values ('hsk3-l10', 'hsk3', 'HSK3', 10, '数学比历史难多了', 'Shùxué bǐ lìshǐ nánduō le', 'Maths is much harder than history', '{"level": "hsk3", "lesson": 10, "book": "HSK3", "title_zh": "数学比历史难多了", "title_pinyin": "Shùxué bǐ lìshǐ nánduō le", "title_en": "Maths is much harder than history", "textbook": {"ref": {"book": "textbook", "pages": [97, 98, 99, 100, 101, 102, 103, 104, 105]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①历史 lìshǐ", "②体育 tǐyù", "③个子 gèzi", "④车站 chēzhàn", "⑤数学 shùxué", "⑥自行车 zìxíngchē"], "pictures_desc_en": ["A: a white mountain bike standing on a grass lawn", "B: a green chalkboard covered with maths formulas (E=mc², functions, geometric figures)", "C: an old book titled “HISTORY” with a compass, a globe and a quill pen", "D: a little boy in a blue T-shirt and jeans with his hand on top of his head as if showing his height", "E: a bus stop shelter with a bus sign by a field", "F: various sports balls (basketball, football, American football, baseball, tennis ball) and a tennis racket"]}, {"instruction_zh": "写出下列词语的反义词", "instruction_en": "Write down the antonym of each of the following words.", "items": ["例如：大—小", "新 xīn—________", "高 gāo—________", "难 nán—________", "远 yuǎn—________", "贵 guì—________", "胖 pàng—________"]}], "texts": [{"n": 1, "title_zh": "在教室", "title_en": "In the classroom", "kind": "dialogue", "audio": "hsk3-textbook-1001.mp3", "lines": [{"speaker": "朋友", "zh": "大山，你和马可谁个子高？", "pinyin": "Dàshān, nǐ hé Mǎkě shéi gèzi gāo?"}, {"speaker": "大山", "zh": "马可比我高，我比马可矮一点儿。", "pinyin": "Mǎkě bǐ wǒ gāo, wǒ bǐ Mǎkě ǎi yìdiǎnr."}, {"speaker": "朋友", "zh": "那你们谁大？", "pinyin": "Nà nǐmen shéi dà?"}, {"speaker": "大山", "zh": "我比马可大两岁。", "pinyin": "Wǒ bǐ Mǎkě dà liǎng suì."}, {"speaker": "朋友", "zh": "你们谁的汉语说得更好？", "pinyin": "Nǐmen shéi de Hànyǔ shuō de gèng hǎo?"}, {"speaker": "大山", "zh": "马可比我说得好一些，我的汉语没有他好。", "pinyin": "Mǎkě bǐ wǒ shuō de hǎo yìxiē, wǒ de Hànyǔ méiyǒu tā hǎo."}], "new_words": [{"n": 1, "zh": "个子", "pinyin": "gèzi", "pos": "n.", "en": "height, stature", "text": 1}, {"n": 2, "zh": "矮", "pinyin": "ǎi", "pos": "adj.", "en": "short", "text": 1}]}, {"n": 2, "title_zh": "在教室", "title_en": "In the classroom", "kind": "dialogue", "audio": "hsk3-textbook-1002.mp3", "lines": [{"speaker": "小明", "zh": "我喜欢历史课、体育课，不喜欢数学课。", "pinyin": "Wǒ xǐhuan lìshǐ kè, tǐyù kè, bù xǐhuan shùxué kè."}, {"speaker": "同学", "zh": "为什么？数学也很有意思啊。", "pinyin": "Wèi shénme? Shùxué yě hěn yǒu yìsi a."}, {"speaker": "小明", "zh": "我觉得数学比历史难多了，我听不懂。", "pinyin": "Wǒ juéde shùxué bǐ lìshǐ nánduō le, wǒ tīng bu dǒng."}, {"speaker": "同学", "zh": "别担心，我可以帮你。", "pinyin": "Bié dān xīn, wǒ kěyǐ bāng nǐ."}, {"speaker": "小明", "zh": "好啊，我们每天学多长时间？", "pinyin": "Hǎo a, wǒmen měi tiān xué duō cháng shíjiān?"}, {"speaker": "同学", "zh": "一两个小时吧。", "pinyin": "Yì-liǎng ge xiǎoshí ba."}], "new_words": [{"n": 3, "zh": "历史", "pinyin": "lìshǐ", "pos": "n.", "en": "history", "text": 2}, {"n": 4, "zh": "体育", "pinyin": "tǐyù", "pos": "n.", "en": "P.E., sports", "text": 2}, {"n": 5, "zh": "数学", "pinyin": "shùxué", "pos": "n.", "en": "maths", "text": 2}]}, {"n": 3, "title_zh": "在休息室", "title_en": "In the lounge", "kind": "dialogue", "audio": "hsk3-textbook-1003.mp3", "lines": [{"speaker": "同事", "zh": "你最近比以前来得早多了，搬家了？", "pinyin": "Nǐ zuìjìn bǐ yǐqián lái de zǎoduō le, bān jiā le?"}, {"speaker": "小丽", "zh": "是啊，你不知道？我上个月就搬家了，走路二十分钟就到。", "pinyin": "Shì a, nǐ bù zhīdào? Wǒ shàng ge yuè jiù bān jiā le, zǒu lù èrshí fēnzhōng jiù dào."}, {"speaker": "同事", "zh": "那很方便啊。", "pinyin": "Nà hěn fāngbiàn a."}, {"speaker": "小丽", "zh": "我还打算买辆自行车，骑车七八分钟就能到。", "pinyin": "Wǒ hái dǎsuàn mǎi liàng zìxíngchē, qí chē qī-bā fēnzhōng jiù néng dào."}, {"speaker": "同事", "zh": "你不是有一辆吗？", "pinyin": "Nǐ bú shì yǒu yí liàng ma?"}, {"speaker": "小丽", "zh": "那辆太旧了，要换一辆，很便宜，两三百块钱。", "pinyin": "Nà liàng tài jiù le, yào huàn yí liàng, hěn piányi, liǎng-sān bǎi kuài qián."}], "new_words": [{"n": 6, "zh": "方便", "pinyin": "fāngbiàn", "pos": "adj.", "en": "convenient", "text": 3}, {"n": 7, "zh": "自行车", "pinyin": "zìxíngchē", "pos": "n.", "en": "bicycle", "text": 3}, {"n": 8, "zh": "骑", "pinyin": "qí", "pos": "v.", "en": "to ride", "text": 3}, {"n": 9, "zh": "旧", "pinyin": "jiù", "pos": "adj.", "en": "old, used, worn", "text": 3}, {"n": 10, "zh": "换", "pinyin": "huàn", "pos": "v.", "en": "to change, to substitute", "text": 3}]}, {"n": 4, "title_zh": "在看房子", "title_en": "Seeing an apartment", "kind": "dialogue", "audio": "hsk3-textbook-1004.mp3", "lines": [{"speaker": "大山", "zh": "这两个地方的房子一样吗？", "pinyin": "Zhè liǎng ge dìfang de fángzi yíyàng ma?"}, {"speaker": "中介", "zh": "不一样。您看，学校外边的房子比学校里边的大一些。", "pinyin": "Bù yíyàng. Nín kàn, xuéxiào wàibian de fángzi bǐ xuéxiào lǐbian de dà yìxiē."}, {"speaker": "大山", "zh": "大小没关系，主要是环境，哪个更安静？", "pinyin": "Dàxiǎo méi guānxi, zhǔyào shì huánjìng, nǎge gèng ānjìng?"}, {"speaker": "中介", "zh": "学校里边的没有学校外边的那么安静。", "pinyin": "Xuéxiào lǐbian de méiyǒu xuéxiào wàibian de nàme ānjìng."}, {"speaker": "大山", "zh": "哪个方便一些呢？", "pinyin": "Nǎge fāngbiàn yìxiē ne?"}, {"speaker": "中介", "zh": "学校里边比学校外边方便，附近有三四个车站。", "pinyin": "Xuéxiào lǐbian bǐ xuéxiào wàibian fāngbiàn, fùjìn yǒu sān-sì ge chēzhàn."}], "new_words": [{"n": 11, "zh": "地方", "pinyin": "dìfang", "pos": "n.", "en": "place", "text": 4}, {"n": 12, "zh": "中介", "pinyin": "zhōngjiè", "pos": "n.", "en": "intermediary, agent", "text": 4, "star": true}, {"n": 13, "zh": "主要", "pinyin": "zhǔyào", "pos": "adj.", "en": "main", "text": 4}, {"n": 14, "zh": "环境", "pinyin": "huánjìng", "pos": "n.", "en": "environment", "text": 4}, {"n": 15, "zh": "附近", "pinyin": "fùjìn", "pos": "n.", "en": "nearby, vicinity", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "比较句2：A比B＋Adj＋一点儿／一些／得多／多了", "title_en": "Comparative Sentences 2: A比B + Adj + 一点儿/一些/得多/多了", "explanation_zh": "“一点儿”“一些”“得多”“多了”等词可以用于“比”字句中形容词的后边，表示事物之间的差别程度，“一点儿”和“一些”表示差别的程度不大，“得多”和“多了”表示差别的程度很大。例如：（1）–（4）\n否定形式为“A没有B（＋这么／那么）＋Adj”，例如：（5）–（8）", "explanation_en": "“一点儿”, “一些”, “得多” or “多了” etc. can follow an adjective in a comparative sentence, indicating the degree of difference between things, among which “一点儿” and “一些” indicate a slight difference, while “得多” and “多了” indicate a big difference. For example: (1)–(4)\nThe negative form is “A没有B (+ 这么/那么) + Adj”. For example: (5)–(8)", "structure_rows": ["A比B＋Adj＋一点儿／一些／得多／多了", "A没有B（＋这么／那么）＋Adj"], "examples": [{"n": 1, "zh": "大山比大卫矮一点儿。"}, {"n": 2, "zh": "我今天起得比昨天晚一些。"}, {"n": 3, "zh": "今天的作业比昨天多得多。"}, {"n": 4, "zh": "数学比历史难多了。"}, {"n": 5, "zh": "咖啡没有茶好喝。"}, {"n": 6, "zh": "他没有我这么高。"}, {"n": 7, "zh": "这个电影没有那个电影那么有意思。"}, {"n": 8, "zh": "学校里边的（房子）没有学校外边的那么安静。"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "今天的天气比________。"}, {"n": 2, "zh": "我做的饭没有________。"}, {"n": 3, "zh": "骑自行车________。"}]}, {"n": 2, "title_zh": "概数的表达1", "title_en": "Expression of Approximate Numbers 1", "explanation_zh": "汉语中，相邻两个数词连用可以表达概数。如“一二（两）、两三、三四、五六、七八、八九”等。例如：", "explanation_en": "In Chinese, two adjacent numerals can be used together to indicate an approximate number, for example, “一二（两）(one or two)”, “两三 (two or three)”, “三四 (three or four)”, “五六 (five or six)”, “七八 (seven or eight)”, and “八九 (eight or nine)”. For example:", "structure_rows": ["一二（两）、两三、三四、五六、七八、八九"], "examples": [{"n": 1, "zh": "我每天学习一两个小时汉语。"}, {"n": 2, "zh": "你都喝了三四杯咖啡了，别再喝了！"}, {"n": 3, "zh": "从小丽家到公司骑车七八分钟就能到。"}, {"n": 4, "zh": "学校里边比学校外边方便，附近有三四个车站。"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "这辆自行车________。"}, {"n": 2, "zh": "今天的作业我________能做完。"}, {"n": 3, "zh": "我有________条黑色的裤子。"}]}], "exercises": [{"n": 1, "type_zh": "朗读", "instruction_zh": "朗读下列短语和句子", "instruction_en": "Read the following phrases and sentences aloud.", "audio": "hsk3-textbook-1005.mp3", "items": [{"n": 1, "zh": "历史：历史课／中国历史／历史很长／数学比历史难多了。"}, {"n": 2, "zh": "自行车：一辆自行车／骑自行车／这辆自行车太旧了／我还打算买辆自行车。"}, {"n": 3, "zh": "换：换钱／换手机／换班／我要换一辆自行车。"}, {"n": 4, "zh": "环境：环境很好／学校环境／环境问题／哪个环境更安静？"}, {"n": 5, "zh": "附近：学校附近／附近的超市／我住在附近／学校附近有三四个车站。"}]}, {"n": 2, "type_zh": "选词填空", "instruction_zh": "选择恰当的词语填空", "instruction_en": "Choose the proper words to fill in the blanks.", "word_bank": [["安静", "体育", "个子", "旧", "骑"], ["方便", "数学", "换", "附近", "地方"]], "items": [{"n": 1, "zh": "我________比他高一点儿。"}, {"n": 2, "zh": "我每天________车来学校。"}, {"n": 3, "zh": "我最喜欢________课，多有意思啊。"}, {"n": 4, "zh": "我喜欢住在这儿，主要是觉得这儿很________。"}, {"n": 5, "zh": "这条裤子太________了，再买一条吧。"}, {"n": 6, "zh": "A：我觉得你的比我的好。 B：你想要这个吗？没问题，我跟你________。"}, {"n": 7, "zh": "A：你哪天比较________，我们见面聊聊天儿？ B：周末吧，来我家吃饭。"}, {"n": 8, "zh": "A：这个________的天气怎么样？ B：非常好，夏天一点儿也不热。"}, {"n": 9, "zh": "A：请问，这儿________有超市吗？ B：有，一直往前走就是。"}, {"n": 10, "zh": "A：你怎么不太高兴？ B：我________考得不好。"}]}, {"n": 3, "type_zh": "完成对话", "instruction_zh": "用本课新学的语言点和词语完成对话", "instruction_en": "Complete the dialogues using the newly-learned language points and words.", "items": [{"n": 1, "zh": "A：你和妈妈谁起得早？ B：________。 A：她比你________起多长时间？ B：________。", "picture_desc_en": "A smiling young woman sitting up in a bed with white sheets, stretching and rubbing one eye as if just woken up."}, {"n": 2, "zh": "A：今天我们班来了多少学生？ B：今天来了________个学生。 A：昨天呢？ B：昨天比今天来得________。", "picture_desc_en": "A teacher standing in front of a classroom full of students seated at desks, some of them raising their hands."}, {"n": 3, "zh": "A：你们今天玩儿了多长时间游戏了？ B：玩儿了________了。 A：怎么玩儿了这么长时间？ B：昨天玩儿了三个小时，今天没有________。", "picture_desc_en": "A father and a young son sitting on a sofa, each holding a game controller and playing a video game."}, {"n": 4, "zh": "A：你看这条裤子怎么样？ B：太贵了，要________块钱。 A：那条呢？没有________。 B：我觉得还可以。", "picture_desc_en": "A woman and a man in a clothing shop, each holding up a pair of blue jeans."}]}, {"n": 4, "type_zh": "回答问题", "instruction_zh": "根据课文回答问题", "instruction_en": "Answer the questions according to the texts.", "items": [{"n": 1, "zh": "马可和大山谁高？谁年龄大？谁的汉语说得好？"}, {"n": 2, "zh": "小明为什么不喜欢数学课？"}, {"n": 3, "zh": "小明和同学打算每天一起做什么？做多长时间？"}, {"n": 4, "zh": "小丽为什么比以前来得早了？"}, {"n": 5, "zh": "小丽为什么要买自行车？"}, {"n": 6, "zh": "住在学校里边和学校外边有什么不一样？"}]}], "characters": {"knowledge_title_zh": "旧字新词", "knowledge_zh": "读读下面的词语，想想组成的新词是什么意思。", "knowledge_en": "Read the following words and guess the meanings of the newly-formed ones.", "word_game": [{"parts": ["换", "季节"], "result": "换季"}, {"parts": ["地方", "上面"], "result": "地面"}, {"parts": ["主要", "菜"], "result": "主菜"}], "confusable_pairs": [["自", "白"], ["更", "史"], ["育", "有"], ["数", "楼"], ["骑", "椅"]]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，询问对方今年是否做过下列事情，做过多少次。用概数表达法回答。", "instruction_en": "Work in pairs. Ask your partner whether or not he/she has done the following things this year, and how many times he/she has done them. Answer the questions using approximate numbers.", "example_zh": ["表格：| 事情 | 对方做过几次 |", "| 爬山 | 爬过两三次 |", "| 参加比赛 | |", "| 听音乐会 | |", "| 逛公园 | |", "| 旅游 | |", "| 上课迟到 | |"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，通过比较，为每个人找到程度最高的方面。使用“A比B＋Adj＋一点儿／一些／得多／多了”和“A没有B（＋这么／那么）＋Adj”。", "instruction_en": "Work in groups of 3-4. Compare and find each person’s most distinguishing aspect, using “A比B + Adj + 一点儿/一些/得多/多了” and “A没有B (+ 这么/那么) + Adj”.", "example_zh": ["例如：A：我每天听歌听半个小时。", "B：我听歌的时间比A长得多，我听三个小时。", "C：我听歌的时间没有B那么长。", "D：我听歌的时间比B长一点儿，我听三个半小时。", "D听歌的时间最长。", "提示：学习的时间　看过的电影　旅游去过的地方　游泳游得远　作业写得快", "表格：| 谁 | 最…… |"]}], "saying": {"zh": "不可同日而语", "pinyin": "Bù kě tóngrì’éryǔ", "en": "The two cannot be mentioned in the same breath", "explanation_zh": "“不可同日而语”的意思是不能放在同一个时间谈论，用来比喻差别很大，不能放在一起比较。例如：通信技术进步太快了，过去跟现在不可同日而语。", "explanation_en": "“不可同日而语”, literally “(two things) cannot be mentioned in the same breath”, is used metaphorically to mean that there is no comparison between two people or two things because of the significant difference. For instance, in terms of science and technology, there is no comparison between the past and the present."}, "culture": {"title_zh": "中国人结婚时穿什么", "body_zh": "以前中国人结婚时，新娘穿传统的红色旗袍。现在新娘既穿红色旗袍，也穿白色的婚纱，这表现了中国文化和西方文化的融合。在你们国家，人们结婚时穿什么呢？", "body_en": "What Chinese People Wear on Their Wedding Day. In the past, brides in China wore traditional red cheongsams on their wedding days, and now they wear both red cheongsams and white wedding gowns, which mirrors that Chinese and Western cultures have been blended together. What do people wear on their wedding days in your country?"}}, "teacher": {"ref": {"book": "teacher", "pages": [71, 72, 73, 74, 75, 76, 77]}, "objectives_zh": ["重点词语：学生能够熟练掌握：“骑、换、地方、主要、环境、附近”的词义和用法", "语言点：学生能够了解并掌握：（1）“A比B＋形容词＋一点儿／一些／得多／多了”表示事物之间的差别程度（2）两个数词连用表达概数", "汉字：学生能够：根据已学生词猜测出3个旧字新词“换季、地面、主菜”的意思", "功能：学生能够：（1）根据两者之间的差别程度使用比较句（2）描述大概的数量"], "steps": [{"title_zh": "复习旧课", "body_zh": "1 教师展示第9课的热身图片，请学生根据图片说出生词。\n2 教师根据第9课的内容进行提问。\n（1）你学了多长时间汉语了？现在怎么样？\n（2）听、说、读、写都一样难吗？哪个容易？哪个难？\n（3）公共汽车很长时间不来，你会觉得怎么样？\n（4）你的爱好是什么？你妈妈呢？你们一样吗？\n（5）我们班有没有一样高的同学？说说他们是谁。"}, {"title_zh": "学习新课 1 热身", "body_zh": "热身1：教师可依次朗读热身部分的词语，要求学生集体或单个说出图片对应的编号，教师评判正误；最后全体学生再次齐读热身环节的所有词语，要求语音标准、声调准确。\n答案：①C　②F　③D　④E　⑤B　⑥A\n热身2：可留至语言点（1）“比较句2：A比B＋形容词＋一点儿／一些／得多／多了”导入时使用。"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n个子、矮、历史、体育、数学、方便、自行车、骑、旧、换、地方、中介、主要、环境、附近\n· 教师先带领学生快速认读一遍生词；\n· 取消拼音，带领学生再次认读；\n· 请单个学生独自认读2-3个生词；\n· 最后全班再快速认读所有的生词。\n（2）生词讲解方式\n· 直观法（如图片、照片、实物等）展示：个子、历史、体育、数学、自行车\n· 对比法展示：高—矮、新—旧\n· 启发式引导：方便\n教师给出句子部分内容让学生进行补充，如：他家楼下有一家超市，所以买东西很方便。\n（3）重点生词扩展及常用搭配\n骑—骑自行车—你会骑自行车吗？\n换—换一辆自行车—换一个手机—旧书换新书\n地方—这个地方—什么地方—每个地方都很漂亮。\n主要—主要学习语法—现在天气越来越不好，主要是环境的问题。\n环境—环境很好—公司的环境—学习环境—我们学校的学习环境很不错。\n附近—我家附近—附近的环境—请问，这儿附近有超市吗？\n练习册相关练习：P64／一／第一部分，P67／二／第二部分"}, {"title_zh": "3 语言点（1）比较句2：A比B＋形容词＋一点儿／一些／得多／多了", "body_zh": "① 语言点解析\n“一点儿”“一些”“得多”“多了”等词可以用于“比”字句中形容词的后边，表示事物之间的差别程度，“一点儿”和“一些”表示差别的程度不大，“得多”和“多了”表示差别的程度很大，否定形式为“A没有B（＋这么／那么）＋形容词”。\n［框］A比B＋形容词＋一点儿\n［框］A比B＋形容词＋一些\n［框］A比B＋形容词＋得多\n［框］A比B＋形容词＋多了\n［框］A没有B（这么／那么）＋形容词\n② 语言点导入\n教师可利用本课热身2导入语言点。\n教师请学生完成填空，复习以前学过的形容词。\n答案：新—旧　高—低　难—容易　远—近　贵—便宜　胖—瘦\n教师给出情景，引导学生说出本课的目标句：\n教师：大卫1米9，小丽1米5，他们谁高？\n学生：大卫比小丽高。\n教师：大卫比小丽高一点儿还是高多了？\n学生：大卫比小丽高多了。\n③ 语言点操练\n教师给出情景，练习四种形式的比较句及其否定形式。\n例如：\n这个本子20块，那个本子18块。\n学生：这个本子比那个本子贵一点儿。\n　　　这个本子比那个本子贵一些。\n　　　那个本子没有这个本子贵。\n这本书89块，那本书18块。\n学生：这本书比那本书贵多了。\n　　　这本书比那本书贵得多。\n　　　那本书没有这本书贵。\n④ 语言点扩展练习\n教师可根据学生实际情况进行问答练习。\n你觉得历史难还是数学难？\n你觉得今天的作业多还是昨天的作业多？\n你觉得可乐好喝还是咖啡好喝？\n注意：本句型中的形容词前一般不能再有程度副词的修饰。"}, {"title_zh": "3 语言点（2）概数的表达", "body_zh": "① 语言点解析\n相邻两个数词连用可以表达概数，例如“三四个”表示“三个或者四个”。\n② 语言点导入\n教师就地取材，收集几本学生的汉语书，引导学生说出目标句：\n教师：（不给学生看清楚具体多少本）这是多少本汉语书？\n学生1：六本。\n学生2：七本。\n教师：六本或者七本，老师有六七本汉语书。\n③ 语言点操练\n教师给出情景，请学生完成句子。\n例如：楼下有八辆或者九辆自行车。——楼下有八九辆自行车。\n　　　这些东西要三十或者四十块钱。\n　　　他买了四瓶或者五瓶牛奶。\n④ 语言点扩展练习\n教师提问，请学生用概数回答。\n你昨天学习了多长时间？\n你昨晚睡了几个小时？\n你现在身上有多少钱？\n注意：相邻的两个数字如果是“九十”则表示确定的数“90”，而不是概数。"}, {"title_zh": "4 课文 课文1", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n大山和马可谁高？——马可比大山高一点儿。\n大山和马可谁大？——大山比马可大两岁。\n大山和马可谁的汉语说得更好？——马可比大山说得更好一些。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：……，你和……个子高？\nB：……比我高，我比……。\nA：那你们……？\nB：我比……。\nA：你们谁……？\nB：……比我……，我的……。"}, {"title_zh": "4 课文 课文2", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的喜欢什么课？——他喜欢历史课、体育课。\n男的为什么不喜欢数学课？——他觉得数学比历史难多了。\n他们要每天一起学多长时间？——他们要每天一起学一两个小时。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：我喜欢……，不喜欢……。\nB：为什么？……也……。\nA：我觉得……，我……。\nB：别……，我可以……。\nA：好，我们每天……？\nB：……吧。"}, {"title_zh": "4 课文 课文3", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n女的为什么比以前来得早多了？——因为她搬家了，走路二十分钟就到。\n女的打算买什么？——她打算买一辆自行车。\n换自行车贵不贵？多少钱？——不贵，很便宜，两三百块钱。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）教师给提示词，带领学生复述课文。\n提示词：最近、比、搬家、方便、自行车、换、便宜"}, {"title_zh": "4 课文 课文4", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n哪个房子大一些？——学校外边的房子比学校里边的大一些。\n男的觉得什么很重要？——他觉得环境更重要。\n哪个房子更方便？——学校里边的房子比学校外边的方便一些。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）教师给提示词，带领学生复述课文。\n提示词：房子、一样、大、环境、安静、方便、车站\n练习册相关练习：第70页／四"}, {"title_zh": "5 汉字", "body_zh": "旧字新词：\n① 教师领读以前学过的词语和新词，并让学生猜猜新词的意思。\n· 领读：换、季节、换季\n问学生：“换季”是什么意思？——换季节，季节变了。\n· 领读：地方、上面、地面\n问学生：“地面”是什么意思？——地的上面。\n扩展提问：地面的下边怎么说？——地下。（根据实际情况选用）\n· 领读：主要、菜、主菜\n问学生：“主菜”是什么意思？——吃饭的时候，主要吃的菜。\n② 教师领读新词扩展，通过情景，理解新词的意思和用法。\n换季：换季了／换季的衣服／什么时候换季？\n地面：地面上／地面上很干净／昨天下雨了，现在地面上有很多水。\n主菜：不吃主菜／今天的主菜是什么？／今天的主菜很好吃。\n汉字辨认练习：\n辨认下列汉字并组词。\n自：________、________　白：________、________\n更：________、________　史：________、________\n育：________、________　有：________、________\n数：________、________　楼：________、________\n骑：________、________　椅：________、________\n练习册相关练习：第70页／三／第三部分"}, {"title_zh": "6 补充课堂活动——我来做，你来猜", "body_zh": "活动规则：A、B两个同学一组到教室前边完成，教师给A同学和其他同学出示词语卡片，B同学不能看。A同学要用动作表演出卡片上词语的内容，B同学根据A同学的表演猜出这个词语是什么，并用这个词语说一个句子。\n参考词语：个子、矮、体育、历史、数学、骑自行车、换手机、三四块钱……"}, {"title_zh": "7 俗语", "body_zh": "教师引导学生理解俗语的含义，注意这里的“语”是“说”的意思，这句俗语的意思主要是强调变化大、变化快。"}, {"title_zh": "8 本课小结", "body_zh": "· 语言点：用“A比B＋形容词＋一点儿／一些／得多／多了”表示差异程度\n　　　　　用相邻数词表示概数\n· 汉　字：旧字新词：换季、地面、主菜"}, {"title_zh": "文化：中国人结婚时穿什么", "body_zh": "1 文化点解析\n① 中国人崇尚红色，因为它象征着喜庆和活力，所以传统的婚礼服饰是红色的，逢年过节，人们也喜欢用红色来进行装饰。\n② 中国人与西方人对颜色的看法不同，中国人相信主管杀戮的神是白虎神，认为白色象征着死亡、凶险。但是西方人却认为白色象征着纯洁、高雅，因此西方人结婚时喜欢穿白色的婚纱。\n③ 西方人穿白色婚纱的习俗在一百多年前传入中国，并被许多中国人接受，因此，我们现在也经常看到中国新娘结婚时穿白色的婚纱，这表现了中国文化和西方文化的融合。\n2 文化点参考处理方式\n· 教师介绍中国人的思想观念中红色和白色的象征意义。\n· 请学生说说自己国家的思想观念中，红色和白色的象征意义。\n· 教师请学生说说其他中国文化和西方文化融合的例子。"}], "notes_zh": ["注意：本句型中的形容词前一般不能再有程度副词的修饰。（语言点1）", "注意：相邻的两个数字如果是“九十”则表示确定的数“90”，而不是概数。（语言点2）", "扩展提问：地面的下边怎么说？——地下。（根据实际情况选用）（汉字·旧字新词）", "注意这里的“语”是“说”的意思，这句俗语的意思主要是强调变化大、变化快。（俗语）"], "warmup_answers_zh": ["热身1 答案：①C　②F　③D　④E　⑤B　⑥A", "热身2：可留至语言点（1）导入时使用。答案：新—旧　高—低　难—容易　远—近　贵—便宜　胖—瘦"], "text_questions": [{"text": 1, "q_zh": "大山和马可谁高？", "a_zh": "马可比大山高一点儿。"}, {"text": 1, "q_zh": "大山和马可谁大？", "a_zh": "大山比马可大两岁。"}, {"text": 1, "q_zh": "大山和马可谁的汉语说得更好？", "a_zh": "马可比大山说得更好一些。"}, {"text": 2, "q_zh": "男的喜欢什么课？", "a_zh": "他喜欢历史课、体育课。"}, {"text": 2, "q_zh": "男的为什么不喜欢数学课？", "a_zh": "他觉得数学比历史难多了。"}, {"text": 2, "q_zh": "他们要每天一起学多长时间？", "a_zh": "他们要每天一起学一两个小时。"}, {"text": 3, "q_zh": "女的为什么比以前来得早多了？", "a_zh": "因为她搬家了，走路二十分钟就到。"}, {"text": 3, "q_zh": "女的打算买什么？", "a_zh": "她打算买一辆自行车。"}, {"text": 3, "q_zh": "换自行车贵不贵？多少钱？", "a_zh": "不贵，很便宜，两三百块钱。"}, {"text": 4, "q_zh": "哪个房子大一些？", "a_zh": "学校外边的房子比学校里边的大一些。"}, {"text": 4, "q_zh": "男的觉得什么很重要？", "a_zh": "他觉得环境更重要。"}, {"text": 4, "q_zh": "哪个房子更方便？", "a_zh": "学校里边的房子比学校外边的方便一些。"}], "summary_zh": "语言点：用“A比B＋形容词＋一点儿／一些／得多／多了”表示差异程度；用相邻数词表示概数。汉字：旧字新词：换季、地面、主菜。"}, "workbook": {"ref": {"book": "workbook", "pages": [68, 69, 70, 71, 72, 73, 74]}, "answers_ref": {"book": "teacher", "pages": [170, 171, 172]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 1-5: Choose the right picture for each dialogue you hear.", "audio": "hsk3-workbook-10-part1.mp3", "items": [{"n": "例", "zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "transcript_zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "options": {"A": "[picture] many children running and playing on a sports ground (with pitch lines) in front of a school building", "B": "[picture] people clinking glasses at a restaurant table (a young woman and an older couple)", "C": "[picture] a female teacher at a blackboard (with a triangle and formulas) explaining to a girl student, another student seated in the foreground", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man in glasses talking on a mobile phone and covering one ear, beside a road with heavy traffic", "F": "[picture] a salesman in a suit talking with a young couple next to a car in a car showroom"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [68]}}, {"n": 1, "zh": "", "options": {"A": "[picture] many children running and playing on a sports ground (with pitch lines) in front of a school building", "B": "[picture] people clinking glasses at a restaurant table (a young woman and an older couple)", "C": "[picture] a female teacher at a blackboard (with a triangle and formulas) explaining to a girl student, another student seated in the foreground", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man in glasses talking on a mobile phone and covering one ear, beside a road with heavy traffic", "F": "[picture] a salesman in a suit talking with a young couple next to a car in a car showroom"}, "transcript_zh": "男：妈，你看，给笑笑讲题的那个就是我们班数学老师。 女：她个子真高，讲得怎么样？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 2, "zh": "", "options": {"A": "[picture] many children running and playing on a sports ground (with pitch lines) in front of a school building", "B": "[picture] people clinking glasses at a restaurant table (a young woman and an older couple)", "C": "[picture] a female teacher at a blackboard (with a triangle and formulas) explaining to a girl student, another student seated in the foreground", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man in glasses talking on a mobile phone and covering one ear, beside a road with heavy traffic", "F": "[picture] a salesman in a suit talking with a young couple next to a car in a car showroom"}, "transcript_zh": "女：喂，你听得见我说话吗？ 男：喂，喂，你等一会儿，我找个安静点儿的地方再跟你说。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 3, "zh": "", "options": {"A": "[picture] many children running and playing on a sports ground (with pitch lines) in front of a school building", "B": "[picture] people clinking glasses at a restaurant table (a young woman and an older couple)", "C": "[picture] a female teacher at a blackboard (with a triangle and formulas) explaining to a girl student, another student seated in the foreground", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man in glasses talking on a mobile phone and covering one ear, beside a road with heavy traffic", "F": "[picture] a salesman in a suit talking with a young couple next to a car in a car showroom"}, "transcript_zh": "男：谢谢你们请我们吃饭，这家饭馆的环境真好，菜也很好吃，特别是主菜。 女：我很高兴你们喜欢这个地方，下次我们再来。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 4, "zh": "", "options": {"A": "[picture] many children running and playing on a sports ground (with pitch lines) in front of a school building", "B": "[picture] people clinking glasses at a restaurant table (a young woman and an older couple)", "C": "[picture] a female teacher at a blackboard (with a triangle and formulas) explaining to a girl student, another student seated in the foreground", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man in glasses talking on a mobile phone and covering one ear, beside a road with heavy traffic", "F": "[picture] a salesman in a suit talking with a young couple next to a car in a car showroom"}, "transcript_zh": "女：听说你们店可以用旧车换新车？ 男：对，这边请，我来给您介绍一下吧。您有旧车吗？", "answer": "F", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 5, "zh": "", "options": {"A": "[picture] many children running and playing on a sports ground (with pitch lines) in front of a school building", "B": "[picture] people clinking glasses at a restaurant table (a young woman and an older couple)", "C": "[picture] a female teacher at a blackboard (with a triangle and formulas) explaining to a girl student, another student seated in the foreground", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man in glasses talking on a mobile phone and covering one ear, beside a road with heavy traffic", "F": "[picture] a salesman in a suit talking with a young couple next to a car in a car showroom"}, "transcript_zh": "男：看，那么多人踢足球，他们在比赛吗？ 女：不是，他们在上体育课呢。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听句子，判断对错", "instruction_en": "Questions 6-10: Decide whether the statements are true or false based on the sentences you hear.", "audio": "hsk3-workbook-10-part2.mp3", "items": [{"n": "例1", "zh": "他希望自己很健康。", "transcript_zh": "为了让自己更健康，他每天都花一个小时去锻炼身体。", "answer": "√", "answer_ref": {"book": "workbook", "pages": [69]}}, {"n": "例2", "zh": "那块儿手表不是他的。", "transcript_zh": "今天我想早点儿回家。看了看手表，才5点。过了一会儿再看表，还是5点，我这才发现我的手表不走了。", "answer": "×", "answer_ref": {"book": "workbook", "pages": [69]}}, {"n": 6, "zh": "今天比昨天冷得多。", "transcript_zh": "地面上怎么都是雪？昨天我女朋友还穿裙子呢，今天怎么就下雪了？", "answer": "√", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 7, "zh": "他们要回家了。", "transcript_zh": "走，找个环境好的地方，我早就想跟你聊聊了，这儿附近有没有安静点儿的咖啡店？", "answer": "×", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 8, "zh": "爸爸很健康，因为他喜欢运动。", "transcript_zh": "我爸爸身体那么好，主要是因为每天锻炼。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 9, "zh": "他每天工作很累。", "transcript_zh": "我每天工作八九个小时，中午也不能休息，能不累吗？", "answer": "√", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 10, "zh": "以前儿子不喜欢学习。", "transcript_zh": "我儿子的学习比以前好多了，主要是他有兴趣了。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听短对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the short dialogues and choose the right answers.", "audio": "hsk3-workbook-10-part3.mp3", "items": [{"n": "例", "zh": "男的想让小王做什么？", "transcript_zh": "男：小王，帮我开一下门，好吗？谢谢！ 女：没问题。您去超市了？买了这么多东西。 问：男的想让小王做什么？", "options": {"A": "开门", "B": "拿东西", "C": "去超市买东西"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [69]}}, {"n": 11, "zh": "女的是什么意思？", "options": {"A": "买两个", "B": "买三个", "C": "少买一点儿"}, "transcript_zh": "男：前边有卖水果的，我们买点儿苹果吧？ 女：现在是换季的时候，苹果不一定好吃，别买太多，买两三个就行。 问：女的是什么意思？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 12, "zh": "女的现在怎么样了？", "options": {"A": "好点儿了", "B": "好多了", "C": "越来越不好"}, "transcript_zh": "男：今天怎么样？还发烧吗？ 女：吃了药比昨天好一些了，但还头疼。 问：女的现在怎么样了？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 13, "zh": "小刚和方明谁高？", "options": {"A": "小刚", "B": "方明", "C": "一样高"}, "transcript_zh": "女：小刚，方明高还是你高？ 男：他个子也不高，只比我高一点儿。 问：小刚和方明谁高？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 14, "zh": "他们可能在哪儿？", "options": {"A": "飞机上", "B": "电影院", "C": "火车上"}, "transcript_zh": "男：怎么还没到？我都看了三四个电影了。 女：我们是从中国到美国，还要再飞五六个小时。你睡一会儿，或者再看几个电影。 问：他们可能在哪儿？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 15, "zh": "这个地方有几个姓王的老师？", "options": {"A": "三个", "B": "三十个", "C": "很多"}, "transcript_zh": "女：喂，您好，请找一下王老师。 男：我们这儿有三四个姓王的老师呢，您找哪一个？ 问：这个地方有几个姓王的老师？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "一、听力 第四部分", "type_zh": "听力 第四部分", "instruction_zh": "第16–20题：听长对话，选择正确答案", "instruction_en": "Questions 16-20: Listen to the dialogues and choose the right answers.", "audio": "hsk3-workbook-10-part4.mp3", "items": [{"n": "例", "zh": "男的在做什么？", "transcript_zh": "女：晚饭做好了，准备吃饭了。 男：等一会儿，比赛还有三分钟就结束了。 女：快点儿吧，一起吃，菜冷了就不好吃了。 男：你先吃，我马上就看完了。 问：男的在做什么？", "options": {"A": "洗澡", "B": "吃饭", "C": "看电视"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [70]}}, {"n": 16, "zh": "关于男的，可以知道什么？", "options": {"A": "可能骑自行车", "B": "可能坐公共汽车", "C": "要去上课"}, "transcript_zh": "女：你要出去吗？ 男：小丽，我问你，去中山南路骑自行车快还是坐公共汽车快？ 女：这个时间，骑车比坐公共汽车快得多。你这么着急，要去上课吗？ 男：不，我要去见女朋友。 问：关于男的，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 17, "zh": "男的是什么意思？", "options": {"A": "明天很冷", "B": "明天是阴天", "C": "下雪时最冷"}, "transcript_zh": "女：明天是晴天还是阴天？ 男：上午下雪，下午就晴了。 女：太好了，明天可以穿我的新裙子了。 男：雪后晴天比下雪时冷得多，你不知道吗？ 问：男的是什么意思？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 18, "zh": "关于男的，可以知道什么？", "options": {"A": "买了一辆旧车", "B": "买的是自行车", "C": "买了五辆车"}, "transcript_zh": "男：我昨天换了辆新车，比那辆旧的舒服多了。 女：又换了？你已经换了四五辆了吧？多少钱？ 男：不贵，一百多。我那辆旧车送给你吧。 女：一百多？自行车啊！ 问：关于男的，可以知道什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 19, "zh": "关于女的和她女儿，可以知道什么？", "options": {"A": "妈妈高得多", "B": "一样高", "C": "女儿高得多"}, "transcript_zh": "男：你女儿个子真高，比你高多了吧？ 女：其实我跟她一样高，只是她比我瘦多了。 男：她今年多大？十七八岁？在哪儿学习呢？ 女：今年十九了，正在国外学习，学历史和数学。 问：关于女的和她女儿，可以知道什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 20, "zh": "他们要做什么？", "options": {"A": "去咖啡店", "B": "听音乐会", "C": "买东西"}, "transcript_zh": "男：走了两三个小时了，还买了这么多东西，真累。我们休息一会儿吧。 女：那就在这儿坐坐，喝点儿水。 男：楼上有个咖啡店，比这儿安静得多，环境也不错，还有音乐。 女：也好，我们上去喝点儿饮料。 问：他们要做什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第21–25题：选择合适的问答", "instruction_en": "Questions 21-25: Match the two parts of the same dialogue.", "items": [{"n": "例", "zh": "你知道怎么去那儿吗？", "options": {"A": "好，你等我一两分钟，我去一下洗手间。", "B": "你怎么在这么远的地方买房子？", "C": "体育比数学容易多了，也有意思多了。", "D": "今天我不上班，我昨天只睡了两三个小时，让我再睡一会儿。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "小方，你跟小丽一样大吗？"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [71]}}, {"n": 21, "zh": "九点半了，你迟到了，快起床。", "options": {"A": "好，你等我一两分钟，我去一下洗手间。", "B": "你怎么在这么远的地方买房子？", "C": "体育比数学容易多了，也有意思多了。", "D": "今天我不上班，我昨天只睡了两三个小时，让我再睡一会儿。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "小方，你跟小丽一样大吗？"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 22, "zh": "我们去买点儿吃的吧，我早就饿了。", "options": {"A": "好，你等我一两分钟，我去一下洗手间。", "B": "你怎么在这么远的地方买房子？", "C": "体育比数学容易多了，也有意思多了。", "D": "今天我不上班，我昨天只睡了两三个小时，让我再睡一会儿。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "小方，你跟小丽一样大吗？"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 23, "zh": "她的生日是五月，我是一月，我比她大一点儿。", "options": {"A": "好，你等我一两分钟，我去一下洗手间。", "B": "你怎么在这么远的地方买房子？", "C": "体育比数学容易多了，也有意思多了。", "D": "今天我不上班，我昨天只睡了两三个小时，让我再睡一会儿。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "小方，你跟小丽一样大吗？"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 24, "zh": "你个子那么高，跑得也快，当然觉得容易。", "options": {"A": "好，你等我一两分钟，我去一下洗手间。", "B": "你怎么在这么远的地方买房子？", "C": "体育比数学容易多了，也有意思多了。", "D": "今天我不上班，我昨天只睡了两三个小时，让我再睡一会儿。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "小方，你跟小丽一样大吗？"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 25, "zh": "虽然远，但是附近有三四个车站，很方便。", "options": {"A": "好，你等我一两分钟，我去一下洗手间。", "B": "你怎么在这么远的地方买房子？", "C": "体育比数学容易多了，也有意思多了。", "D": "今天我不上班，我昨天只睡了两三个小时，让我再睡一会儿。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "小方，你跟小丽一样大吗？"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第26–30题：选择合适的词语填空", "instruction_en": "Questions 26-30: Choose the proper words to fill in the brackets.", "word_bank": [["A 方便", "B 骑", "C 换", "D 地方", "E 声音", "F 旧"]], "items": [{"n": "例", "zh": "她说话的（　）多好听啊！", "options": {"A": "方便", "B": "骑", "C": "换", "D": "地方", "E": "声音", "F": "旧"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [71]}}, {"n": 26, "zh": "这件衣服有点儿（　）了，我不想穿了。", "options": {"A": "方便", "B": "骑", "C": "换", "D": "地方", "E": "声音", "F": "旧"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 27, "zh": "我还没去过那个（　），漂亮吗？好玩儿吗？", "options": {"A": "方便", "B": "骑", "C": "换", "D": "地方", "E": "声音", "F": "旧"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 28, "zh": "你（　）得太快了，慢点儿，小心前边的车。", "options": {"A": "方便", "B": "骑", "C": "换", "D": "地方", "E": "声音", "F": "旧"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 29, "zh": "A：你每天怎么去学校？坐车还是坐地铁？ B：坐地铁更快，也更（　）。", "options": {"A": "方便", "B": "骑", "C": "换", "D": "地方", "E": "声音", "F": "旧"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 30, "zh": "A：这辆车买了十五六年了，总是出问题。 B：那（　）一辆新的吧，车出问题不是件小事儿。", "options": {"A": "方便", "B": "骑", "C": "换", "D": "地方", "E": "声音", "F": "旧"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第31–35题：选择正确答案", "instruction_en": "Questions 31-35: Choose the right answers.", "items": [{"n": "例", "zh": "您是来参加今天会议的吗？您来早了一点儿，现在才八点半。您先进来坐吧。 ★会议最可能几点开始？", "options": {"A": "8点", "B": "8点半", "C": "9点"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [72]}}, {"n": 31, "zh": "每个周末，我们一家人都去公园或远的地方走走、玩儿玩儿。我们不坐公共汽车，也不坐出租车，我们骑自行车去。很多时候，骑车比开车、坐车方便得多，也快得多。最主要是因为骑车对身体好，对环境也好。 ★骑车：", "options": {"A": "没有坐车方便", "B": "对环境很好", "C": "不健康"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 32, "zh": "以前中国有很多茶馆，但现在越来越少，咖啡店越来越多了，人们走累了可以去咖啡店坐坐，喝点儿咖啡，当然也有茶、牛奶和水。这样的咖啡店比以前的茶馆安静得多，环境也更好，大家很喜欢去。 ★咖啡店：", "options": {"A": "没有茶馆多", "B": "不太安静", "C": "环境比茶馆好"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 33, "zh": "我家楼下有一家旧车店，卖“二手”自行车。没有那么多钱买新车的人，可以到这儿来买辆旧的骑骑，特别便宜，也方便。 ★“二手”车的意思是：", "options": {"A": "便宜车", "B": "新车", "C": "旧车"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 34, "zh": "我女儿现在每天都要上历史课、体育课和数学课。她说她最喜欢历史课，因为历史课比数学课和体育课有意思多了。体育课比数学课容易一些，但是没有历史课那么好玩儿。 ★女儿最不喜欢上什么课？", "options": {"A": "数学课", "B": "历史课", "C": "体育课"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 35, "zh": "有时候，我真想回到以前。五年前这个地方比现在安静得多，这儿只有一条路，房子也没有现在多。现在这儿有四五条路，路上都是车，大楼也越来越多，饭馆有二三十个呢！ ★这个地方：", "options": {"A": "以前没有路", "B": "现在有45条路", "C": "现在的路比以前多"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "三、书写 第一部分", "type_zh": "书写 第一部分", "instruction_zh": "第36–40题：连词成句", "instruction_en": "Questions 36-40: Rearrange the words/phrases to make sentences.", "items": [{"n": "例", "zh": "小船　上　一　河　条　有", "answer": "河上有一条小船。", "answer_ref": {"book": "workbook", "pages": [73]}}, {"n": 36, "zh": "这个地方　安静　比　那个地方　一些", "answer": "这个地方比那个地方安静一些。", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 37, "zh": "周经理　都　一两杯　喝　咖啡　每天", "answer": "周经理每天都喝一两杯咖啡。", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 38, "zh": "自行车　快　骑　比　得多　走路", "answer": "骑自行车比走路快得多。", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 39, "zh": "矮　朋友　一点儿　我　比　个子", "answer": "朋友比我个子矮一点儿。", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 40, "zh": "四　五　只有　教室里　个　学生", "answer": "教室里只有四五个学生。", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "三、书写 第二部分", "type_zh": "书写 第二部分", "instruction_zh": "第41–45题：看拼音，写汉字", "instruction_en": "Questions 41-45: Write the characters based on their pinyin.", "items": [{"n": "例", "zh": "没（　）系，别难过，高兴点儿。", "hint_zh": "guān", "answer": "关", "answer_ref": {"book": "workbook", "pages": [73]}}, {"n": 41, "zh": "我们坐公共汽车去吧，我不会（　）自行车。", "hint_zh": "qí", "answer": "骑", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 42, "zh": "这条裙子有点儿瘦，我可以（　）一条吗？", "hint_zh": "huàn", "answer": "换", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 43, "zh": "我喜欢住在这个地方，因为（　）境特别好，最重要的是有很多商店。", "hint_zh": "huán", "answer": "环", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 44, "zh": "这儿（　）近有个学校，每天下午都有很多爸爸妈妈接孩子。", "hint_zh": "fù", "answer": "附", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 45, "zh": "在这个学校，我的工作（　）要是给学生上历史课。", "hint_zh": "zhǔ", "answer": "主", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "三、书写 第三部分", "type_zh": "书写 第三部分", "instruction_zh": "第46–50题：辨认汉字，选择正确的汉字填空", "instruction_en": "Questions 46-50: Distinguish the characters and fill in the blanks.", "items": [{"n": "例", "zh": "我不知道________个地方在________儿。", "hint_zh": "（那、哪）", "answer": "那、哪", "answer_ref": {"book": "workbook", "pages": [74]}}, {"n": 46, "zh": "弟弟新买了一辆________色的________行车。", "hint_zh": "（自、白）", "answer": "白、自", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 47, "zh": "________学老师的办公室不在这儿，在________上。", "hint_zh": "（数、楼）", "answer": "数、楼", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 48, "zh": "音乐课容易吗？我觉得音乐课比历________课________难。", "hint_zh": "（更、史）", "answer": "史、更", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 49, "zh": "请问，________子旁边的那辆车，我可以________一下吗？", "hint_zh": "（骑、椅）", "answer": "椅、骑", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 50, "zh": "我们每个星期都________两次体________课。", "hint_zh": "（育、有）", "answer": "有、育", "answer_ref": {"book": "teacher", "pages": [172]}}]}, {"n": "四、复习", "type_zh": "复习", "instruction_zh": "第1–2题：根据课文内容填空", "instruction_en": "Questions 1-2: Fill in the blanks based on the texts in the textbook.", "items": [{"n": 1, "zh": "小丽上个月搬家了，走路去公司二十分钟就到，很________，所以最近比以前来得________。她还打算________一辆________，因为以前那辆太________了。", "answer": "方便、早多了、买、自行车、旧", "answer_ref": {"book": "teacher", "pages": [172]}}, {"n": 2, "zh": "大山在看房子。中介公司的人告诉他，学校里边比学校外边方便一点儿，________有________个车站。学校外边的房子比学校里边的大________，也比学校里边的安静。大山觉得房子大小没关系，最________的是________。", "answer": "附近、三四、一些、主要、环境", "answer_ref": {"book": "teacher", "pages": [172]}}]}]}, "audio": {"textbook": ["hsk3-textbook-1001.mp3", "hsk3-textbook-1002.mp3", "hsk3-textbook-1003.mp3", "hsk3-textbook-1004.mp3", "hsk3-textbook-1005.mp3"], "workbook": ["hsk3-workbook-10-part1.mp3", "hsk3-workbook-10-part2.mp3", "hsk3-workbook-10-part3.mp3", "hsk3-workbook-10-part4.mp3"]}, "unclear": ["Багшийн ном PDF х.73 (语言点1 导入 — 热身2-ын хариулт): «高—低» гэж хэвлэсэн; мөн номын PDF х.72 生词 对比法-д «高—矮», энэ хичээлийн шинэ үг 矮. Номд байгаагаар хоёуланг нь үлдээсэн.", "Багшийн ном PDF х.74 课文1 хариулт «马可比大山说得更好一些» — 课文1-д «马可比我说得好一些» (更 байхгүй); багшийн номын өөрийн 注意 (х.73: 形容词前一般不能再有程度副词) -тэй ч зөрж болзошгүй. Номд байгаагаар.", "Багшийн ном PDF х.75 课文4 хариулт «学校里边的房子比学校外边的方便一些» — 课文4-т «学校里边比学校外边方便» (一些 байхгүй); дасгалын ном 复习2 (PDF х.74) «方便一点儿». Бүгдийг номд байгаагаар.", "Багшийн ном PDF х.73 语言点 гарчиг «（2）概数的表达» («1» дугааргүй), сурах бичиг PDF х.100 «概数的表达1». Тус тусад нь номд байгаагаар.", "Багшийн ном PDF х.74 课文1 模仿练习 — «A：……，你和……个子高？» — 课文1-ийн «谁» хэвлэгдээгүй; номд байгаагаар.", "Багшийн ном PDF х.72 生词 启发式引导 — «他家楼下有一家超市，所以买东西很方便。» — «很方便» доогуур зураастай (сурагч нөхөх хэсэг); текстэд тэмдэглэгээгүй оруулсан.", "Багшийн номын 本课小结 (PDF х.77) 文化-г агуулаагүй; «文化：中国人结婚时穿什么» (文化点解析 + 参考处理方式) нь 小结-ийн дараа тусдаа хэсэг — teacher.steps-ийн сүүлийн алхам болгон оруулсан.", "Дасгалын ном 15 (PDF х.69): бичвэр «我们这儿有三四个姓王的老师呢» — сонголт A 三个 / B 三十个 / C 很多 — номын хариулт C (багшийн ном PDF х.172). Номд байгаагаар.", "Сурах бичгийн 练一练 (2 дүрэм × 3), 练习2 选词填空 / 练习3 完成对话 / 练习4 回答问题 / 运用 / багшийн номын 操练 (这些东西要三十或者四十块钱／他买了四瓶或者五瓶牛奶) / 汉字辨认练习 (组词) — хариулт номд хэвлэгдээгүй тул answer талбаргүй. Багшийн номын 课文 асуулт-хариулт (teacher.text_questions) нь 练习4-ийн асуултаас өөр.", "Сурах бичгийн 练习3-ын гарчиг «用本课新学的语言点和词语完成对话» (L02 шиг «描述图片» биш) — type_zh-д «完成对话» гэж гарчгаас товчилсон.", "Сурах бичгийн 拼音课文 (PDF х.99)-ын гарчгийн пиньинь (Zài jiàoshì / Zài jiàoshì / Zài xiūxishì / Zài kàn fángzi) болон ярилцагчийн нэрийн пиньинь (péngyou, Dàshān, Xiǎomíng, tóngxué, tóngshì, Xiǎolì, zhōngjiè) схемд талбаргүй тул lines.pinyin-д зөвхөн яриаг оруулсан.", "Энэ хичээлд 专有名词 хүснэгт, 汉字知识 хэсэг байхгүй; 注释1 жишээ (1)-д 大卫 гардаг ч тусгай нэрийн хүснэгтэд ороогүй. 注释-ийн жишээ 1-(4), 1-(8), 2-(4) нь номд улаанаар (课文-ээс авсан) хэвлэгдсэн.", "Дасгалын номын сонсгол нэг CD тэмдэгтэй (10) — аудиог hsk3-workbook-10-part1…4.mp3 болгож хэсэг тус бүрт хуваасныг section.audio-д оноосон.", "Дасгалын ном 听力 第三/四部分 — номд зөвхөн сонголтууд хэвлэгдсэн; item.zh-д багшийн номын хавсралтын «问：» асуултыг оруулсан (transcript_zh-д бүтнээр).", "Дасгалын номд 51–54 (组词) хэсэг байхгүй — нийт 1–50 + 复习 1–2.", "verified_pages: сурах бичиг PDF х.97–105, багшийн ном PDF х.71–77 ба 170–172, дасгалын ном PDF х.68–74 (71–74 дугаар багшийн ном, дасгалын ном хоёуланд давхцана).", "HSK 3.0 нэмэлт үгс (BLCUP 课件 补充HSK3.0, слайд 5, 16, 26) hsk30-д."], "verified_pages": [68, 69, 70, 71, 72, 73, 74, 75, 76, 77, 97, 98, 99, 100, 101, 102, 103, 104, 105, 170, 171, 172], "schema_version": 1, "hsk30": {"source": "courseware", "ref": {"book": "hsk30_courseware", "pages": [5, 16, 26]}, "new_words": [{"n": 1, "zh": "身高", "pinyin": "shēngāo", "pos": "n.", "en": "height", "text": 1}, {"n": 2, "zh": "直到", "pinyin": "zhídào", "pos": "v.", "en": "until", "text": 2}, {"n": 3, "zh": "受", "pinyin": "shòu", "pos": "v.", "en": "receive", "text": 2}, {"n": 4, "zh": "方便面", "pinyin": "fāngbiànmiàn", "pos": "n.", "en": "instant noodles", "text": 3}, {"n": 5, "zh": "汽车", "pinyin": "qìchē", "pos": "n.", "en": "car", "text": 3}, {"n": 6, "zh": "高铁", "pinyin": "gāotiě", "pos": "n.", "en": "high-speed rail", "text": 3}, {"n": 7, "zh": "红绿灯", "pinyin": "hóng-lǜdēng", "pos": "n.", "en": "traffic light", "text": 3}, {"n": 8, "zh": "街", "pinyin": "jiē", "pos": "n.", "en": "street", "text": 4}, {"n": 9, "zh": "马路", "pinyin": "mǎlù", "pos": "n.", "en": "road", "text": 4}, {"n": 10, "zh": "路边", "pinyin": "lùbiān", "pos": "n.", "en": "roadside", "text": 4}, {"n": 11, "zh": "路口", "pinyin": "lùkǒu", "pos": "n.", "en": "crossing", "text": 4}], "grammar": [], "exercises": []}}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk3-l11', 'hsk3', 'HSK3', 11, '别忘了把空调关了', 'Bié wàngle bǎ kōngtiáo guān le', 'Don’t forget to turn off the air conditioner', '{"level": "hsk3", "lesson": 11, "book": "HSK3", "title_zh": "别忘了把空调关了", "title_pinyin": "Bié wàngle bǎ kōngtiáo guān le", "title_en": "Don’t forget to turn off the air conditioner", "textbook": {"ref": {"book": "textbook", "pages": [106, 107, 108, 109, 110, 111, 112, 113]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①词典 cídiǎn", "②筷子 kuàizi", "③空调 kōngtiáo", "④地铁 dìtiě", "⑤灯 dēng", "⑥瓶子 píngzi"], "pictures_desc_en": ["A: a white wall-mounted air conditioner unit", "B: a thick book with a dark blue cover, the word DICTIONARY on its spine", "C: a lit crystal chandelier hanging from a ceiling", "D: red chopsticks lying side by side", "E: a brown glass bottle lying on its side", "F: a subway train standing at a station platform"]}, {"instruction_zh": "看图，说说他们在做什么", "instruction_en": "Look at the pictures and talk about what they are doing.", "items": ["A. 关空调 guān kōngtiáo", "B. 洗衣服 xǐ yīfu", "C. 还书 huán shū", "D. 关灯 guān dēng"], "pictures_desc_en": ["①: a finger pressing a light switch on a white wall", "②: a smiling young woman standing below a wall-mounted air conditioner, reaching up towards it", "③: a woman putting pink clothes into a washing machine", "④: several people holding books at a library counter"]}], "texts": [{"n": 1, "title_zh": "在教室", "title_en": "In the classroom", "kind": "dialogue", "audio": "hsk3-textbook-1101.mp3", "lines": [{"speaker": "小明", "zh": "我先走了。", "pinyin": "Wǒ xiān zǒu le."}, {"speaker": "同学", "zh": "你去哪儿？", "pinyin": "Nǐ qù nǎr?"}, {"speaker": "小明", "zh": "我去图书馆借本书。", "pinyin": "Wǒ qù túshūguǎn jiè běn shū."}, {"speaker": "同学", "zh": "帮我把这本词典还了吧。", "pinyin": "Bāng wǒ bǎ zhè běn cídiǎn huánle ba."}, {"speaker": "小明", "zh": "好，等一会儿你离开教室的时候，记得把灯关了。", "pinyin": "Hǎo, děng yíhuìr nǐ lí kāi jiàoshì de shíhou, jìde bǎ dēng guān le."}, {"speaker": "同学", "zh": "好的，放心吧。", "pinyin": "Hǎo de, fàng xīn ba."}], "new_words": [{"n": 1, "zh": "图书馆", "pinyin": "túshūguǎn", "pos": "n.", "en": "library", "text": 1}, {"n": 2, "zh": "借", "pinyin": "jiè", "pos": "v.", "en": "to borrow, to lend", "text": 1}, {"n": 3, "zh": "词典", "pinyin": "cídiǎn", "pos": "n.", "en": "dictionary", "text": 1}, {"n": 4, "zh": "还", "pinyin": "huán", "pos": "v.", "en": "to return", "text": 1}, {"n": 5, "zh": "灯", "pinyin": "dēng", "pos": "n.", "en": "light, lamp", "text": 1}]}, {"n": 2, "title_zh": "在会议室", "title_en": "In the conference room", "kind": "dialogue", "audio": "hsk3-textbook-1102.mp3", "lines": [{"speaker": "周明", "zh": "会议结束后，别忘记把空调关了。", "pinyin": "Huìyì jiéshù hòu, bié wàngjì bǎ kōngtiáo guān le."}, {"speaker": "小丽", "zh": "好的。王经理两点左右来了个电话。", "pinyin": "Hǎo de. Wáng jīnglǐ liǎng diǎn zuǒyòu láile ge diànhuà."}, {"speaker": "周明", "zh": "他已经到北京了？", "pinyin": "Tā yǐjīng dào Běijīng le?"}, {"speaker": "小丽", "zh": "是的，他正坐地铁来我们公司呢。", "pinyin": "Shì de, tā zhèng zuò dìtiě lái wǒmen gōngsī ne."}, {"speaker": "周明", "zh": "等他到了就告诉我。", "pinyin": "Děng tā dàole jiù gàosu wǒ."}], "new_words": [{"n": 6, "zh": "会议", "pinyin": "huìyì", "pos": "n.", "en": "meeting, conference", "text": 2}, {"n": 7, "zh": "结束", "pinyin": "jiéshù", "pos": "v.", "en": "to end, to finish", "text": 2}, {"n": 8, "zh": "忘记", "pinyin": "wàngjì", "pos": "v.", "en": "to forget", "text": 2}, {"n": 9, "zh": "空调", "pinyin": "kōngtiáo", "pos": "n.", "en": "air conditioner", "text": 2}, {"n": 10, "zh": "关", "pinyin": "guān", "pos": "v.", "en": "to turn off, to close", "text": 2}, {"n": 11, "zh": "地铁", "pinyin": "dìtiě", "pos": "n.", "en": "subway", "text": 2}]}, {"n": 3, "title_zh": "在客厅", "title_en": "In the living room", "kind": "dialogue", "audio": "hsk3-textbook-1103.mp3", "lines": [{"speaker": "妈妈", "zh": "还差一双筷子，你去拿一下。", "pinyin": "Hái chà yì shuāng kuàizi, nǐ qù ná yíxià."}, {"speaker": "儿子", "zh": "今天怎么做了这么多菜？", "pinyin": "Jīntiān zěnme zuòle zhème duō cài?"}, {"speaker": "妈妈", "zh": "今天是你爸爸的生日。", "pinyin": "Jīntiān shì nǐ bàba de shēngrì."}, {"speaker": "儿子", "zh": "真的啊？我把爸爸的生日忘了。那我们今天喝点儿啤酒吧。", "pinyin": "Zhēn de a? Wǒ bǎ bàba de shēngrì wàng le. Nà wǒmen jīntiān hē diǎnr píjiǔ ba."}, {"speaker": "妈妈", "zh": "医生说你爸爸一口酒都不能喝，别让他看见酒瓶子。", "pinyin": "Yīshēng shuō nǐ bàba yì kǒu jiǔ dōu bù néng hē, bié ràng tā kànjiàn jiǔ píngzi."}], "new_words": [{"n": 12, "zh": "双", "pinyin": "shuāng", "pos": "m.", "en": "pair", "text": 3}, {"n": 13, "zh": "筷子", "pinyin": "kuàizi", "pos": "n.", "en": "chopsticks", "text": 3}, {"n": 14, "zh": "啤酒", "pinyin": "píjiǔ", "pos": "n.", "en": "beer", "text": 3}, {"n": 15, "zh": "口", "pinyin": "kǒu", "pos": "m.", "en": "mouthful", "text": 3}, {"n": 16, "zh": "瓶子", "pinyin": "píngzi", "pos": "n.", "en": "bottle", "text": 3}]}, {"n": 4, "kind": "narrative", "audio": "hsk3-textbook-1104.mp3", "lines": [{"zh": "这个笔记本电脑我去年买的时候要五千块左右，现在便宜多了。", "pinyin": "Zhège bǐjìběn diànnǎo wǒ qùnián mǎi de shíhou yào wǔ qiān kuài zuǒyòu, xiànzài piányi duō le."}, {"zh": "我想把这个电脑卖了，再买一个更好的。", "pinyin": "Wǒ xiǎng bǎ zhège diànnǎo mài le, zài mǎi yí ge gèng hǎo de."}, {"zh": "现在我每天起床后的第一件事就是打开电脑，看电子邮件。", "pinyin": "Xiànzài wǒ měi tiān qǐ chuáng hòu de dì yī jiàn shì jiù shì dǎ kāi diànnǎo, kàn diànzǐ yóujiàn."}, {"zh": "我已经很少写信，也很少用笔写字，已经习惯用电脑来学习和工作了。", "pinyin": "Wǒ yǐjīng hěn shǎo xiě xìn, yě hěn shǎo yòng bǐ xiě zì, yǐjīng xíguàn yòng diànnǎo lái xuéxí hé gōngzuò le."}, {"zh": "哪一天突然没有了电脑，我们怎么办呢？", "pinyin": "Nǎ yì tiān tūrán méiyǒule diànnǎo, wǒmen zěnme bàn ne?"}], "new_words": [{"n": 17, "zh": "笔记本（电脑）", "pinyin": "bǐjìběn (diànnǎo)", "pos": "n.", "en": "notebook, laptop", "text": 4}, {"n": 18, "zh": "电子邮件", "pinyin": "diànzǐ yóujiàn", "en": "e-mail", "text": 4}, {"n": 19, "zh": "习惯", "pinyin": "xíguàn", "pos": "v./n.", "en": "to be used to; habit", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "“把”字句1：A把B＋V＋……", "title_en": "The Ba-Sentence 1: A把B + V + ……", "explanation_zh": "汉语中，表示对确定的人或确定的事物做出相应处置，可以用“把”字句，其结构为“A把B＋V＋……”。这种“把”字句多用于对别人的请求、命令的情境中。注意：A为动作的发出者；B为动词涉及的对象，必须是特指或已知的。例如：（1）–（4）\n否定副词和能愿动词等应该放在“把”字的前边，例如：（5）–（8）", "explanation_en": "In Chinese, a ba-sentence can be used to indicate a certain action done on a definite person or thing, the structure being “A把B + V + ……”. This type of ba-sentence is often used to request or order other people to do something. It is noteworthy that A is the agent of the action, and B is the patient. Both A and B should be specific or known to the speaker and the listener. For example: (1)–(4)\nIf there is a negative adverb or a modal verb etc., it should precede “把”. For example: (5)–(8)", "structure_rows": ["A把B＋V＋……"], "examples": [{"n": 1, "zh": "请你把衣服洗了。"}, {"n": 2, "zh": "帮我把这本词典还了。"}, {"n": 3, "zh": "你把灯关了吧。"}, {"n": 4, "zh": "我把爸爸的生日忘了。"}, {"n": 5, "zh": "你没把书给我。"}, {"n": 6, "zh": "你别把手机忘了。"}, {"n": 7, "zh": "我不能把电脑给你。"}, {"n": 8, "zh": "你可以把空调关了吗？"}], "practice_instruction_zh": "练一练　用提示词完成句子 Complete the sentences with the words given.", "practice": [{"n": 1, "zh": "房间里有点儿冷，你可以________？", "hint_zh": "（关门）"}, {"n": 2, "zh": "你发烧还没好，快________。", "hint_zh": "（吃药）"}, {"n": 3, "zh": "吃饭以前别忘了________。", "hint_zh": "（洗手）"}]}, {"n": 2, "title_zh": "概数的表达2：左右", "title_en": "Expression of Approximate Numbers 2: 左右", "explanation_zh": "汉语中，“左右”用在数字后面表示概数，如：三点左右，五个左右，十年左右。例如：", "explanation_en": "In Chinese, “左右” can be used after a numeral to indicate an approximate number, such as “三点左右” (around three o’clock), “五个左右” (about five), and “十年左右” (ten years or so). For example:", "structure_rows": ["三点左右", "五个左右", "十年左右"], "examples": [{"n": 1, "zh": "周末我一般十点左右起床。"}, {"n": 2, "zh": "我们公司有五百人左右。"}, {"n": 3, "zh": "王经理两点左右来了个电话。"}, {"n": 4, "zh": "这个笔记本电脑我去年买的时候要五千块左右。"}], "practice_instruction_zh": "练一练　完成对话 Complete the dialogues.", "practice": [{"n": 1, "zh": "A：你每天几点睡觉？ B：________。"}, {"n": 2, "zh": "A：你学了多长时间的汉语了？ B：________。"}, {"n": 3, "zh": "A：从你家到学校坐多长时间车？ B：________。"}]}], "exercises": [{"n": 1, "type_zh": "朗读", "instruction_zh": "朗读下列短语和句子", "instruction_en": "Read the following phrases and sentences aloud.", "audio": "hsk3-textbook-1105.mp3", "items": [{"n": 1, "zh": "关：关灯／关门／关电视／离开教室的时候，记得把灯关了。"}, {"n": 2, "zh": "借：借书／借钱／借我用用／我去图书馆借本书。"}, {"n": 3, "zh": "结束：学期结束／还没结束／结束了／会议结束后，别忘了把空调关了。"}, {"n": 4, "zh": "口：一口水／喝一口／吃几口饭／你爸爸一口酒都不能喝。"}, {"n": 5, "zh": "习惯：好习惯／学习习惯／还没习惯／我已经习惯用电脑来学习和工作了。"}]}, {"n": 2, "type_zh": "选词填空", "instruction_zh": "选择恰当的词语填空", "instruction_en": "Choose the proper words to fill in the blanks.", "word_bank": [["瓶子", "空调", "词典", "双", "口"], ["习惯", "结束", "关", "还（huán）", "会议"]], "items": [{"n": 1, "zh": "拿两________筷子就可以了，今天爸爸不回来吃晚饭。"}, {"n": 2, "zh": "这本________是我朋友的，不是我的。"}, {"n": 3, "zh": "这种咖啡特别好喝，你快来喝一________吧。"}, {"n": 4, "zh": "桌子上有一个________，是谁的？"}, {"n": 5, "zh": "你怎么没开________？太热了！"}, {"n": 6, "zh": "A：你把灯________了吧，我要睡觉了。 B：好，我马上就去。"}, {"n": 7, "zh": "A：你可以帮我把书________了吗？ B：明天下午可以吗？"}, {"n": 8, "zh": "A：音乐会________以后，我们一起去饭馆吃饭吧。 B：还是回家吃吧。"}, {"n": 9, "zh": "A：你下课以后常常做什么？ B：我下了汉语课________去图书馆。"}, {"n": 10, "zh": "A：今天的________是几点的？ B：下午两点半。"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "A：音乐会就要开始了，先生，请您________。 B：好的，我马上关。请问还有多长时间开始？ A：还有五分钟________。 B：谢谢。", "picture_desc_en": "A person holding up a mobile phone, its screen showing a stage."}, {"n": 2, "zh": "A：你今天打算几点睡觉？ B：十点半________。 A：睡觉以前别忘了________。 B：没问题。", "picture_desc_en": "A smiling man standing beside a boy who is drinking from a white cup."}, {"n": 3, "zh": "A：昨天谁是最后一个离开办公室的？ B：是我，我昨天是________离开的。 A：你是不是忘了________？ B：对不起，我以后一定不会忘。", "picture_desc_en": "A finger pressing a round power button with a small green light on a grey-and-black office machine."}, {"n": 4, "zh": "A：今天下午你要去见小刚吗？ B：对，我________去找他。 A：你可以帮我________？ B：没问题，我帮你还他。", "picture_desc_en": "One hand passing Chinese yuan banknotes into another open hand."}]}, {"n": 4, "type_zh": "回答问题", "instruction_zh": "根据课文回答问题", "instruction_en": "Answer the questions according to the texts.", "items": [{"n": 1, "zh": "小明要帮同学做什么？"}, {"n": 2, "zh": "小明告诉同学做什么？"}, {"n": 3, "zh": "王经理现在在哪儿？"}, {"n": 4, "zh": "周太太今天为什么做了那么多的菜？"}, {"n": 5, "zh": "爸爸能喝酒吗？为什么？"}, {"n": 6, "zh": "“我”现在每天用电脑做什么？"}]}], "characters": {"knowledge_title_zh": "旧字新词", "knowledge_zh": "读读下面的词语，想想组成的新词是什么意思。", "knowledge_en": "Read the following words and guess the meanings of the newly-formed ones.", "word_game": [{"parts": ["字", "词典"], "result": "字典"}, {"parts": ["运动", "会议"], "result": "运动会"}, {"parts": ["开", "会议"], "result": "开会"}], "confusable_pairs": [["周", "调"], ["关", "天"], ["还", "这"], ["快", "筷"], ["借", "错"]]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两个人一组，互相询问对方感兴趣的东西多少钱。", "instruction_en": "Work in pairs and ask each other the price of something you are interested in.", "example_zh": ["A：在你们国家，一个手机多少钱？", "B：在我们国家，一个手机2000块左右。", "表格：| | 问 | 答 |", "| 1 | 手机 | 2000块左右 |"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，用“把”字句说说今天的计划：什么时候，在什么地方，要做什么。", "instruction_en": "Work in groups of 3-4. Talk about today’s plan (including when, where, and what to do) using ba-sentences.", "example_zh": ["今天下了课我要去图书馆把书还了。", "提示词：洗衣服　买牛奶　写作业　做饭　借书　复习课文", "表格：| | 什么时候 | 什么地方 | 做什么 |", "| 1 | 下了课 | 去图书馆 | 把书还了 |"]}], "saying": {"zh": "贵人多忘事", "pinyin": "Guìrén duō wàng shì", "en": "Great wits have short memories", "explanation_zh": "“贵人多忘事”，这里的“贵人”是做大官的人或者做大生意的人。这句话的意思是做大官或者做大生意的人因为事情太多，所以常常会忘记做一些小事。现在一般用在对话中表示客气，说明一个人工作太忙，事情太多，忘记一些小事是可以理解的，有时候也有一种讽刺的意味。", "explanation_en": "In the saying “贵人多忘事”, “贵人” refers to “a high-ranking official” or “a successful businessman”. The saying means that one who holds a high government position or does big business often forgets certain trivialities due to the enormous amount of work. Now it is a polite way to say that it is understandable that one who is fully occupied with work or business affairs should forget some trivial matters, sometimes also conveying an ironic tone."}}, "teacher": {"ref": {"book": "teacher", "pages": [78, 79, 80, 81, 82, 83]}, "objectives_zh": ["重点词语：学生能够掌握：“借、还、双、口、电子邮件”的词义和用法", "语言点：学生能够了解并掌握：（1）“把”字句表示命令与请求（2）名词“左右”表示概数", "汉字：学生能够：根据已学生词猜测出3个旧字新词“字典、运动会、开会”的意思", "功能：学生能够：（1）用“把”字句表示命令与请求（2）用“左右”表示概数"], "steps": [{"title_zh": "复习旧课", "body_zh": "1 教师展示第10课的热身图片，请学生根据图片说出生词。\n2 教师根据第10课的内容进行提问。\n（1）你在这个地方住了多久了？你喜欢这儿吗？\n（2）我们每课的新词多不多？有几个？\n（3）你做的饭好吃还是妈妈做的饭好吃？\n（4）旅游的时候，坐飞机好还是坐火车好？为什么？\n（5）你觉得在大公司工作好还是在小公司工作好？为什么？"}, {"title_zh": "学习新课 1 热身", "body_zh": "热身1：学生两人一组，合作完成热身1；教师出示热身1的图片，让学生根据图片说出词语，核对答案；最后全体学生齐读热身环节所有词语，要求语音标准，声调准确。\n答案：①B　②D　③A　④F　⑤C　⑥E\n热身2：可留至语言点（1）“‘把’字句1：A把B＋动词＋……”导入时使用。"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n图书馆、借、词典、还、灯、会议、结束、忘记、空调、关、地铁、双、筷子、啤酒、口、瓶子、笔记本（电脑）、电子邮件、习惯\n· 教师先带领学生快速认读一遍生词；\n· 取消拼音，带领学生再次认读；\n· 请单个学生独自认读2-3个生词；\n· 最后全班一起快速认读所有的生词。\n（2）生词讲解方式\n· 直观法（如图片、照片、实物等）展示：图书馆、词典、灯、空调、地铁、筷子、啤酒、瓶子、笔记本（电脑）、电子邮件\n· 对比法展示：借—还、开始—结束、记得—忘记、开—关\n（3）重点生词扩展及常用搭配\n借—借书—借了五十块钱—我能借你的手机用一下吗？\n还—还书—还钱—你上次借的钱还没还呢。\n双—一双筷子—再拿两双筷子来，一会儿来两个朋友吃饭。\n口—一口—喝一口—一口酒—你只喝了一小口咖啡，是不是不好喝？\n电子邮件—写电子邮件—发电子邮件—你能用汉语给老师发一个电子邮件吗？\n练习册相关练习：第71页／一／第一部分，第74页／二／第二部分"}, {"title_zh": "3 语言点（1）“把”字句1：A把B＋动词＋……", "body_zh": "① 语言点解析\n汉语中，表示对确定的人或确定的事物做出相应处置，可以用“把”字句，其结构为“A把B＋动词＋……”。动词后最简单的其他成分就是“了”，这种“把”字句多用于对别人的请求、命令的情境中。\n［A把B＋动词＋其他成分（如“了”）］\n② 语言点导入\n教师可利用本课热身2导入语言点。\n答案：①D　②A　③B　④C\n教师：你想请朋友关灯，怎么说？\n学生：请关灯。\n教师引导学生说出：请把灯关了。\n③ 语言点操练\n教师可利用本课热身2操练语言点。\n教师展示图片并提问。\n教师：我们要出去，空调还开着，你应该说什么？\n学生：请把空调关了。\n目标句：请把空调关了。\n　　　　请把衣服洗了。\n　　　　请把书还了。\n④ 语言点扩展练习\n教师给出情境，请学生两人一组，一人说，一人做。\n在医院，医生请病人吃药、喝水。\n在家，妻子请丈夫做饭、洗衣服。\n在教室，老师请学生关手机、写作业。\n在办公室，经理请秘书关门、关电脑。\n注意：“A把B＋动词＋……”格式中，A为动作的发出者，B为动词涉及的对象，必须是特指或已知的。"}, {"title_zh": "3 语言点（2）概数的表达2：左右", "body_zh": "① 语言点解析\n汉语中，“左右”用在数字后面表示概数。如：三点左右，五个左右，十年左右。\n② 语言点导入\n教师根据实际情况，提问并引入语言点。\n教师：你今天是什么时候到教室的？\n学生：早上八点左右。\n③ 语言点操练\n教师可利用热身1的图片A、B、F，热身2的图片（3）（4）进行操练。\n目标句：一个空调两千块左右。\n　　　　一本词典五十块左右。\n　　　　地铁三分钟左右就来一次。\n　　　　明天我打算上午十点左右洗衣服。\n　　　　我昨天是下午两点左右去图书馆的。\n④ 语言点扩展练习\n教师可根据实际情况提问，请学生回答。\n你每天几点睡觉？周末呢？\n你觉得老师今年多大？"}, {"title_zh": "4 课文 课文1", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的为什么要先走？——他要去图书馆借本书。\n女的请男的做什么？——请男的帮她把词典还了。\n男的让女的做什么？——离开教室的时候把灯关了。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：我先……。\nB：你去哪儿？\nA：我……。\nB：帮我把……。\nA：好，……的时候，记得把……。\nB：好的，放心吧。"}, {"title_zh": "4 课文 课文2", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的对女的说什么？——会议结束后，别忘记把空调关了。\n女的告诉男的什么事儿？——王经理两点左右来了个电话。\n王经理现在在哪儿？——王经理正坐地铁来他们公司。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）教师给提示词，带领学生复述课文。\n提示词：结束、把……V了、左右、来电话、地铁"}, {"title_zh": "4 课文 课文3", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n女的（妈妈）让男的（儿子）做什么？——妈妈让儿子再拿一双筷子。\n妈妈今天为什么做了那么多菜？——因为今天是爸爸的生日。\n儿子做错了什么？——他把爸爸的生日忘了。\n他们今天能喝啤酒吗？为什么？——他们不能喝。因为医生一口酒都不让爸爸喝。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：还差……，你去……。\nB：今天怎么……？\nA：今天是……。\nB：真的啊？我把……。那……吧。\nA：医生说……，别……。"}, {"title_zh": "4 课文 课文4", "body_zh": "① 快速阅读，并回答：我现在有什么习惯？\n② 教师领读课文两遍，并回答下列问题：\n这个电脑是什么时候买的？多少钱？——这个电脑是去年买的，五千块左右。\n“我”现在有什么打算？——“我”想把这个电脑卖了，再买一个更好的。\n“我”每天起床后第一件事是什么？——第一件事是打开电脑，看电子邮件。\n③ 教师给提示词，带领学生复述课文。\n提示词：去年、左右、更好的、打开、电子邮件、习惯\n④ 教师请学生根据课文，说说自己用什么学习、工作，有什么习惯。\n练习册相关练习：第77页／四"}, {"title_zh": "5 汉字", "body_zh": "旧字新词：\n① 教师领读以前学过的词语和新词，并让学生猜猜新词的意思。\n· 领读：字、词典、字典\n问学生：什么时候用“字典”？——不会写字、不知道字怎么读的时候。\n· 领读：运动、会议、运动会\n问学生：“运动会”的时候做什么？——比赛。\n扩展提问：还有什么“会”？——音乐会、晚会、舞会、年会、迎新会。（根据实际情况选用）\n· 领读：开、会议、开会\n问学生：谁经常“开会”？——经理、秘书、老师。\n② 教师领读新词扩展，通过情景，理解新词的意思和用法：\n字典：一本字典／买字典／电子字典／你有汉语字典吗？\n运动会：开运动会／运动会要开始了／你们学校什么时候开运动会？\n开会：开一个会／开半个小时会／开会的时候请把手机关了。\n汉字辨认练习：\n辨认下列汉字并组词。\n周：________、________　调：________、________\n关：________、________　天：________、________\n还：________、________　这：________、________\n快：________、________　筷：________、________\n借：________、________　错：________、________\n练习册相关练习：第77页／三／第三部分"}, {"title_zh": "6 补充课堂活动——根据词卡写句子", "body_zh": "4-5个学生一组，小组内A→B、B→C、……、E→A，每人请同伴帮自己做一件事，要求用上“把”字句。"}, {"title_zh": "7 俗语", "body_zh": "教师引导学生理解俗语的含义，注意这里的“贵”的意思不是价格很贵，“贵人”是一种尊敬的用法。这句话是对别人说的，一般不对自己说。如：您真是贵人多忘事，这么快就把我的名字忘了。"}, {"title_zh": "8 本课小结", "body_zh": "· 语言点：用“把”字句表示命令与请求\n　　　　　用“左右”表示概数\n· 汉　字：旧字新词：字典、运动会、开会"}], "notes_zh": ["注意：“A把B＋动词＋……”格式中，A为动作的发出者，B为动词涉及的对象，必须是特指或已知的。（语言点1）", "动词后最简单的其他成分就是“了”。［A把B＋动词＋其他成分（如“了”）］（语言点1 解析）", "对比法展示：借—还、开始—结束、记得—忘记、开—关（生词）", "注意这里的“贵”的意思不是价格很贵，“贵人”是一种尊敬的用法。这句话是对别人说的，一般不对自己说。（俗语）"], "warmup_answers_zh": ["热身1 答案：①B　②D　③A　④F　⑤C　⑥E", "热身2 答案：①D　②A　③B　④C（语言点（1）导入）", "热身2：可留至语言点（1）“‘把’字句1：A把B＋动词＋……”导入时使用。"], "text_questions": [{"text": 1, "q_zh": "男的为什么要先走？", "a_zh": "他要去图书馆借本书。"}, {"text": 1, "q_zh": "女的请男的做什么？", "a_zh": "请男的帮她把词典还了。"}, {"text": 1, "q_zh": "男的让女的做什么？", "a_zh": "离开教室的时候把灯关了。"}, {"text": 2, "q_zh": "男的对女的说什么？", "a_zh": "会议结束后，别忘记把空调关了。"}, {"text": 2, "q_zh": "女的告诉男的什么事儿？", "a_zh": "王经理两点左右来了个电话。"}, {"text": 2, "q_zh": "王经理现在在哪儿？", "a_zh": "王经理正坐地铁来他们公司。"}, {"text": 3, "q_zh": "女的（妈妈）让男的（儿子）做什么？", "a_zh": "妈妈让儿子再拿一双筷子。"}, {"text": 3, "q_zh": "妈妈今天为什么做了那么多菜？", "a_zh": "因为今天是爸爸的生日。"}, {"text": 3, "q_zh": "儿子做错了什么？", "a_zh": "他把爸爸的生日忘了。"}, {"text": 3, "q_zh": "他们今天能喝啤酒吗？为什么？", "a_zh": "他们不能喝。因为医生一口酒都不让爸爸喝。"}, {"text": 4, "q_zh": "快速阅读，并回答：我现在有什么习惯？"}, {"text": 4, "q_zh": "这个电脑是什么时候买的？多少钱？", "a_zh": "这个电脑是去年买的，五千块左右。"}, {"text": 4, "q_zh": "“我”现在有什么打算？", "a_zh": "“我”想把这个电脑卖了，再买一个更好的。"}, {"text": 4, "q_zh": "“我”每天起床后第一件事是什么？", "a_zh": "第一件事是打开电脑，看电子邮件。"}], "summary_zh": "语言点：用“把”字句表示命令与请求；用“左右”表示概数。汉字：旧字新词：字典、运动会、开会。"}, "workbook": {"ref": {"book": "workbook", "pages": [75, 76, 77, 78, 79, 80, 81]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 1-5: Choose the right picture for each dialogue you hear.", "audio": "hsk3-workbook-11-part1.mp3", "items": [{"n": "例", "zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "transcript_zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "options": {"A": "[picture] a man working on a laptop at a desk, with a lamp and a potted plant beside him", "B": "[picture] a bowl and a pair of chopsticks on a chopstick rest, on a bamboo mat", "C": "[picture] a stadium full of spectators", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a patterned porcelain vase on a stand", "F": "[picture] an open thick dictionary with a pen lying on it"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [75]}}, {"n": 1, "zh": "", "options": {"A": "[picture] a man working on a laptop at a desk, with a lamp and a potted plant beside him", "B": "[picture] a bowl and a pair of chopsticks on a chopstick rest, on a bamboo mat", "C": "[picture] a stadium full of spectators", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a patterned porcelain vase on a stand", "F": "[picture] an open thick dictionary with a pen lying on it"}, "transcript_zh": "男：这个花瓶真漂亮，在哪儿买的？ 女：我家楼下的商店，我带你去看看。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 2, "zh": "", "options": {"A": "[picture] a man working on a laptop at a desk, with a lamp and a potted plant beside him", "B": "[picture] a bowl and a pair of chopsticks on a chopstick rest, on a bamboo mat", "C": "[picture] a stadium full of spectators", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a patterned porcelain vase on a stand", "F": "[picture] an open thick dictionary with a pen lying on it"}, "transcript_zh": "男：把词典还我吧，我要用一下。 女：好，方便的时候再借我用用。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 3, "zh": "", "options": {"A": "[picture] a man working on a laptop at a desk, with a lamp and a potted plant beside him", "B": "[picture] a bowl and a pair of chopsticks on a chopstick rest, on a bamboo mat", "C": "[picture] a stadium full of spectators", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a patterned porcelain vase on a stand", "F": "[picture] an open thick dictionary with a pen lying on it"}, "transcript_zh": "女：饭菜都做好了，把电脑关了吧？先吃饭。 男：好的，我马上就来。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 4, "zh": "", "options": {"A": "[picture] a man working on a laptop at a desk, with a lamp and a potted plant beside him", "B": "[picture] a bowl and a pair of chopsticks on a chopstick rest, on a bamboo mat", "C": "[picture] a stadium full of spectators", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a patterned porcelain vase on a stand", "F": "[picture] an open thick dictionary with a pen lying on it"}, "transcript_zh": "女：运动会什么时候结束？ 男：五点左右吧。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 5, "zh": "", "options": {"A": "[picture] a man working on a laptop at a desk, with a lamp and a potted plant beside him", "B": "[picture] a bowl and a pair of chopsticks on a chopstick rest, on a bamboo mat", "C": "[picture] a stadium full of spectators", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a patterned porcelain vase on a stand", "F": "[picture] an open thick dictionary with a pen lying on it"}, "transcript_zh": "男：服务员，这儿只有一双筷子，请再给我们拿一双。 女：好的，请您等一下，马上来。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听句子，判断对错", "instruction_en": "Questions 6-10: Decide whether the statements are true or false based on the sentences you hear.", "audio": "hsk3-workbook-11-part2.mp3", "items": [{"n": "例1", "zh": "他希望自己很健康。", "transcript_zh": "为了让自己更健康，他每天都花一个小时去锻炼身体。", "answer": "√", "answer_ref": {"book": "workbook", "pages": [76]}}, {"n": "例2", "zh": "那块儿手表不是他的。", "transcript_zh": "今天我想早点儿回家。看了看手表，才5点。过了一会儿再看表，还是5点，我这才发现我的手表不走了。", "answer": "×", "answer_ref": {"book": "workbook", "pages": [76]}}, {"n": 6, "zh": "他的电脑出了点儿问题。", "transcript_zh": "小周，你帮我看一下笔记本电脑吧。昨天我还能看电子邮件，今天突然就打不开了，不知道是怎么回事。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 7, "zh": "他打算去图书馆学习。", "transcript_zh": "教室里人太多了，我们去图书馆学习吧，那儿比较安静。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 8, "zh": "他以前骑自行车上班。", "transcript_zh": "住在这儿真不错，附近环境很好，离我上班的医院也不远，上下班都不用坐地铁了，骑自行车就可以。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 9, "zh": "跟家人一起吃晚饭很快乐。", "transcript_zh": "什么是快乐？结束一天的工作以后，你和家人一起吃晚饭，说说白天的事情，这不就是快乐吗？", "answer": "√", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 10, "zh": "啤酒在桌子上。", "transcript_zh": "你把桌子上的杯子给我，我去洗一下。你去楼下买几瓶啤酒吧。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听短对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the short dialogues and choose the right answers.", "audio": "hsk3-workbook-11-part3.mp3", "items": [{"n": "例", "zh": "男的想让小王做什么？", "transcript_zh": "男：小王，帮我开一下门，好吗？谢谢！ 女：没问题。您去超市了？买了这么多东西。 问：男的想让小王做什么？", "options": {"A": "开门", "B": "拿东西", "C": "去超市买东西"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [76]}}, {"n": 11, "zh": "男的在找什么？", "options": {"A": "地铁站", "B": "眼镜店", "C": "地图"}, "transcript_zh": "男：你看一下地图，这儿附近有眼镜店吗？ 女：地铁站旁边有一个，在地铁站的北边。 问：男的在找什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 12, "zh": "女的要做什么？", "options": {"A": "给妹妹喝牛奶", "B": "去超市买牛奶", "C": "带妹妹去医院"}, "transcript_zh": "男：妹妹怎么了？病了吗？ 女：可能饿了，你把奶瓶给我吧。 问：女的要做什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 13, "zh": "他们最可能是什么关系？", "options": {"A": "同事", "B": "经理和客人", "C": "医生和病人"}, "transcript_zh": "男：会议结束后，你记得把空调和灯都关了。 女：好的，我知道了，明天见。 问：他们最可能是什么关系？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 14, "zh": "男的要做什么？", "options": {"A": "出去开会", "B": "照顾小雨", "C": "和女的去公园"}, "transcript_zh": "女：我明天出去开会，你能帮我照顾一下小雨吗？ 男：行，没问题，我每天都带她去公园玩儿。 问：男的要做什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 15, "zh": "男的是什么意思？", "options": {"A": "让女的去还书", "B": "书已经还了", "C": "女的忘了还书"}, "transcript_zh": "女：我的那本历史书呢，你看见了吗？ 男：你昨天让我去图书馆把书还了，你忘了？ 问：男的是什么意思？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "一、听力 第四部分", "type_zh": "听力 第四部分", "instruction_zh": "第16–20题：听长对话，选择正确答案", "instruction_en": "Questions 16-20: Listen to the dialogues and choose the right answers.", "audio": "hsk3-workbook-11-part4.mp3", "items": [{"n": "例", "zh": "男的在做什么？", "transcript_zh": "女：晚饭做好了，准备吃饭了。 男：等一会儿，比赛还有三分钟就结束了。 女：快点儿吧，一起吃，菜冷了就不好吃了。 男：你先吃，我马上就看完了。 问：男的在做什么？", "options": {"A": "洗澡", "B": "吃饭", "C": "看电视"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [77]}}, {"n": 16, "zh": "男的为什么要打电话？", "options": {"A": "今天比较忙", "B": "空调有问题", "C": "叫人来换水"}, "transcript_zh": "女：空调下面怎么这么多水？ 男：我也是刚看见，我已经打电话叫人来看了。 女：问他们什么时候到了吗？ 男：他们说今天周日，比较忙，下午才能来。 问：男的为什么要打电话？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 17, "zh": "女的为什么不去跑步？", "options": {"A": "已经洗澡了", "B": "不喜欢出去跑步", "C": "想去超市买东西"}, "transcript_zh": "男：我要去跑步，你去不去？ 女：我已经洗完澡了，不想出去了。 男：要带点儿什么东西吗？ 女：你回来时，在楼下超市买斤香蕉和两瓶牛奶吧。 问：女的为什么不去跑步？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 18, "zh": "关于男的的电脑，可以知道什么？", "options": {"A": "比以前便宜了", "B": "太旧了", "C": "又大又方便"}, "transcript_zh": "女：我的笔记本电脑太旧了，我想换一个，你说买个什么样的好？ 男：我用的这个就不错，也不大，带着很方便。 女：贵不贵？ 男：有点儿贵，我去年买的时候九千，听说现在卖八千左右。 问：关于男的的电脑，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 19, "zh": "关于女的，可以知道什么？", "options": {"A": "来周先生家吃晚饭", "B": "每天八点左右下班", "C": "总是照顾周先生的小狗"}, "transcript_zh": "女：周先生，我公司突然有事，您能帮我去接一下孩子吗？ 男：没问题，我带她来我家吃晚饭。 女：好的，太谢谢你了，我八点左右去接她回来。 男：别客气，你不也总是帮我照顾小狗吗？ 问：关于女的，可以知道什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 20, "zh": "男的要做什么？", "options": {"A": "玩儿电脑", "B": "打篮球", "C": "复习考试"}, "transcript_zh": "男：妈，我跟同学去打篮球。 女：你明天不是还要考试吗？ 男：没关系，我已经复习好了，玩儿一会儿就回来。 女：好吧，你的电脑关了没有？ 问：男的要做什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第21–25题：选择合适的问答", "instruction_en": "Questions 21-25: Match the two parts of the same dialogue.", "items": [{"n": "例", "zh": "你知道怎么去那儿吗？", "options": {"A": "都这么晚了，今天别看书了，快睡觉吧。", "B": "你什么时候来找我，我们一起去图书馆吧。", "C": "我昨天没来，把你的笔记本借我看看吧。", "D": "我今天是开车来的，你们喝吧。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "不是，我去参加一个会议，下星期三回来。"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [78]}}, {"n": 21, "zh": "中午吃完饭，一点左右，怎么样？", "options": {"A": "都这么晚了，今天别看书了，快睡觉吧。", "B": "你什么时候来找我，我们一起去图书馆吧。", "C": "我昨天没来，把你的笔记本借我看看吧。", "D": "我今天是开车来的，你们喝吧。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "不是，我去参加一个会议，下星期三回来。"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 22, "zh": "你带这么多东西，又要出去旅游吗？", "options": {"A": "都这么晚了，今天别看书了，快睡觉吧。", "B": "你什么时候来找我，我们一起去图书馆吧。", "C": "我昨天没来，把你的笔记本借我看看吧。", "D": "我今天是开车来的，你们喝吧。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "不是，我去参加一个会议，下星期三回来。"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 23, "zh": "我习惯睡觉以前看会儿书了，不看书我睡不着。", "options": {"A": "都这么晚了，今天别看书了，快睡觉吧。", "B": "你什么时候来找我，我们一起去图书馆吧。", "C": "我昨天没来，把你的笔记本借我看看吧。", "D": "我今天是开车来的，你们喝吧。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "不是，我去参加一个会议，下星期三回来。"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 24, "zh": "周经理，您怎么一口酒都不喝？", "options": {"A": "都这么晚了，今天别看书了，快睡觉吧。", "B": "你什么时候来找我，我们一起去图书馆吧。", "C": "我昨天没来，把你的笔记本借我看看吧。", "D": "我今天是开车来的，你们喝吧。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "不是，我去参加一个会议，下星期三回来。"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 25, "zh": "对不起，我忘带了，明天给你吧。", "options": {"A": "都这么晚了，今天别看书了，快睡觉吧。", "B": "你什么时候来找我，我们一起去图书馆吧。", "C": "我昨天没来，把你的笔记本借我看看吧。", "D": "我今天是开车来的，你们喝吧。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "不是，我去参加一个会议，下星期三回来。"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第26–30题：选择合适的词语填空", "instruction_en": "Questions 26-30: Choose the proper words to fill in the brackets.", "word_bank": [["A 结束", "B 图书馆", "C 地铁", "D 习惯", "E 声音", "F 关"]], "items": [{"n": "例", "zh": "她说话的（　）多好听啊！", "options": {"A": "结束", "B": "图书馆", "C": "地铁", "D": "习惯", "E": "声音", "F": "关"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [78]}}, {"n": 26, "zh": "我们一会儿在（　）门口见面吧。", "options": {"A": "结束", "B": "图书馆", "C": "地铁", "D": "习惯", "E": "声音", "F": "关"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 27, "zh": "你去经理的办公室把灯（　）了。", "options": {"A": "结束", "B": "图书馆", "C": "地铁", "D": "习惯", "E": "声音", "F": "关"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 28, "zh": "我想住在（　）站附近，这样去别的地方很方便。", "options": {"A": "结束", "B": "图书馆", "C": "地铁", "D": "习惯", "E": "声音", "F": "关"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 29, "zh": "A：今天晚上的音乐会几点（　）？ B：十点左右，你还有事情吗？", "options": {"A": "结束", "B": "图书馆", "C": "地铁", "D": "习惯", "E": "声音", "F": "关"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 30, "zh": "A：给你买件衬衫吧，在银行上班穿衬衫好一些。 B：我还不太（　）穿衬衫。", "options": {"A": "结束", "B": "图书馆", "C": "地铁", "D": "习惯", "E": "声音", "F": "关"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第31–35题：选择正确答案", "instruction_en": "Questions 31-35: Choose the right answers.", "items": [{"n": "例", "zh": "您是来参加今天会议的吗？您来早了一点儿，现在才八点半。您先进来坐吧。 ★会议最可能几点开始？", "options": {"A": "8点", "B": "8点半", "C": "9点"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [79]}}, {"n": 31, "zh": "我每天下班都坐地铁回家，在地铁上，我更喜欢站着，因为我已经在办公室里坐了一天了。 ★我为什么在地铁上站着？", "options": {"A": "地铁上人很多", "B": "我不累", "C": "我坐了一天了"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 32, "zh": "看书时会看到一些历史上的人或者国家的名字，这些字现在很多都不用了，想要知道这些字的读音和意思就要字典的帮助，所以有本字典很方便。 ★看书时会看到：", "options": {"A": "不认识的字", "B": "现在的名人", "C": "汉字的读音"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 33, "zh": "中国有一句话叫“有借有还，再借不难”，是说向别人借的东西，用完就要还，这样下次你再借东西的时候，他们还会借给你。 ★借了别人的东西：", "options": {"A": "别用太长时间", "B": "要记得还", "C": "不能再借"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 34, "zh": "我爸爸妈妈都是北方人，但是我一直住在南方，所以没见过雪。搬到北京以后，虽然这儿的天气很冷，我还不太习惯，但是我见到雪了，我很高兴。 ★她：", "options": {"A": "不想搬家", "B": "见到雪了", "C": "习惯北京的天气"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 35, "zh": "下班后，我们一起去喝啤酒吧，就在公司旁边，以前是六十元一个人，现在是三十元一个人，想喝几瓶就可以喝几瓶，还送一些吃的。你那个朋友姓什么，我忘记了，叫他也来吧。 ★根据这段话，可以知道：", "options": {"A": "我忘记我朋友的名字了", "B": "三十元可以喝一瓶啤酒", "C": "喝啤酒比以前便宜了"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "三、书写 第一部分", "type_zh": "书写 第一部分", "instruction_zh": "第36–40题：连词成句", "instruction_en": "Questions 36-40: Rearrange the words/phrases to make sentences.", "items": [{"n": "例", "zh": "小船　上　一　河　条　有", "answer": "河上有一条小船。", "answer_ref": {"book": "workbook", "pages": [80]}}, {"n": 36, "zh": "左右　上地铁　我每天　七点", "answer": "我每天七点左右上地铁。", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 37, "zh": "几点　图书馆　关门", "answer": "图书馆几点关门？", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 38, "zh": "喝了　我昨天　啤酒　两瓶", "answer": "我昨天喝了两瓶啤酒。", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 39, "zh": "参加　运动会　今年的　你　吗", "answer": "你参加今年的运动会吗？", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 40, "zh": "别　忘了　手机　你　把", "answer": "你别把手机忘了。", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "三、书写 第二部分", "type_zh": "书写 第二部分", "instruction_zh": "第41–45题：看拼音，写汉字", "instruction_en": "Questions 41-45: Write the characters based on their pinyin.", "items": [{"n": "例", "zh": "没（　）系，别难过，高兴点儿。", "hint_zh": "guān", "answer": "关", "answer_ref": {"book": "workbook", "pages": [80]}}, {"n": 41, "zh": "这个笔记（　）电脑太贵了。", "hint_zh": "běn", "answer": "本", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 42, "zh": "早睡早起是一个好（　）惯。", "hint_zh": "xí", "answer": "习", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 43, "zh": "今天的（　）议几点结束？", "hint_zh": "huì", "answer": "会", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 44, "zh": "我从图书馆借了一本英汉（　）典。", "hint_zh": "cí", "answer": "词", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 45, "zh": "房间里的（　）怎么还开着呢？", "hint_zh": "dēng", "answer": "灯", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "三、书写 第三部分", "type_zh": "书写 第三部分", "instruction_zh": "第46–50题：辨认汉字，选择正确的汉字填空", "instruction_en": "Questions 46-50: Distinguish the characters and fill in the blanks.", "items": [{"n": "例", "zh": "我不知道________个地方在________儿。", "hint_zh": "（那、哪）", "answer": "那、哪", "answer_ref": {"book": "workbook", "pages": [81]}}, {"n": 46, "zh": "家里的空________坏了，________末我要叫人来看看。", "hint_zh": "（周、调）", "answer": "调、周", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 47, "zh": "昨________你离开的时候忘记________灯了。", "hint_zh": "（关、天）", "answer": "天、关", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 48, "zh": "你帮我把________本数学书________了吧。", "hint_zh": "（还、这）", "answer": "这、还", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 49, "zh": "________点儿，2号桌还少一双________子。", "hint_zh": "（快、筷）", "answer": "快、筷", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 50, "zh": "你看________了，我________的不是这本书。", "hint_zh": "（借、错）", "answer": "错、借", "answer_ref": {"book": "teacher", "pages": [175]}}]}, {"n": "四、复习", "type_zh": "复习", "instruction_zh": "第1–2题：根据课文内容填空", "instruction_en": "Questions 1-2: Fill in the blanks based on the texts in the textbook.", "items": [{"n": 1, "zh": "开会的时候，小丽告诉周明，王经理两点________来了个电话，说他已经坐________来公司了。周明告诉小丽会议________后，别________把________关了。", "answer": "左右、地铁、结束、忘记、空调", "answer_ref": {"book": "teacher", "pages": [175]}}, {"n": 2, "zh": "今天是爸爸的生日，所以妈妈做了很多菜。妈妈让儿子去拿________，还差一________。儿子想让爸爸喝点儿________，但是医生说爸爸一________酒都不能喝，所以不能让他看见酒________。", "answer": "筷子、双、啤酒、口、瓶子", "answer_ref": {"book": "teacher", "pages": [175]}}]}], "answers_ref": {"book": "teacher", "pages": [173, 174, 175]}}, "hsk30": {"source": "courseware", "ref": {"book": "hsk30_courseware", "pages": [5, 16, 26, 36, 37]}, "new_words": [{"n": 1, "zh": "电子书", "pinyin": "diànzǐshū", "pos": "n.", "en": "e-book", "text": 1}, {"n": 2, "zh": "字典", "pinyin": "zìdiǎn", "pos": "n.", "en": "dictionary", "text": 1}, {"n": 3, "zh": "会", "pinyin": "huì", "pos": "n.", "en": "meeting", "text": 2}, {"n": 4, "zh": "洗衣机", "pinyin": "xǐyījī", "pos": "n.", "en": "washing machine", "text": 2}, {"n": 5, "zh": "酒", "pinyin": "jiǔ", "pos": "n.", "en": "alcohol", "text": 3}, {"n": 6, "zh": "收到", "pinyin": "shōudào", "pos": "v.", "en": "receive", "text": 4}, {"n": 7, "zh": "电", "pinyin": "diàn", "pos": "n.", "en": "electricity", "text": 4}, {"n": 8, "zh": "封", "pinyin": "fēng", "pos": "m.", "en": "used of sth. sealed or wrapped up", "text": 4}, {"n": 9, "zh": "信", "pinyin": "xìn", "pos": "v./n.", "en": "believe/letter", "text": 4}, {"n": 10, "zh": "邮件", "pinyin": "yóujiàn", "pos": "n.", "en": "e-mail", "text": 4}, {"n": 11, "zh": "邮箱", "pinyin": "yóuxiāng", "pos": "n.", "en": "mailbox", "text": 4}, {"n": 12, "zh": "开机", "pinyin": "kāijī", "pos": "v.", "en": "power on", "text": 4}, {"n": 13, "zh": "关机", "pinyin": "guānjī", "pos": "v.", "en": "power off", "text": 4}], "grammar": [], "exercises": [], "unclear": []}, "audio": {"textbook": ["hsk3-textbook-1101.mp3", "hsk3-textbook-1102.mp3", "hsk3-textbook-1103.mp3", "hsk3-textbook-1104.mp3", "hsk3-textbook-1105.mp3"], "workbook": ["hsk3-workbook-11-part1.mp3", "hsk3-workbook-11-part2.mp3", "hsk3-workbook-11-part3.mp3", "hsk3-workbook-11-part4.mp3"]}, "unclear": ["课文2 (сурах бичиг PDF х.107) «会议结束后，别忘记把空调关了。» (忘记), харин 练习1 朗读 ③ (PDF х.110) «会议结束后，别忘了把空调关了。» (忘了) — номд хоёр өөр; тус бүрийг номд байгаагаар нь үлдээсэн.", "练习4 ④ (сурах бичиг PDF х.112) «周太太今天为什么做了那么多的菜？» — 课文3-т ээжийг зөвхөн «妈妈» гэж нэрлэсэн (周太太 гэсэн нэр бичвэрт байхгүй); багшийн ном (PDF х.81) «妈妈今天为什么做了那么多菜？» гэж асуудаг. Номд байгаагаар нь үлдээсэн.", "注释1 (сурах бичиг PDF х.109): хятад тайлбар «B为动词涉及的对象，必须是特指或已知的» (зөвхөн B), англи тайлбар «Both A and B should be specific or known to the speaker and the listener» (A ба B хоёулаа) — хоёр хэлний хооронд зөрүүтэй; номд байгаагаар нь.", "生词18 电子邮件 (сурах бичиг PDF х.108) — үгийн ай (pos) номд заагаагүй, зөвхөн «e-mail»; pos талбаргүй үлдээсэн.", "课文4 — гарчиггүй (номд зөвхөн «4», аудио 11-4) өгүүлэмж; lines-ийг өгүүлбэр (。／？) бүрээр хувааж, 拼音课文-ын харгалзах хэсгийг тус бүрт оноосон (номд нэг догол мөр).", "拼音课文-ын гарчгийн пиньинь (Zài jiàoshì / Zài huìyìshì / Zài kètīng) болон ярилцагчийн нэрийн пиньинь (Xiǎomíng, tóngxué, Zhōu Míng, Xiǎolì, māma, érzi) схемд талбаргүй тул lines.pinyin-д зөвхөн яриаг оруулсан.", "Энэ хичээлд 专有名词 хүснэгт、汉字知识、文化 хэсэг, * тэмдэгтэй үг байхгүй (сурах бичиг PDF х.106–113).", "Сурах бичгийн 练一练 (2 дүрэм × 3)、练习2 选词填空、练习3 描述图片、练习4 回答问题、运用 — хариулт сурах бичиг, багшийн номд хэвлэгдээгүй тул answer талбаргүй. Багшийн номын 课文 асуулт-хариулт (teacher.text_questions) нь 练习4-ийн асуултаас өөр.", "Багшийн номын 汉字辨认练习 (周/调 · 关/天 · 还/这 · 快/筷 · 借/错 — 组词 — PDF х.83) хоосон зайтай, хариулт хэвлэгдээгүй.", "Багшийн ном 课文1 асуулт (PDF х.81) ярилцагчдыг «男的／女的» гэж нэрлэсэн (сурах бичигт 小明／同学).", "练习3 (PDF х.111) зургууд: (3) товч дарж буй төхөөрөмж ямар машин (компьютер/принтер г.м.) болох нь тодорхойгүй; (2) хүүгийн ууж буй зүйл тодорхойгүй — picture_desc_en-д тодорхой бус хэлбэрээр.", "Дасгалын номын сонсгол нэг CD тэмдэгтэй (11, PDF х.75) — аудиог hsk3-workbook-11-part1…4.mp3 болгож хэсэг тус бүрт хуваасныг section.audio-д оноосон.", "Дасгалын ном 听力 第三/四部分 — номд зөвхөн сонголтууд хэвлэгдсэн; item.zh-д багшийн номын хавсралтын «问：» асуултыг оруулсан (transcript_zh-д бүтнээр).", "Дасгалын номд 51–54 (组词) хэсэг энэ хичээлд байхгүй — 1–50 + 复习 1–2.", "Багшийн ном 教学目标 (PDF х.78) «左右»-г «名词» гэж нэрлэсэн — номд байгаагаар.", "HSK 3.0 нэмэлт үгс (BLCUP 课件 补充HSK3.0, слайд 5, 16, 26, 36, 37) `hsk30`-д."], "verified_pages": [75, 76, 77, 78, 79, 80, 81, 82, 83, 106, 107, 108, 109, 110, 111, 112, 113, 173, 174, 175], "schema_version": 1}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk3-l12', 'hsk3', 'HSK3', 12, '把重要的东西放在我这儿吧', 'Bǎ zhòngyào de dōngxi fàng zài wǒ zhèr ba', 'Leave the important items with me', '{"level": "hsk3", "lesson": 12, "book": "HSK3", "title_zh": "把重要的东西放在我这儿吧", "title_pinyin": "Bǎ zhòngyào de dōngxi fàng zài wǒ zhèr ba", "title_en": "Leave the important items with me", "textbook": {"ref": {"book": "textbook", "pages": [114, 115, 116, 117, 118, 119, 120, 121, 122]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①护照 hùzhào", "②黑板 hēibǎn", "③行李箱 xínglixiāng", "④太阳 tàiyáng", "⑤画儿 huàr", "⑥包 bāo"], "pictures_desc_en": ["A: a bright sun shining in a blue sky", "B: a red suitcase on wheels with a pull-up handle", "C: a dark blue passport with “PASSPORT” printed on the cover", "D: a person painting a picture of an arched gateway on an easel outdoors", "E: a brown leather handbag", "F: a green blackboard in a wooden frame decorated with flowers and pinned pictures"]}, {"instruction_zh": "下边这些东西，你会放在什么地方？", "instruction_en": "Where would you put the following things?", "items": ["东西 | 放在哪儿", "铅笔 qiānbǐ | 桌子上 zhuōzi shang", "衣服 yīfu |", "照片 zhàopiàn |", "钱包 qiánbāo |", "护照 hùzhào |", "笔记本电脑 bǐjìběn diànnǎo |"]}], "texts": [{"n": 1, "title_zh": "在家", "title_en": "At home", "kind": "dialogue", "audio": "hsk3-textbook-1201.mp3", "lines": [{"speaker": "小丽", "zh": "今天太阳从西边出来了吗？", "pinyin": "Jīntiān tàiyáng cóng xībian chūlai le ma?"}, {"speaker": "小刚", "zh": "怎么了？", "pinyin": "Zěnme le?"}, {"speaker": "小丽", "zh": "你怎么这么早就要睡觉了？以前都要12点以后才睡觉。", "pinyin": "Nǐ zěnme zhème zǎo jiù yào shuì jiào le? Yǐqián dōu yào shí''èr diǎn yǐhòu cái shuì jiào."}, {"speaker": "小刚", "zh": "我明天8点就要到公司。", "pinyin": "Wǒ míngtiān bā diǎn jiù yào dào gōngsī."}, {"speaker": "小丽", "zh": "有事吗？", "pinyin": "Yǒu shì ma?"}, {"speaker": "小刚", "zh": "经理生气了，他告诉我，明天8点不到，以后就别来了。", "pinyin": "Jīnglǐ shēng qì le, tā gàosu wǒ, míngtiān bā diǎn bú dào, yǐhòu jiù bié lái le."}], "new_words": [{"n": 1, "zh": "太阳", "pinyin": "tàiyáng", "pos": "n.", "en": "sun", "text": 1}, {"n": 2, "zh": "西", "pinyin": "xī", "pos": "n.", "en": "west", "text": 1}, {"n": 3, "zh": "生气", "pinyin": "shēng qì", "pos": "v.", "en": "angry", "text": 1}]}, {"n": 2, "title_zh": "在家", "title_en": "At home", "kind": "dialogue", "audio": "hsk3-textbook-1202.mp3", "lines": [{"speaker": "小刚", "zh": "我要跟周经理去外地办事，明天的飞机。", "pinyin": "Wǒ yào gēn Zhōu jīnglǐ qù wàidì bàn shì, míngtiān de fēijī."}, {"speaker": "小丽", "zh": "那我帮你把衣服放到行李箱里吧。什么时候回来？", "pinyin": "Nà wǒ bāng nǐ bǎ yīfu fàngdào xínglixiāng li ba. Shénme shíhou huílai?"}, {"speaker": "小刚", "zh": "一个星期就回来。", "pinyin": "Yí ge xīngqī jiù huílai."}, {"speaker": "小丽", "zh": "啊？一个星期以后才回来？", "pinyin": "Á? Yí ge xīngqī yǐhòu cái huílai?"}, {"speaker": "小刚", "zh": "你要自己照顾好自己，我已经给你准备好吃的和喝的了。", "pinyin": "Nǐ yào zìjǐ zhàogù hǎo zìjǐ, wǒ yǐjīng gěi nǐ zhǔnbèi hǎo chī de hé hē de le."}, {"speaker": "小丽", "zh": "好吧。我已经把我的照片放在你的包里了。", "pinyin": "Hǎo ba. Wǒ yǐjīng bǎ wǒ de zhàopiàn fàng zài nǐ de bāo li le."}], "new_words": [{"n": 4, "zh": "行李箱", "pinyin": "xínglixiāng", "pos": "n.", "en": "luggage, suitcase", "text": 2}, {"n": 5, "zh": "自己", "pinyin": "zìjǐ", "pos": "pron.", "en": "self", "text": 2}, {"n": 6, "zh": "包", "pinyin": "bāo", "pos": "n.", "en": "bag, sack", "text": 2}]}, {"n": 3, "title_zh": "在机场", "title_en": "At the airport", "kind": "dialogue", "audio": "hsk3-textbook-1203.mp3", "lines": [{"speaker": "周明", "zh": "你怎么才来？", "pinyin": "Nǐ zěnme cái lái?"}, {"speaker": "小刚", "zh": "对不起，周经理，来机场的路上我才发现忘带护照了。", "pinyin": "Duìbuqǐ, Zhōu jīnglǐ, lái jīchǎng de lùshang wǒ cái fāxiàn wàng dài hùzhào le."}, {"speaker": "周明", "zh": "快点吧，飞机就要起飞了。", "pinyin": "Kuài diǎnr ba, fēijī jiù yào qǐfēi le."}, {"speaker": "小刚", "zh": "您有钱吗？司机把我送到机场的时候，我才发现忘记带钱包了。", "pinyin": "Nín yǒu qián ma? Sījī bǎ wǒ sòng dào jīchǎng de shíhou, wǒ cái fāxiàn wàngjì dài qiánbāo le."}, {"speaker": "周明", "zh": "我看你还是把重要的东西放在我这儿吧。", "pinyin": "Wǒ kàn nǐ háishi bǎ zhòngyào de dōngxi fàng zài wǒ zhèr ba."}], "new_words": [{"n": 7, "zh": "发现", "pinyin": "fāxiàn", "pos": "v.", "en": "to discover", "text": 3}, {"n": 8, "zh": "护照", "pinyin": "hùzhào", "pos": "n.", "en": "passport", "text": 3}, {"n": 9, "zh": "起飞", "pinyin": "qǐfēi", "pos": "v.", "en": "(of an aircraft) to take off", "text": 3}, {"n": 10, "zh": "司机", "pinyin": "sījī", "pos": "n.", "en": "driver", "text": 3}]}, {"n": 4, "title_zh": "", "kind": "narrative", "audio": "hsk3-textbook-1204.mp3", "lines": [{"zh": "我是一个中学老师，教学生画画儿。", "pinyin": "Wǒ shì yí ge zhōngxué lǎoshī, jiāo xuésheng huà huàr."}, {"zh": "每次下课前，我都会把下次学生需要带的东西写在黑板上，但是每次上课时，总会有学生忘了拿铅笔，所以我有点儿生气，不是因为他们没带铅笔，是因为他们没有好的学习习惯。", "pinyin": "Měi cì xià kè qián, wǒ dōu huì bǎ xià cì xuésheng xūyào dài de dōngxi xiě zài hēibǎn shang, dànshì měi cì shàng kè shí, zǒng huì yǒu xuésheng wàngle ná qiānbǐ, suǒyǐ wǒ yǒudiǎnr shēng qì, bú shì yīnwèi tāmen méi dài qiānbǐ, shì yīnwèi tāmen méiyǒu hǎo de xuéxí xíguàn."}], "new_words": [{"n": 11, "zh": "教", "pinyin": "jiāo", "pos": "v.", "en": "to teach", "text": 4}, {"n": 12, "zh": "画", "pinyin": "huà", "pos": "v./n.", "en": "to draw, to paint; drawing, painting", "text": 4}, {"n": 13, "zh": "需要", "pinyin": "xūyào", "pos": "v.", "en": "to need", "text": 4}, {"n": 14, "zh": "黑板", "pinyin": "hēibǎn", "pos": "n.", "en": "blackboard", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "“才”和“就”", "title_en": "Comparison of “才” and “就”", "explanation_zh": "“才”和“就”都可以放在动词前做状语。\n“就”表示说话人认为动作发生得早，进行得快、顺利。例如：（1）–（4）\n“才”表示说话人认为动作发生得晚，进行得慢、不顺利。例如：（5）–（8）", "explanation_en": "Both “才” and “就” can be used as an adverbial modifier before a verb.\n“就” indicates that in the speaker’s opinion, the action happened early, or went on fast or smoothly. For example: (1)–(4)\n“才” indicates that in the speaker’s opinion, the action happened late, or went on slowly or unsatisfactorily. For example: (5)–(8)", "examples": [{"n": 1, "zh": "我早上五点就起床了。"}, {"n": 2, "zh": "坐飞机一个小时就到了。"}, {"n": 3, "zh": "我很容易就找到了他的家。"}, {"n": 4, "zh": "你怎么这么早就要睡觉了？"}, {"n": 5, "zh": "八点上课，他九点才起床。"}, {"n": 6, "zh": "坐火车八个小时才能到。"}, {"n": 7, "zh": "弟弟三个小时才做完作业。"}, {"n": 8, "zh": "来机场的路上我才发现忘带护照了。"}], "practice_instruction_zh": "练一练　完成对话 Complete the dialogues.", "practice": [{"n": 1, "zh": "A：你昨天几点回的家？ B：________。"}, {"n": 2, "zh": "A：昨天的作业你多长时间写完的？ B：________。"}, {"n": 3, "zh": "A：你昨天睡了几个小时？ B：________。"}]}, {"n": 2, "title_zh": "“把”字句2：A把B+V+在/到/给……", "title_en": "The Ba-Sentence 2: A把B + V + 在/到/给……", "explanation_zh": "汉语中，表示对确定的人或事物做出相应动作，使其发生位置上的改变，多用“把”字句表达，其结构为“A把B+V+在/到+location”。例如：（1）–（4）\n表示通过动作使某确定事物发生关系上的转移，可以用“A把B+V+给+sb.”例如：（5）–（8）", "explanation_en": "In Chinese, a ba-sentence is often used to indicate a certain action is done on a definite person or thing and has changed the location of the person or thing, the structure being “A把B + V + 在/到 + location”. For example: (1)–(4)\nIf an action has changed the owner or user of a definite object, the structure “A把B + V + 给 + sb.” is used. For example: (5)–(8)", "structure_rows": ["A把B+V+在/到+location", "A把B+V+给+sb."], "examples": [{"n": 1, "zh": "我把照片放在你包里了。"}, {"n": 2, "zh": "老师把作业放在桌子上了。"}, {"n": 3, "zh": "我没把裤子放到椅子上。"}, {"n": 4, "zh": "我帮你把衣服放到行李箱里吧。"}, {"n": 5, "zh": "我把鲜花送给老师了。"}, {"n": 6, "zh": "我朋友把书借给我了。"}, {"n": 7, "zh": "弟弟没把钱还给哥哥。"}, {"n": 8, "zh": "你帮我把这本书带给小刚。"}], "practice_instruction_zh": "练一练　用提示词完成句子 Complete the sentences with the words given.", "practice": [{"n": 1, "zh": "我把书________。", "hint_zh": "（V在）"}, {"n": 2, "zh": "司机把我________。", "hint_zh": "（V到）"}, {"n": 3, "zh": "我想把这些吃的________。", "hint_zh": "（V给）"}]}], "exercises": [{"n": 1, "type_zh": "朗读", "instruction_zh": "朗读下列短语和句子", "instruction_en": "Read the following phrases and sentences aloud.", "audio": "hsk3-textbook-1205.mp3", "items": [{"n": 1, "zh": "生气：很生气／不生气／别生气／经理生气了。"}, {"n": 2, "zh": "自己：我自己／他们自己／你自己去吧／你要自己照顾好自己。"}, {"n": 3, "zh": "护照：一本护照／办护照／护照照片／来机场的路上我才发现忘带护照了。"}, {"n": 4, "zh": "教：教课／教汉语／教了十年／我教学生画画儿。"}, {"n": 5, "zh": "需要：不需要／需要休息／需要学习／我把需要带的东西写在黑板上。"}]}, {"n": 2, "type_zh": "选词填空", "instruction_zh": "选择恰当的词语填空", "instruction_en": "Choose the proper words to fill in the blanks.", "word_bank": [["黑板", "司机", "画", "包", "护照"], ["发现", "生气", "自己", "行李箱", "起飞"]], "items": [{"n": 1, "zh": "这张________真漂亮！是你的吗？"}, {"n": 2, "zh": "教室后边的那块________上写着几个字，你看得见吗？"}, {"n": 3, "zh": "你看，就是那位________找到了我的手机。"}, {"n": 4, "zh": "桌子上有一本________，是谁的？"}, {"n": 5, "zh": "请问，这个小________能带上飞机吗？"}, {"n": 6, "zh": "A：我现在能去一下洗手间吗？ B：对不起，飞机就要________了，请您坐好。"}, {"n": 7, "zh": "A：你怎么了？ B：今天我又迟到了，老师都________了。"}, {"n": 8, "zh": "A：我________公司楼下那家店的蛋糕特别好吃。 B：是吗？今天我也去买一块。"}, {"n": 9, "zh": "A：我的衣服太多了！ B：你把衣服放在我的________里吧，我的箱子大。"}, {"n": 10, "zh": "A：我出国一个星期，你怎么办？ B：不用担心，我可以照顾好________。"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "A：你怎么不上飞机？ B：我________发现忘了带护照了。 A：那怎么办？ B：我让妈妈把________。", "picture_desc_en": "A woman in sunglasses and a purple top sitting on a black suitcase next to a red suitcase, resting her chin on her hand."}, {"n": 2, "zh": "A：9点半了，你怎么________来？ B：起晚了，还等了半天公共汽车。 A：你的车呢？ B：我把________。", "picture_desc_en": "A young man in a dark suit and pink tie looking at his wristwatch in an office."}, {"n": 3, "zh": "A：你带我们去游泳吧。 B：行，你是刚学会游泳吗？ A：不是，我两年前________。 B：好，我一会儿就把________游泳馆。", "picture_desc_en": "A woman and two children sitting in the open back of a car."}, {"n": 4, "zh": "A：起床吧，已经8点了。 B：再让我睡会儿吧，昨晚________。 A：那我先起来了。我的眼镜呢？ B：昨天晚上我把________。", "picture_desc_en": "A pair of black-framed glasses lying on a white computer keyboard."}]}, {"n": 4, "type_zh": "回答问题", "instruction_zh": "根据课文回答问题", "instruction_en": "Answer the questions according to the texts.", "items": [{"n": 1, "zh": "小刚平时几点睡觉？今天呢？"}, {"n": 2, "zh": "小刚什么时候出差回来？"}, {"n": 3, "zh": "小刚给小丽准备了什么？小丽呢？"}, {"n": 4, "zh": "小刚今天忘带什么了？"}, {"n": 5, "zh": "每次下课以前，老师会做什么？"}, {"n": 6, "zh": "老师为什么有点儿生气？"}]}], "characters": {"knowledge_title_zh": "旧字新词", "knowledge_zh": "读读下面的词语，想想组成的新词是什么意思。", "knowledge_en": "Read the following words and guess the meanings of the newly-formed ones.", "word_game": [{"parts": ["钱", "包"], "result": "钱包"}, {"parts": ["电子邮件", "行李箱"], "result": "电子邮箱"}, {"parts": ["行李箱", "杯子"], "result": "箱子"}], "confusable_pairs": [["已", "己"], ["起", "超"], ["司", "同"], ["气", "汽"], ["现", "视"]]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两个人一组，互相询问并比较两个人的生活习惯。", "instruction_en": "Work in pairs. Ask about and compare each other’s living habits.", "example_zh": ["表格：| | | 我 | 朋友 |", "| 1 | 起床 | 我每天早上6点就起床。 | 我每天早上8点才起床。 |", "| 2 | 到教室 | | |", "| 3 | 学汉语 | | |", "| 4 | 睡觉 | | |", "| 5 | 做完作业 | | |", "| 6 | 吃晚饭 | | |"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，用“把”字句说说每个人平时都把日常用品放在哪儿，找找谁和自己的习惯一样。", "instruction_en": "Work in groups of 3-4. Talk about where you usually put certain articles for daily use using ba-sentences, and find out who have the same habits as yours.", "example_zh": ["例如：我把电脑放在桌子上。", "提示词：钱包　护照　汉语书　衣服　裤子　衬衫　照片　足球　书包", "表格：| 东西 | 谁跟我一样 | 放在哪儿 |", "| 电脑 | 小刚 | 我们都把电脑放在桌子上。 |"]}], "saying": {"zh": "习惯成自然", "pinyin": "Xíguàn chéng zìrán", "en": "Habit is a second nature", "explanation_zh": "“习惯成自然”，这里“成”是变成的意思。这句话的意思是，平时做事的方法习惯了，慢慢就变成自然的事了，很难再改变了。这句话告诉我们要养成好的习惯，不要觉得不好的事情只做一次没关系，如果不注意，慢慢就会变成很自然的事，到时候就不容易发现错误，也不容易改变了。", "explanation_en": "In the saying “习惯成自然”, “成” means “to become”. The sentence means that when the way of doing something turns into a habit, it becomes natural and hard to change. It tells us to form good habits and not to think it’s OK to do something bad just once, because the bad deed may gradually become a natural habit without you knowing it and by then, it would be hard to discover or change it."}}, "teacher": {"ref": {"book": "teacher", "pages": [84, 85, 86, 87, 88, 89]}, "objectives_zh": ["重点词语：学生能够熟练掌握：“生气、发现、起飞、教、画、需要”的词义和用法", "语言点：学生能够了解并掌握：（1）副词“才”和“就”的区别（2）“把”字句表示物体位置上的变化或关系上的转移", "汉字：学生能够：根据已学生词猜测出3个旧字新词“钱包、电子邮箱、箱子”的意思", "功能：学生能够：（1）用“才”和“就”描述主观认为动作的早晚快慢（2）用“把”字句描述位置上的改变和关系上的转移"], "steps": [{"title_zh": "复习旧课", "body_zh": "1 教师展示第11课的热身图片，请学生根据图片说出生词。\n2 教师根据第11课的内容进行提问。\n（1）你有事不能去图书馆，请朋友帮你还书，该怎么说？\n（2）夏天的晚上，出门的时候你要做什么？\n（3）你习惯用电脑做什么？\n（4）昨天你学了多长时间的汉语？\n（5）比较贵的手机多少钱一个？比较便宜的呢？你觉得我买哪个比较好？"}, {"title_zh": "学习新课 1 热身", "body_zh": "热身1：教师可依次出示热身部分的词语卡片，要求学生集体认读并请单个学生说出对应图片的编号，教师评判正误；最后全体学生齐读热身环节所有词语，要求语音标准，声调准确。\n答案：①C　②F　③B　④A　⑤D　⑥E\n热身2：可留至语言点（2）“‘把’字句2：A把B+动词+在/到/给……”导入时使用。"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n太阳、西、生气、行李箱、自己、包、发现、护照、起飞、司机、教、画、需要、黑板\n· 教师先带领学生快速认读一遍生词；\n· 取消拼音，带领学生再次认读；\n· 请单个学生独自认读2-3个生词；\n· 最后全班一起快速认读所有的生词。\n（2）生词讲解方式\n· 直观法（如图片、照片、实物等）展示：太阳、西、行李箱、包、护照、司机、画（n.）、黑板\n· 肢体展示：自己、画（v.）\n（3）重点生词扩展及常用搭配\n生气—很生气—我忘了爸爸的生日，他很生气。\n　—不生气—这件事是我错了，你别生气。\n发现—发现了—没发现—我昨天发现了一个很好吃的饭馆。\n起飞—飞机起飞—八点起飞—飞机就要起飞了，请您坐好。\n教—教我—教汉语—谁教你们画画儿？\n画—画画儿—画一张画儿—他会画中国画儿。\n　—画得好—你画画儿画得怎么样？\n需要—需要铅笔—需要照顾—去旅游，需要带什么东西？\n练习册相关练习：第78页／一／第一部分，第81页／二／第二部分"}, {"title_zh": "3 语言点（1）“才”和“就”", "body_zh": "① 语言点解析\n“才”放在动词前做状语，表示说话人认为动作发生得晚，进行得慢、不顺利。“就”放在动词前做状语，表示说话人认为动作发生得早，进行得快、顺利。\n［才＋动词］\n［就＋动词］\n② 语言点导入\n教师在黑板上写出三个句子，引发学生比较并思考，引导学生理解目标句。\n8：30上课。\n大山7：00来了。\n马可9：30来了。\n教师：他们谁来得早？谁来得晚？\n学生：大山来得早，马可来得晚。\n教师：你们觉得大山来得早，可以说“大山七点就来了”，你们觉得马可来得晚，可以说“马可九点半才来”。\n③ 语言点操练\n教师利用对比法，给出短语，请学生说句子：\n我早上五点起床，他早上九点起床——我早上五点就起床了，他九点才起床。\n坐飞机一个小时到，坐火车八个小时到\n我作业写了二十分钟，他写了两个小时\n我感冒三天好了，他一个星期好了\n昨天我5点回家，妈妈8点回家\n④ 语言点扩展练习\n教师提问，请学生根据实际情况回答。\n昨天你学了几个小时汉语？\n上周六你几点睡觉？\n你打算什么时候结婚？\n注意：“才”和“就”表示的早晚是主观的感觉，例如，我平时早上十点起床，今天九点半起的，就可以说“今天我九点半就起床了”，表达“九点半起床很早”的意思。“才V”后可不加“了”。"}, {"title_zh": "3 语言点（2）“把”字句2：A把B+动词+在/到/给……", "body_zh": "① 语言点解析\n“把”字句在动词后加上“在/到+地点”表示对确定的人或事物做出相应动作，使其发生位置上的改变；动词后加上“给+对象”表示通过动作使某确定事物发生关系上的转移。\n［A把B+动词+在/到+地点名词］\n［A把B+动词+给+对象］\n② 语言点导入\n教师可利用本课热身2的表格导入语言点。\n教师带领学生认读表格中的名词。\n教师示范：\n教师：铅笔，你会放在哪儿？\n学生：我会放在桌子上。\n教师引导学生说出目标句：我把铅笔放在桌子上。\n③ 语言点操练\n教师可利用热身2的表格操练语言点。\n学生向教师提问，教师作答后，请学生说出目标句。\n目标句：我把衣服放在床上了。\n　　　　我把照片放到钱包里了。\n　　　　我把钱包给太太了。\n　　　　我把护照放在家里了。\n　　　　我把笔记本电脑放在桌子上了。\n④ 语言点扩展练习\n教师利用热身2，让学生两人一组互相询问并回答。\n注意：“把”字句的宾语是定指的，例如不能说“我把一本书放在桌子上了”。"}, {"title_zh": "4 课文 课文1", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的（小刚）以前几点睡觉？——他以前都要12点以后才睡觉。\n小刚明天几点要到公司？——他明天8点就要到公司。\n小刚明天为什么要这样做？——他的经理生气了，经理告诉他，明天8点不到，以后就不用去了。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：今天太阳……？\nB：怎么了？\nA：你怎么……了？以前都要……。\nB：我明天……\nA：有事吗？\nB：……。"}, {"title_zh": "4 课文 课文2", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的（小刚）明天要做什么？——他要跟周经理去外地办事。\n小刚什么时候回来？——他一个星期以后回来。\n女的（小丽）帮他做什么了？——她帮小刚把衣服放到行李箱里，把她的照片放在小刚的包里了。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：我要……，明天的……。\nB：那我帮你……。什么……回来？\nA：……回来。\nB：啊？……才回来？\nA：你要……，我已经……。\nB：好吧。我已经……。"}, {"title_zh": "4 课文 课文3", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n第二个人（小刚）什么时候发现忘带护照的？——他来机场的路上才发现忘带护照的。\n小刚还忘记带什么了？——他忘记带钱包了。\n周经理建议他怎么做？——建议他把重要的东西放在自己这儿。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）教师给提示词，带领学生复述课文。\n提示词：机场、发现、护照、起飞、司机、钱包、重要"}, {"title_zh": "4 课文 课文4", "body_zh": "（1）快速阅读，并回答：“我”为什么生气？\n（2）教师领读课文两遍，并回答下列问题：\n“我”教学生什么？——“我”教学生画画儿。\n每次下课前，“我”会做什么？——“我”会把下次学生需要带的东西写在黑板上。\n（3）教师给提示词，带领学生复述课文。\n提示词：中学、教、画、下课前、需要、黑板、忘了、生气、不是……而是……\n（4）教师请学生根据课文，说一个自己老师生气的故事。\n练习册相关练习：第84页／四"}, {"title_zh": "5 汉字", "body_zh": "旧字新词：\n① 教师领读以前学过的词语和新词，并让学生猜猜新词的意思。\n· 领读：钱、包、钱包\n问学生：“钱包”是什么意思？——放钱的包。\n扩展提问：我们学习过哪些“包”？——书包、钥匙包、卡包、公文包。（根据实际情况选用）\n· 领读：电子邮件、行李箱、电子邮箱\n问学生：“电子邮箱”是什么意思？——放电子邮件的地方。\n· 领读：行李箱、杯子、箱子\n问学生：“箱子”是什么意思？——放东西的东西。\n② 教师领读新词扩展，通过情景，理解新词的意思和用法：\n钱包：我的钱包／钱包里／我的钱包里有女朋友的照片。\n电子邮箱：电子邮箱里／发到电子邮箱／我的电子邮箱里没有你的邮件。\n箱子：一个箱子／箱子里／我把夏天的衣服放到箱子里了。\n汉字辨认练习：\n辨认下列汉字并组词。\n已：________、________　起：________、________\n己：________、________　超：________、________\n司：________、________　气：________、________\n同：________、________　汽：________、________\n现：________、________\n视：________、________\n练习册相关练习：第84页／三／第三部分"}, {"title_zh": "6 补充课堂活动——布置会议场所", "body_zh": "教师将全班分成两组，每组根据板书提示，写下来怎么布置会场，看看哪组布置得又好又快。\n板书提示：把、咖啡、茶、水、杯子、笔记本、笔、椅子、桌子、空调、灯、电脑……"}, {"title_zh": "7 俗语", "body_zh": "教师引导学生理解俗语的含义，注意这里的“自然”表示的是自然的事，一件事情做多了，就变成了自然的事。例如，我现在吃完晚饭都会去外边走走，习惯成自然了。"}, {"title_zh": "8 本课小结", "body_zh": "· 语言点：用“才”和“就”表示人的主观感受\n　　　　　用“把”字句表示事物位置或关系的转移\n· 汉　字：旧字新词：钱包、电子邮箱、箱子"}], "notes_zh": ["注意：“才”和“就”表示的早晚是主观的感觉，例如，我平时早上十点起床，今天九点半起的，就可以说“今天我九点半就起床了”，表达“九点半起床很早”的意思。“才V”后可不加“了”。（语言点1）", "注意：“把”字句的宾语是定指的，例如不能说“我把一本书放在桌子上了”。（语言点2）", "注意这里的“自然”表示的是自然的事，一件事情做多了，就变成了自然的事。例如，我现在吃完晚饭都会去外边走走，习惯成自然了。（俗语）"], "warmup_answers_zh": ["热身1 答案：①C　②F　③B　④A　⑤D　⑥E", "热身2：可留至语言点（2）“‘把’字句2：A把B+动词+在/到/给……”导入时使用。"], "text_questions": [{"text": 1, "q_zh": "男的（小刚）以前几点睡觉？", "a_zh": "他以前都要12点以后才睡觉。"}, {"text": 1, "q_zh": "小刚明天几点要到公司？", "a_zh": "他明天8点就要到公司。"}, {"text": 1, "q_zh": "小刚明天为什么要这样做？", "a_zh": "他的经理生气了，经理告诉他，明天8点不到，以后就不用去了。"}, {"text": 2, "q_zh": "男的（小刚）明天要做什么？", "a_zh": "他要跟周经理去外地办事。"}, {"text": 2, "q_zh": "小刚什么时候回来？", "a_zh": "他一个星期以后回来。"}, {"text": 2, "q_zh": "女的（小丽）帮他做什么了？", "a_zh": "她帮小刚把衣服放到行李箱里，把她的照片放在小刚的包里了。"}, {"text": 3, "q_zh": "第二个人（小刚）什么时候发现忘带护照的？", "a_zh": "他来机场的路上才发现忘带护照的。"}, {"text": 3, "q_zh": "小刚还忘记带什么了？", "a_zh": "他忘记带钱包了。"}, {"text": 3, "q_zh": "周经理建议他怎么做？", "a_zh": "建议他把重要的东西放在自己这儿。"}, {"text": 4, "q_zh": "“我”为什么生气？"}, {"text": 4, "q_zh": "“我”教学生什么？", "a_zh": "“我”教学生画画儿。"}, {"text": 4, "q_zh": "每次下课前，“我”会做什么？", "a_zh": "“我”会把下次学生需要带的东西写在黑板上。"}], "summary_zh": "语言点：用“才”和“就”表示人的主观感受；用“把”字句表示事物位置或关系的转移。汉字：旧字新词：钱包、电子邮箱、箱子。"}, "workbook": {"ref": {"book": "workbook", "pages": [82, 83, 84, 85, 86, 87, 88]}, "answers_ref": {"book": "teacher", "pages": [176, 177, 178]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 1-5: Choose the right picture for each dialogue you hear.", "audio": "hsk3-workbook-12-part1.mp3", "items": [{"n": "例", "zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "transcript_zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "options": {"A": "[picture] the cabin of a passenger plane with rows of seats and a flight attendant in the aisle", "B": "[picture] a row of hard-shell suitcases of different sizes", "C": "[picture] a board with the words “说普通话 写规范字” and vertical inscriptions on both sides", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young woman sitting beside a smiling elderly woman in a wheelchair in a park", "F": "[picture] a man in a suit talking on a mobile phone and looking at his wristwatch"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [82]}}, {"n": 1, "zh": "", "options": {"A": "[picture] the cabin of a passenger plane with rows of seats and a flight attendant in the aisle", "B": "[picture] a row of hard-shell suitcases of different sizes", "C": "[picture] a board with the words “说普通话 写规范字” and vertical inscriptions on both sides", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young woman sitting beside a smiling elderly woman in a wheelchair in a park", "F": "[picture] a man in a suit talking on a mobile phone and looking at his wristwatch"}, "transcript_zh": "女1：你的腿好点了吗？ 女2：还有点儿疼。今天太阳不错，你带我出去吧。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 2, "zh": "", "options": {"A": "[picture] the cabin of a passenger plane with rows of seats and a flight attendant in the aisle", "B": "[picture] a row of hard-shell suitcases of different sizes", "C": "[picture] a board with the words “说普通话 写规范字” and vertical inscriptions on both sides", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young woman sitting beside a smiling elderly woman in a wheelchair in a park", "F": "[picture] a man in a suit talking on a mobile phone and looking at his wristwatch"}, "transcript_zh": "女：能帮我把这些行李箱放到上面吗？我搬不动。 男：可以，我来搬吧。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 3, "zh": "", "options": {"A": "[picture] the cabin of a passenger plane with rows of seats and a flight attendant in the aisle", "B": "[picture] a row of hard-shell suitcases of different sizes", "C": "[picture] a board with the words “说普通话 写规范字” and vertical inscriptions on both sides", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young woman sitting beside a smiling elderly woman in a wheelchair in a park", "F": "[picture] a man in a suit talking on a mobile phone and looking at his wristwatch"}, "transcript_zh": "女：对不起，先生，飞机马上就要起飞了，请您关上手机。 男：好的，我知道了。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 4, "zh": "", "options": {"A": "[picture] the cabin of a passenger plane with rows of seats and a flight attendant in the aisle", "B": "[picture] a row of hard-shell suitcases of different sizes", "C": "[picture] a board with the words “说普通话 写规范字” and vertical inscriptions on both sides", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young woman sitting beside a smiling elderly woman in a wheelchair in a park", "F": "[picture] a man in a suit talking on a mobile phone and looking at his wristwatch"}, "transcript_zh": "女：黑板上的那个字怎么读？ 男：我也不认识，我查一下字典，找到了告诉你。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 5, "zh": "", "options": {"A": "[picture] the cabin of a passenger plane with rows of seats and a flight attendant in the aisle", "B": "[picture] a row of hard-shell suitcases of different sizes", "C": "[picture] a board with the words “说普通话 写规范字” and vertical inscriptions on both sides", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young woman sitting beside a smiling elderly woman in a wheelchair in a park", "F": "[picture] a man in a suit talking on a mobile phone and looking at his wristwatch"}, "transcript_zh": "女：会议早就开始了，你怎么现在还没来？ 男：别生气，我十分钟就到。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听句子，判断对错", "instruction_en": "Questions 6-10: Decide whether the statements are true or false based on the sentences you hear.", "audio": "hsk3-workbook-12-part2.mp3", "items": [{"n": "例1", "zh": "他希望自己很健康。", "transcript_zh": "为了让自己更健康，他每天都花一个小时去锻炼身体。", "answer": "√", "answer_ref": {"book": "workbook", "pages": [83]}}, {"n": "例2", "zh": "那块儿手表不是他的。", "transcript_zh": "今天我想早点儿回家。看了看手表，才5点。过了一会儿再看表，还是5点，我这才发现我的手表不走了。", "answer": "×", "answer_ref": {"book": "workbook", "pages": [83]}}, {"n": 6, "zh": "他是出租车司机。", "transcript_zh": "我的包忘在出租车上了，钱包、手机和护照都在里面。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 7, "zh": "他不喜欢跟老师学画画儿。", "transcript_zh": "我很喜欢画画儿，但是没有人教过我，我都是自己学的，你看这个小狗就是我画的，可爱吗？", "answer": "×", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 8, "zh": "老师昨天没讲明白。", "transcript_zh": "老师，您昨天讲的那几个题，我今天就忘了，您能再教我一次吗？", "answer": "×", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 9, "zh": "爸爸洗衣服的时候发现了护照。", "transcript_zh": "爸爸找了很长时间都没找到他的护照，我今天上午帮他洗衣服的时候，在他那条蓝色的裤子里找到了。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 10, "zh": "桌子和椅子都旧了。", "transcript_zh": "我们需要换新的桌子和椅子，你什么时候有时间，跟我一起去看看？", "answer": "√", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听短对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the short dialogues and choose the right answers.", "audio": "hsk3-workbook-12-part3.mp3", "items": [{"n": "例", "zh": "男的想让小王做什么？", "transcript_zh": "男：小王，帮我开一下门，好吗？谢谢！ 女：没问题。您去超市了？买了这么多东西。 问：男的想让小王做什么？", "options": {"A": "开门", "B": "拿东西", "C": "去超市买东西"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [83]}}, {"n": 11, "zh": "女的现在在哪儿？", "options": {"A": "公园里边", "B": "公园西门", "C": "公园北门"}, "transcript_zh": "女：喂，我已经到公园西门了，你是在北门吗，我过去找你吧？ 男：你别过来了，我快到西门了。 问：女的现在在哪儿？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 12, "zh": "男的是什么意思？", "options": {"A": "太阳从西边出来", "B": "女的不可能每天跑步", "C": "明天要跑一千米"}, "transcript_zh": "女：我决定从明天开始每天跑一千米。 男：真的吗？太阳从西边出来了？ 问：男的是什么意思？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 13, "zh": "护照在哪儿？", "options": {"A": "行李箱里", "B": "包里", "C": "手里"}, "transcript_zh": "男：你把护照放在行李箱里了吗？ 女：没有，在我包里呢，这样拿着比较方便。 问：护照在哪儿？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 14, "zh": "女的要去哪儿？", "options": {"A": "学校", "B": "银行", "C": "西门"}, "transcript_zh": "女：请问，学校附近有中国银行吗？ 男：有，出了西门，向左走两百米就能看见。 问：女的要去哪儿？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 15, "zh": "男的打算怎么去火车站？", "options": {"A": "开车", "B": "打车", "C": "坐公共汽车"}, "transcript_zh": "女：火车站离这儿很远，坐车不太方便，我开车送你去。 男：不用了，谢谢您，我还是自己打出租车去吧。 问：男的打算怎么去火车站？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "一、听力 第四部分", "type_zh": "听力 第四部分", "instruction_zh": "第16–20题：听长对话，选择正确答案", "instruction_en": "Questions 16-20: Listen to the dialogues and choose the right answers.", "audio": "hsk3-workbook-12-part4.mp3", "items": [{"n": "例", "zh": "男的在做什么？", "transcript_zh": "女：晚饭做好了，准备吃饭了。 男：等一会儿，比赛还有三分钟就结束了。 女：快点儿吧，一起吃，菜冷了就不好吃了。 男：你先吃，我马上就看完了。 问：男的在做什么？", "options": {"A": "洗澡", "B": "吃饭", "C": "看电视"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [84]}}, {"n": 16, "zh": "女的还准备画什么？", "options": {"A": "太阳", "B": "小猫", "C": "花儿"}, "transcript_zh": "男：这是你画的吗？ 女：太阳是我画的，小猫是妹妹画的。 男：真好看，画好了吗？ 女：还没有，我想在这儿再画点儿花儿。 问：女的还准备画什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 17, "zh": "关于男的，可以知道什么？", "options": {"A": "帮女的拿西瓜", "B": "想再吃点儿米饭", "C": "想吃点儿西瓜"}, "transcript_zh": "女：吃好了吗？要不要再来点儿米饭？ 男：不吃了。家里还有西瓜吗？ 女：还有半个，你自己拿吧。 男：好的。 问：关于男的，可以知道什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 18, "zh": "男的明天要做什么？", "options": {"A": "去接人", "B": "坐火车", "C": "找司机"}, "transcript_zh": "男：喂，是小马吗？ 女：是我，周经理，您有什么事？ 男：我明天十点要去火车站接个人。 女：好的，我知道了，我让司机明天九点前到楼下等您。 问：男的明天要做什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 19, "zh": "男的要做什么？", "options": {"A": "骑车去上课", "B": "教女的骑车", "C": "学骑自行车"}, "transcript_zh": "女：你会骑自行车吗？ 男：当然，我以前经常骑车去上课。 女：那你教教我吧，我一直想学。 男：可以啊，你什么时候有时间？ 问：男的要做什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 20, "zh": "男的怎么了？", "options": {"A": "来机场晚了", "B": "找不到护照了", "C": "忘了给女的打电话"}, "transcript_zh": "女：你怎么才来，都八点一刻了。 男：对不起，来机场的路上才发现没带护照。 女：出门的时候你怎么不好好看看呢？ 男：你一直给我打电话，我很着急，就出了问题。 问：男的怎么了？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第21–25题：选择合适的问答", "instruction_en": "Questions 21-25: Match the two parts of the same dialogue.", "items": [{"n": "例", "zh": "你知道怎么去那儿吗？", "options": {"A": "你怎么现在才给周经理写信？", "B": "我想学画画儿，你帮我找一个老师教我吧。", "C": "请问您需要什么帮助吗？", "D": "你看桌子下边的那个箱子里有没有？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我担心路上车太多，不好走。"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [85]}}, {"n": 21, "zh": "我找不到行李箱了，您帮我找找吧。", "options": {"A": "你怎么现在才给周经理写信？", "B": "我想学画画儿，你帮我找一个老师教我吧。", "C": "请问您需要什么帮助吗？", "D": "你看桌子下边的那个箱子里有没有？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我担心路上车太多，不好走。"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 22, "zh": "飞机十点才起飞，你怎么现在就要走？", "options": {"A": "你怎么现在才给周经理写信？", "B": "我想学画画儿，你帮我找一个老师教我吧。", "C": "请问您需要什么帮助吗？", "D": "你看桌子下边的那个箱子里有没有？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我担心路上车太多，不好走。"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 23, "zh": "你想学画画儿，真是太阳从西边出来了。", "options": {"A": "你怎么现在才给周经理写信？", "B": "我想学画画儿，你帮我找一个老师教我吧。", "C": "请问您需要什么帮助吗？", "D": "你看桌子下边的那个箱子里有没有？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我担心路上车太多，不好走。"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 24, "zh": "你把我的护照放在哪儿了？", "options": {"A": "你怎么现在才给周经理写信？", "B": "我想学画画儿，你帮我找一个老师教我吧。", "C": "请问您需要什么帮助吗？", "D": "你看桌子下边的那个箱子里有没有？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我担心路上车太多，不好走。"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 25, "zh": "对不起，小丽才把他的电子邮箱告诉我。", "options": {"A": "你怎么现在才给周经理写信？", "B": "我想学画画儿，你帮我找一个老师教我吧。", "C": "请问您需要什么帮助吗？", "D": "你看桌子下边的那个箱子里有没有？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我担心路上车太多，不好走。"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第26–30题：选择合适的词语填空", "instruction_en": "Questions 26-30: Choose the proper words to fill in the brackets.", "word_bank": [["A 司机", "B 起飞", "C 发现", "D 自己", "E 声音", "F 包"]], "items": [{"n": "例", "zh": "她说话的（　）多好听啊！", "options": {"A": "司机", "B": "起飞", "C": "发现", "D": "自己", "E": "声音", "F": "包"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [85]}}, {"n": 26, "zh": "我回来了，真累啊，帮我把（　）放在桌子上吧。", "options": {"A": "司机", "B": "起飞", "C": "发现", "D": "自己", "E": "声音", "F": "包"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 27, "zh": "你给（　）打个电话，让他下午三点来接我。", "options": {"A": "司机", "B": "起飞", "C": "发现", "D": "自己", "E": "声音", "F": "包"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 28, "zh": "我（　）你最近总是上课睡觉，你晚上几点睡啊？", "options": {"A": "司机", "B": "起飞", "C": "发现", "D": "自己", "E": "声音", "F": "包"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 29, "zh": "A：我们的飞机几点（　）？ B：下午三点四十分，还有一个小时。", "options": {"A": "司机", "B": "起飞", "C": "发现", "D": "自己", "E": "声音", "F": "包"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 30, "zh": "A：你帮我把衣服洗了吧。 B：这些都是你的衣服，你（　）洗吧。", "options": {"A": "司机", "B": "起飞", "C": "发现", "D": "自己", "E": "声音", "F": "包"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第31–35题：选择正确答案", "instruction_en": "Questions 31-35: Choose the right answers.", "items": [{"n": "例", "zh": "您是来参加今天会议的吗？您来早了一点儿，现在才八点半。您先进来坐吧。 ★会议最可能几点开始？", "options": {"A": "8点", "B": "8点半", "C": "9点"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [86]}}, {"n": 31, "zh": "有个词语叫“老小孩儿”，意思是人老了有时候跟小孩儿一样，容易高兴，也容易生气。 ★根据这段话，可以知道老人：", "options": {"A": "总是生气", "B": "很喜欢小孩儿", "C": "有些地方跟小孩儿一样"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 32, "zh": "妻子今天不舒服，我把她送到了医院，医生看了以后说没有大的问题，可能是最近工作太忙、太累了，让她在家里休息几天。 ★妻子：", "options": {"A": "需要休息", "B": "自己去医院了", "C": "已经休息几天了"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 33, "zh": "我是新来的司机，姓高，您叫我小高就可以了。来，把您的行李箱给我，我放在车的后边。您带好护照和机票了吗？我们现在就去机场。 ★小高：", "options": {"A": "要去坐飞机", "B": "在机场工作", "C": "是一个司机"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 34, "zh": "周明是我爸爸的同学，也是他现在的同事。我小的时候，他有时候带我出去玩儿，还教会了我游泳。明天是他的生日，我要去给他买一个大的蛋糕。 ★周明：", "options": {"A": "是我的同学", "B": "喜欢游泳", "C": "明天过生日"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 35, "zh": "有的事儿就是很有意思，我昨天才发现，你给小张介绍的男朋友是我妻子以前的同事。我们以前见过面，还一起吃过饭，那个时候我就想把他介绍给小张。 ★小张的男朋友是我妻子：", "options": {"A": "以前的同事", "B": "以前的丈夫", "C": "以前的男朋友"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "三、书写 第一部分", "type_zh": "书写 第一部分", "instruction_zh": "第36–40题：连词成句", "instruction_en": "Questions 36-40: Rearrange the words/phrases to make sentences.", "items": [{"n": "例", "zh": "小船　上　一　河　条　有", "answer": "河上有一条小船。", "answer_ref": {"book": "workbook", "pages": [87]}}, {"n": 36, "zh": "护照　桌子上　放到　请把", "answer": "请把护照放到桌子上。", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 37, "zh": "需要　笔记本　买个　电脑　我", "answer": "我需要买个笔记本电脑。", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 38, "zh": "写字　黑板上　在　你习惯　吗", "answer": "你习惯在黑板上写字吗？", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 39, "zh": "超市　自己　吧　你　去", "answer": "你自己去超市吧。", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 40, "zh": "起飞　半个小时　还有　就　了　飞机", "answer": "飞机还有半个小时就起飞了。", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "三、书写 第二部分", "type_zh": "书写 第二部分", "instruction_zh": "第41–45题：看拼音，写汉字", "instruction_en": "Questions 41-45: Write the characters based on their pinyin.", "items": [{"n": "例", "zh": "没（　）系，别难过，高兴点儿。", "hint_zh": "guān", "answer": "关", "answer_ref": {"book": "workbook", "pages": [87]}}, {"n": 41, "zh": "今天没有（　）阳，天气很冷。", "hint_zh": "tài", "answer": "太", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 42, "zh": "地铁站（　）边有一个咖啡店。", "hint_zh": "xī", "answer": "西", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 43, "zh": "请你把（　）给我。", "hint_zh": "bāo", "answer": "包", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 44, "zh": "老师今天教我们（　）小猫。", "hint_zh": "huà", "answer": "画", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 45, "zh": "这个（　）李箱是谁的？", "hint_zh": "xíng", "answer": "行", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "三、书写 第三部分", "type_zh": "书写 第三部分", "instruction_zh": "第46–50题：辨认汉字，选择正确的汉字填空", "instruction_en": "Questions 46-50: Distinguish the characters and fill in the blanks.", "items": [{"n": "例", "zh": "我不知道________个地方在________儿。", "hint_zh": "（那、哪）", "answer": "那、哪", "answer_ref": {"book": "workbook", "pages": [88]}}, {"n": 46, "zh": "你________经不是小孩子了，要照顾好自________。", "hint_zh": "（已、己）", "answer": "已、己", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 47, "zh": "飞机就要________飞了，我们没有时间去________市了。", "hint_zh": "（起、超）", "answer": "起、超", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 48, "zh": "以前我们是________学，现在他是我的________机。", "hint_zh": "（司、同）", "answer": "同、司", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 49, "zh": "真生________，我刚到车站，公共________车就离开了。", "hint_zh": "（气、汽）", "answer": "气、汽", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 50, "zh": "我发________你最近越来越爱看电________了。", "hint_zh": "（现、视）", "answer": "现、视", "answer_ref": {"book": "teacher", "pages": [178]}}]}, {"n": "四、复习", "type_zh": "复习", "instruction_zh": "第1–2题：根据课文内容填空", "instruction_en": "Questions 1-2: Fill in the blanks based on the texts in the textbook.", "items": [{"n": 1, "zh": "小丽觉得今天________从________边出来了，因为小刚12点以前________要睡觉了。小刚说，他的经理________了，明天小刚8点不到，以后就别去上班了。", "answer": "太阳、西、就、生气", "answer_ref": {"book": "teacher", "pages": [178]}}, {"n": 2, "zh": "小刚去机场迟到了，因为他去机场的路上才发现忘带________了。到了机场，他跟周经理借钱，因为________把他送到机场的时候，他又________自己忘记带________了。飞机就要________了，周经理让小刚把重要的东西放在他那儿。", "answer": "护照、司机、发现、钱包、起飞", "answer_ref": {"book": "teacher", "pages": [178]}}]}]}, "hsk30": {"source": "courseware", "ref": {"book": "hsk30_courseware", "pages": [14, 27, 37]}, "new_words": [{"n": 1, "zh": "外地", "pinyin": "wàidì", "pos": "n.", "en": "other places", "text": 2}, {"n": 2, "zh": "行李", "pinyin": "xíngli", "pos": "n.", "en": "luggage", "text": 2}, {"n": 3, "zh": "箱子", "pinyin": "xiāngzi", "pos": "n.", "en": "box", "text": 2}, {"n": 4, "zh": "游客", "pinyin": "yóukè", "pos": "n.", "en": "tourist", "text": 2}, {"n": 5, "zh": "检票", "pinyin": "jiǎnpiào", "pos": "v.", "en": "ticket check", "text": 3}, {"n": 6, "zh": "晚点", "pinyin": "wǎndiǎn", "pos": "v.", "en": "delayed", "text": 3}, {"n": 7, "zh": "画家", "pinyin": "huàjiā", "pos": "n.", "en": "painter", "text": 4}], "grammar": [], "exercises": [], "unclear": []}, "audio": {"textbook": ["hsk3-textbook-1201.mp3", "hsk3-textbook-1202.mp3", "hsk3-textbook-1203.mp3", "hsk3-textbook-1204.mp3", "hsk3-textbook-1205.mp3"], "workbook": ["hsk3-workbook-12-part1.mp3", "hsk3-workbook-12-part2.mp3", "hsk3-workbook-12-part3.mp3", "hsk3-workbook-12-part4.mp3"]}, "unclear": ["Сурах бичиг PDF х.115 课文3: ханзаар «快点吧» (儿-гүй), PDF х.116 拼音课文-д «Kuài diǎnr ba» — номд байгаагаар хоёуланг нь үлдээсэн (засаагүй).", "课文1-ийн «明天8点不到，以后就别来了» — багшийн номын 课文1 асуулт-хариулт (PDF х.87) «以后就不用去了», дасгалын номын 复习1 (PDF х.88) «以后就别去上班了» гэж өөр хэлбэрээр дамжуулсан. Тус бүрийг номд байгаагаар нь оруулсан.", "Багшийн номын 课文4 复述 提示词 (PDF х.88) «不是……而是……» — сурах бичгийн 课文4-т «不是因为……，是因为……» (而-гүй). Номд байгаагаар нь.", "Сурах бичгийн 练习4 ② «小刚什么时候出差回来？» — 课文2-т «去外地办事» гэж байгаа (出差 энэ хичээлийн 生词 биш); ① «今天呢？» — бичвэрт өнөөдрийн цагийг заагаагүй («这么早就要睡觉了»). Асуултуудыг номд байгаагаар нь.", "Гарчгийн пиньинь: сурах бичиг (PDF х.114) «fàng zài» (зайтай), дасгалын ном (PDF х.82) «fàngzài» (залгаа) — title_pinyin-д сурах бичгийнхийг авсан.", "Сурах бичгийн 注释1 жишээ (4), (8) ба 注释2 жишээ (4) улаанаар хэвлэгдсэн (课文1, 课文3, 课文2-ын өгүүлбэр) — схемд өнгөний талбар байхгүй. 注释2 жишээ (1) «我把照片放在你包里了» нь 课文2-ын «我已经把我的照片放在你的包里了»-ээс ялгаатай (улаанаар биш) — тус бүрийг номд байгаагаар.", "Сурах бичгийн 注释1-д бүтцийн хүснэгт байхгүй; багшийн номд «才＋动词»/«就＋动词» хайрцаг байгаа — teacher.steps-д оруулсан. 注释2-ын structure_rows нь сурах бичгийн тайлбар доторх «A把B+V+在/到+location», «A把B+V+给+sb.» томьёо.", "Сурах бичгийн 练一练 (2 дүрэм × 3), 练习2 选词填空 / 练习3 描述图片 / 练习4 回答问题 ба 热身2 · 运用 болон багшийн номын 语言点操练 (才/就 — зөвхөн эхний хос хариутай; 把 — 目标句) — хариулт сурах бичиг, багшийн номд хэвлэгдээгүй тул answer талбаргүй. Багшийн номын 课文 асуулт-хариулт (teacher.text_questions) нь 练习4-ийн асуултаас өөр; 课文4 «“我”为什么生气？» асуултад багшийн ном хариулт өгөөгүй.", "Багшийн номын 汉字辨认练习 (已/己 · 起/超 · 司/同 · 气/汽 · 现/视 — 组词) хоосон зайтай, хариулт хэвлэгдээгүй; хосуудыг textbook.characters.confusable_pairs-д оруулсан (дасгалын номын 46–50-тай ижил).", "Багшийн номын «练习册相关练习：第78页／一／第一部分，第81页／二／第二部分», «第84页／四», «第84页／三／第三部分» — дасгалын номын хэвлэсэн хуудас (PDF х.82, 85, 88).", "Энэ хичээлд сурах бичгийн 专有名词 хүснэгт, * тэмдэгтэй үг, 汉字知识 болон 文化 хэсэг байхгүй (proper_nouns, culture оруулаагүй). 课文4 гарчиггүй (номд зөвхөн «4»), өгүүлэмжийг 2 өгүүлбэрээр lines-д хуваасан.", "热身1 ⑤ «画儿 huàr», 生词12 «画 huà» — тус бүрийг номд байгаагаар.", "Дасгалын номын сонсгол нэг CD тэмдэгтэй (12) — аудиог hsk3-workbook-12-part1…4.mp3 болгож хэсэг тус бүрт хуваасныг section.audio-д оноосон.", "Дасгалын ном 听力 第三/四部分 — номд зөвхөн сонголтууд хэвлэгдсэн; item.zh-д багшийн номын хавсралтын «问：» асуултыг оруулсан (transcript_zh-д бүтнээр).", "Сурах бичгийн 拼音课文-ын гарчгийн пиньинь (Zài jiā / Zài jiā / Zài jīchǎng / 4.) болон ярилцагчийн нэрийн пиньинь (Xiǎolì, Xiǎogāng, Zhōu Míng) схемд талбаргүй тул lines.pinyin-д зөвхөн яриаг оруулсан.", "Зурагтай даалгаврын (热身1, 练习3, дасгалын номын 听力 第一部分) picture_desc_en / pictures_desc_en нь номд текстгүй тул зургаас товч дүрсэлсэн. Дасгалын ном PDF х.82 зураг C-ийн хоёр талын босоо бичээс бүрэн уншигдахгүй — тайлбарт оруулаагүй.", "HSK 3.0 нэмэлт үгс (BL