values ('hsk3-l15', 'hsk3', 'HSK3', 15, '其他都没什么问题', 'Qítā dōu méi shénme wèntí', 'The rest of them are all OK', '{"level": "hsk3", "lesson": 15, "book": "HSK3", "title_zh": "其他都没什么问题", "title_pinyin": "Qítā dōu méi shénme wèntí", "title_en": "The rest of them are all OK", "textbook": {"ref": {"book": "textbook", "pages": [141, 142, 143, 144, 145, 146, 147, 148, 149, 150]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①节日 jiérì", "②留学生 liúxuéshēng", "③街道 jiēdào", "④世界 shìjiè", "⑤上网 shàng wǎng", "⑥新闻 xīnwén"], "pictures_desc_en": ["A: three young people seen from behind, sitting at computers in a computer room", "B: a folded newspaper with the word “NEWS”", "C: a wide city street lined with high-rise buildings", "D: four smiling young students of different ethnicities holding bags and books", "E: a globe of the Earth", "F: dancers in red costumes holding red lanterns with the character 福"]}, {"instruction_zh": "说说你喜欢什么，不喜欢什么。喜欢的画√，不喜欢的画×。", "instruction_en": "Talk about what you like and what you don’t like. Tick (√) the things you like and cross (×) those you don’t.", "items": ["饮料 yǐnliào | □咖啡 kāfēi | □牛奶 niúnǎi | □茶 chá | □水 shuǐ", "水果 shuǐguǒ | □苹果 píngguǒ | □香蕉 xiāngjiāo | □西瓜 xīguā | □香瓜 xiāngguā", "肉类 ròulèi | □牛肉 niúròu | □羊肉 yángròu | □鸡肉 jīròu | □鱼肉 yúròu", "颜色 yánsè | □红色 hóngsè | □白色 báisè | □绿色 lǜsè | □黑色 hēisè", "运动 yùndòng | □跑步 pǎo bù | □爬山 pá shān | □游泳 yóu yǒng | □打篮球 dǎ lánqiú", "学习 xuéxí | □数学 shùxué | □英语 yīngyǔ | □历史 lìshǐ | □汉语 Hànyǔ"]}], "texts": [{"n": 1, "title_zh": "在办公室", "title_en": "In the office", "kind": "dialogue", "audio": "hsk3-textbook-1501.mp3", "lines": [{"speaker": "大山", "zh": "老师，我来中国留学两年了，但是我的汉语水平提高得一点儿也不快啊。", "pinyin": "Lǎoshī, wǒ lái Zhōngguó liú xué liǎng nián le, dànshì wǒ de Hànyǔ shuǐpíng tí gāo de yìdiǎnr yě bú kuài a."}, {"speaker": "老师", "zh": "你每天认真学习，做练习、完成作业，一直不错啊。", "pinyin": "Nǐ měi tiān rènzhēn xuéxí, zuò liànxí, wán chéng zuòyè, yìzhí búcuò a."}, {"speaker": "大山", "zh": "这是我昨天的作业，您帮我看看对不对。", "pinyin": "Zhè shì wǒ zuótiān de zuòyè, nín bāng wǒ kànkan duì bu duì."}, {"speaker": "老师", "zh": "写得不错，除了这个句子意思有些不清楚外，其他都没什么问题。", "pinyin": "Xiě de búcuò, chúle zhège jùzi yìsi yǒuxiē bù qīngchu wài, qítā dōu méi shénme wèntí."}, {"speaker": "大山", "zh": "谢谢老师！", "pinyin": "Xièxie lǎoshī!"}, {"speaker": "老师", "zh": "以后有什么不明白的地方，可以给我打电话或者发电子邮件。", "pinyin": "Yǐhòu yǒu shénme bù míngbai de dìfang, kěyǐ gěi wǒ dǎ diànhuà huòzhě fā diànzǐ yóujiàn."}], "new_words": [{"n": 1, "zh": "留学", "pinyin": "liú xué", "pos": "v.", "en": "to study abroad", "text": 1}, {"n": 2, "zh": "水平", "pinyin": "shuǐpíng", "pos": "n.", "en": "level, standard", "text": 1}, {"n": 3, "zh": "提高", "pinyin": "tí gāo", "pos": "v.", "en": "to improve", "text": 1}, {"n": 4, "zh": "练习", "pinyin": "liànxí", "pos": "n.", "en": "exercise", "text": 1}, {"n": 5, "zh": "完成", "pinyin": "wán chéng", "pos": "v.", "en": "to complete", "text": 1}, {"n": 6, "zh": "句子", "pinyin": "jùzi", "pos": "n.", "en": "sentence", "text": 1}, {"n": 7, "zh": "其他", "pinyin": "qítā", "pos": "pron.", "en": "the rest", "text": 1}, {"n": 8, "zh": "发", "pinyin": "fā", "pos": "v.", "en": "to send", "text": 1}]}, {"n": 2, "title_zh": "在教室", "title_en": "In the classroom", "kind": "dialogue", "audio": "hsk3-textbook-1502.mp3", "lines": [{"speaker": "学生", "zh": "老师，除了小云，其他人都来了。", "pinyin": "Lǎoshī, chúle Xiǎoyún, qítā rén dōu lái le."}, {"speaker": "老师", "zh": "比赛马上就要开始了，小云怎么还没来？", "pinyin": "Bǐsài mǎshàng jiù yào kāishǐ le, Xiǎoyún zěnme hái méi lái?"}, {"speaker": "学生", "zh": "刚才给她打电话了，她在路上呢。", "pinyin": "Gāngcái gěi tā dǎ diànhuà le, tā zài lùshang ne."}, {"speaker": "老师", "zh": "不等她了，我先给大家讲讲这次比赛的要求和一些需要注意的地方。", "pinyin": "Bù děng tā le, wǒ xiān gěi dàjiā jiǎngjiang zhè cì bǐsài de yāoqiú hé yìxiē xūyào zhù yì de dìfang."}, {"speaker": "学生", "zh": "老师，您放心，今天的比赛我们一定能拿第一。", "pinyin": "Lǎoshī, nín fàngxīn, jīntiān de bǐsài wǒmen yídìng néng ná dì yī."}], "new_words": [{"n": 9, "zh": "要求", "pinyin": "yāoqiú", "pos": "n.", "en": "requirement", "text": 2}, {"n": 10, "zh": "注意", "pinyin": "zhù yì", "pos": "v.", "en": "to pay attention to", "text": 2}], "proper_nouns": [{"zh": "小云", "pinyin": "Xiǎoyún", "en": "Xiaoyun, name of a person"}]}, {"n": 3, "title_zh": "在休息室", "title_en": "In the lounge", "kind": "dialogue", "audio": "hsk3-textbook-1503.mp3", "lines": [{"speaker": "同事", "zh": "现在用电脑上网真方便啊！", "pinyin": "Xiànzài yòng diànnǎo shàng wǎng zhēn fāngbiàn a!"}, {"speaker": "小刚", "zh": "是啊，除了看新闻，人们还可以在网上听歌、看电影、买东西。", "pinyin": "Shì a, chúle kàn xīnwén, rénmen hái kěyǐ zài wǎngshang tīng gē, kàn diànyǐng, mǎi dōngxi."}, {"speaker": "同事", "zh": "对了，你从网上买的那件衣服呢？怎么没见你穿？", "pinyin": "Duìle, nǐ cóng wǎngshang mǎi de nà jiàn yīfu ne? Zěnme méi jiàn nǐ chuān?"}, {"speaker": "小刚", "zh": "那件衣服我穿着有点儿小，给我弟弟了。", "pinyin": "Nà jiàn yīfu wǒ chuānzhe yǒudiǎnr xiǎo, gěi wǒ dìdi le."}, {"speaker": "同事", "zh": "他满意吗？", "pinyin": "Tā mǎnyì ma?"}, {"speaker": "小刚", "zh": "不用花钱，还有新衣服穿，他满意极了。", "pinyin": "Búyòng huā qián, hái yǒu xīn yīfu chuān, tā mǎnyì jí le."}], "new_words": [{"n": 11, "zh": "上网", "pinyin": "shàng wǎng", "pos": "v.", "en": "to surf the Internet", "text": 3}, {"n": 12, "zh": "除了", "pinyin": "chúle", "pos": "prep.", "en": "other than", "text": 3}, {"n": 13, "zh": "新闻", "pinyin": "xīnwén", "pos": "n.", "en": "news", "text": 3}, {"n": 14, "zh": "花", "pinyin": "huā", "pos": "v.", "en": "to spend", "text": 3}, {"n": 15, "zh": "极(了)", "pinyin": "jí (le)", "pos": "adv.", "en": "extremely", "text": 3}]}, {"n": 4, "title_zh": "", "kind": "narrative", "audio": "hsk3-textbook-1504.mp3", "lines": [{"zh": "除了春节、中秋节以外，啤酒节也是这里很重要的一个节日。", "pinyin": "Chúle Chūnjié, Zhōngqiū Jié yǐwài, píjiǔ jié yě shì zhèli hěn zhòngyào de yí ge jiérì."}, {"zh": "这个地方每年夏天都要举行一次啤酒节。", "pinyin": "Zhège dìfang měi nián xiàtiān dōu yào jǔxíng yí cì píjiǔ jié."}, {"zh": "在啤酒节上，你可以喝到世界上不同地方的啤酒。", "pinyin": "Zài píjiǔ jié shang, nǐ kěyǐ hēdào shìjiè shang bùtóng dìfang de píjiǔ."}, {"zh": "除了喝啤酒，你还可以在街道两边看到世界上不同地方的歌舞。", "pinyin": "Chúle hē píjiǔ, nǐ hái kěyǐ zài jiēdào liǎng biān kàndào shìjiè shang bùtóng dìfang de gēwǔ,"}, {"zh": "你想不想了解世界各个地方的啤酒文化？", "pinyin": "nǐ xiǎng bu xiǎng liǎojiě shìjiè gègè dìfang de píjiǔ wénhuà?"}, {"zh": "来这里的啤酒节看看吧。", "pinyin": "Lǎi zhèli de píjiǔ jié kànkan ba."}], "new_words": [{"n": 16, "zh": "节日", "pinyin": "jiérì", "pos": "n.", "en": "festival", "text": 4}, {"n": 17, "zh": "举行", "pinyin": "jǔxíng", "pos": "v.", "en": "to hold (a meeting, an event, etc.)", "text": 4, "star": true}, {"n": 18, "zh": "世界", "pinyin": "shìjiè", "pos": "n.", "en": "world", "text": 4}, {"n": 19, "zh": "街道", "pinyin": "jiēdào", "pos": "n.", "en": "street", "text": 4}, {"n": 20, "zh": "各", "pinyin": "gè", "pos": "pron.", "en": "each", "text": 4, "star": true}, {"n": 21, "zh": "文化", "pinyin": "wénhuà", "pos": "n.", "en": "culture", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "除了……以外，都／还／也……", "title_en": "The Structure “除了……以外，都/还/也……”", "explanation_zh": "“除了……以外，都……”表示在一个范围内，排除一部分，其他的都有相同的情况。其中“以外”可以省略。例如：（1）–（4）\n“除了……以外，还／也……”表示排除一部分，补充其他的。句子的主语放在句首，或者放在“还／也”的前边。例如：（5）–（8）", "explanation_en": "“除了……以外，都…… (all…except…)” indicates that except the part being mentioned, all the others in a specific scope are the same in a certain way. “以外” can be left out. For example: (1)–(4)\n“除了……以外，还/也…… (besides…)” indicates that there are still others besides the part being mentioned. The subject is put at the beginning of the sentence or right before “还/也”. For example: (5)–(8)", "structure_rows": ["除了……以外，都……", "除了……以外，还／也……"], "examples": [{"n": 1, "zh": "除了这个汉字以外，别的汉字我都认识。"}, {"n": 2, "zh": "除了我以外，大家都听懂了。"}, {"n": 3, "zh": "除了这个句子意思有些不清楚外，其他都没什么问题。"}, {"n": 4, "zh": "除了小云，其他人都来了。"}, {"n": 5, "zh": "除了唱歌以外，他还喜欢跳舞。"}, {"n": 6, "zh": "除了汉语以外，我还会说英语。"}, {"n": 7, "zh": "上网除了看新闻，还可以听音乐。"}, {"n": 8, "zh": "除了春节、中秋节以外，啤酒节也是这里很重要的一个节日。"}], "practice_instruction_zh": "练一练　改写句子 Rewrite the sentences.", "practice": [{"n": "例", "zh": "春节很重要，中秋节也是很重要的节日。", "answer": "除了春节以外，中秋节也是很重要的节日。", "answer_ref": {"book": "textbook", "pages": [144]}}, {"n": 1, "zh": "我喜欢春天，也喜欢夏天。"}, {"n": 2, "zh": "我们班只有王老师是中国人，其他人都是外国人。"}, {"n": 3, "zh": "我只想吃西瓜，其他水果都不想吃。"}]}, {"n": 2, "title_zh": "疑问代词活用2", "title_en": "Flexible Use of Interrogative Pronouns 2", "explanation_zh": "汉语中，“什么”可以做指示代词，用来代替不确定的人或事物，表达的语气更客气。去掉“什么”以后，句子的意思不变。例如：（1）–（4）", "explanation_en": "In Chinese, “什么” can be used as a demonstrative pronoun instead of an indefinite person or thing, making the tone politer. The meaning of the sentence won’t change if “什么” is left out. For example: (1)–(4)", "examples": [{"n": 1, "zh": "这个饭馆有没有什么特别好吃的菜？"}, {"n": 2, "zh": "周末你有没有什么打算？"}, {"n": 3, "zh": "你写得很好，没什么问题。"}, {"n": 4, "zh": "以后有什么不明白的地方，可以给我打电话或者发电子邮件。"}], "practice_instruction_zh": "练一练　完成对话 Complete the dialogues.", "practice": [{"n": 1, "zh": "A：________。 B：周末我跟朋友打算去爬山。"}, {"n": 2, "zh": "A：________ B：对不起，我很少看电影，不知道哪个好看。"}, {"n": 3, "zh": "A：________ B：没有了，老师，我都懂了。"}]}, {"n": 3, "title_zh": "程度的表达：极了", "title_en": "“极了” Used to Indicate Degree", "explanation_zh": "汉语中，表达最高程度可以用“形容词／心理动词＋极了”。例如：（1）–（4）", "explanation_en": "In Chinese, the superlative degree can be expressed using “Adj/Mental V + 极了”. For example: (1)–(4)", "structure_rows": ["形容词／心理动词＋极了"], "examples": [{"n": 1, "zh": "我的小狗可爱极了。"}, {"n": 2, "zh": "今天天气冷极了。"}, {"n": 3, "zh": "那件衣服我喜欢极了。"}, {"n": 4, "zh": "他满意极了。"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "外边________，我们别出去了，在家里休息吧。"}, {"n": 2, "zh": "我工作了一天，________。"}, {"n": 3, "zh": "她唱歌________，大家都爱听。"}]}], "exercises": [{"n": 1, "type_zh": "朗读", "instruction_zh": "朗读下列短语和句子", "instruction_en": "Read the following phrases and sentences aloud.", "audio": "hsk3-textbook-1505.mp3", "items": [{"n": 1, "zh": "其他：其他人／其他问题／其他时间／除了小云，其他人都来了。"}, {"n": 2, "zh": "水平：汉语水平／电脑水平／水平高／我的汉语水平提高得一点儿也不快。"}, {"n": 3, "zh": "完成：完成作业／完成工作／没完成／你每天认真学习，做练习、完成作业。"}, {"n": 4, "zh": "上网：上网看电影／上网聊天儿／上一会儿网／现在用电脑上网真方便啊！"}, {"n": 5, "zh": "注意：很注意／没注意／注意身体／我给大家讲讲需要注意的地方。"}]}, {"n": 2, "type_zh": "选词填空", "instruction_zh": "选择恰当的词语填空", "instruction_en": "Choose the proper words to fill in the blanks.", "word_bank": [["花", "发", "练习", "提高", "完成"], ["文化", "句子", "新闻", "节日", "世界"]], "items": [{"n": 1, "zh": "王经理，电子邮件我已经给您________过去了。"}, {"n": 2, "zh": "你每天跟谁________口语？"}, {"n": 3, "zh": "已经夜里12点多了，但是今天的作业我还没________。"}, {"n": 4, "zh": "这个月我的钱都________完了，不能再买新衣服了。"}, {"n": 5, "zh": "我在这里只学了三个月汉语，但是水平________了不少。"}, {"n": 6, "zh": "A：今天听写五个________，请大家准备好笔和纸。 B：五个？老师，太多了！"}, {"n": 7, "zh": "A：________上有多少个国家？你知道吗？ B：这个……，我真不知道。"}, {"n": 8, "zh": "A：你为什么想去那个地方旅游？ B：我对那儿的________很感兴趣。"}, {"n": 9, "zh": "A：你们国家最重要的________是什么？ B：当然是春节！"}, {"n": 10, "zh": "A：刚才电视上的那条________真有意思！ B：你快说说。"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "A：我们去这家饭馆吧，这儿的服务好________。 B：我也听说过，________服务好________，菜________。 A：这儿________好吃的菜？ B：这儿的鱼做得最好。", "picture_desc_en": "The interior of an elegant restaurant with tables and chairs and round lights on the ceiling."}, {"n": 2, "zh": "A：我想快点儿________汉语________，应该怎么做呢？ B：你要多听、多说、多做________。 A：________更容易的吗？ B：没有了。", "picture_desc_en": "Two young women talking at a desk in a lecture hall, with other students sitting behind them."}, {"n": 3, "zh": "A：有________喝的吗？ B：这儿有一些咖啡。 A：________，还有其他的吗？ B：那边还有牛奶和茶。", "picture_desc_en": "Two glass coffee pots on a warming plate, with a small silver jug beside them."}, {"n": 4, "zh": "A：经理，今天的工作我们已经________了。 B：好________！明天的工作大家有问题吗？ A：没________问题。 B：好的，大家一起努力。", "picture_desc_en": "People in business suits sitting around a white table in a meeting."}]}, {"n": 4, "type_zh": "回答问题", "instruction_zh": "根据课文回答问题", "instruction_en": "Answer the questions according to the texts.", "items": [{"n": 1, "zh": "老师觉得大山的汉语怎么样？"}, {"n": 2, "zh": "大家都来参加比赛了吗？谁没来？"}, {"n": 3, "zh": "老师现在在做什么？"}, {"n": 4, "zh": "大家可以上网做什么？"}, {"n": 5, "zh": "小刚从网上买的那件衣服怎么了？"}, {"n": 6, "zh": "啤酒节上可以做什么？"}]}], "characters": {"knowledge_title_zh": "旧字新词", "knowledge_zh": "读读下面的词语，想想组成的新词是什么意思。", "knowledge_en": "Read the following words and guess the meanings of the newly-formed ones.", "word_game": [{"parts": ["电影", "节日"], "result": "电影节"}, {"parts": ["春天", "节日"], "result": "春节"}, {"parts": ["文化", "节日"], "result": "文化节"}], "confusable_pairs": [["炼", "练"], ["求", "球"], ["网", "风"], ["目", "日"], ["世", "也"]]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，互相询问对方对本班学生的态度。一人问，一人回答，并记录。", "instruction_en": "Work in pairs. Ask about each other’s opinions on your classmates, and take notes.", "example_zh": ["例如：A：我们班谁最努力？", "B：我们班王美努力极了。", "A：为什么？", "B：她每天下了课就去图书馆学习。", "提示词：忙　可爱　认真　热情　聪明　客气"]}, {"title_zh": "小组活动", "instruction_zh": "3~4人一组，介绍你们国家的一个节日。说说是什么时候，大家怎么过节、吃什么、喝什么、做什么。一人做记录，并向全班汇报。", "instruction_en": "Work in groups of 3-4. Introduce one of the festivals in your country, including when it is, how people celebrate it, what to eat and drink, and what to do. Ask one member to take notes and report to the whole class.", "example_zh": ["例如：春节是我们国家的重要节日。春节一般在每年的1月或2月。过春节的时候，人们都要回家，除了一起吃饭以外，一家人还一起看电视台的春节晚会。", "表格：| | 什么节日 | 什么时候 | 怎么过节 |", "| 1 | 春节 | 1月或2月 | 一家人一起吃饭、看春节晚会 |", "| | | | |", "| | | | |", "| | | | |", "| | | | |"]}], "saying": {"zh": "一是一，二是二", "pinyin": "Yī shì yī, èr shì èr", "en": "Call a spade a spade", "explanation_zh": "“一是一，二是二”，这句话的意思是保留事物的真实面貌，不做任何改变，常常用来比喻一个人说话做事很诚实，不骗别人。", "explanation_en": "The saying “一是一，二是二” means to keep the true look of something without making any alteration. It is often used metaphorically to describe someone who is honest in word and deed and doesn’t lie."}, "culture": {"title_zh": "中国人过生日吃什么", "body_zh": "西方人过生日都要吃生日蛋糕，中国人的习俗是吃面条。面条长长的，表示“长寿”的意思。因此，生日面也叫长寿面。在你们国家，人们过生日时吃什么呢？", "body_en": "What Food Chinese People Eat on Their Birthdays. Westerners eat cakes on their birthdays, while by tradition, Chinese people eat noodles. The noodles, being long, stand for “longevity”, which is why birthday noodles are also called longevity noodles. What do people eat on their birthdays in your country?"}}, "teacher": {"ref": {"book": "teacher", "pages": [103, 104, 105, 106, 107, 108, 109]}, "objectives_zh": ["重点词语：学生能够熟练掌握：“提高、完成、其他、发、花”的词义和用法", "语言点：学生能够了解并掌握：（1）“除了……以外，都／还／也……”表示范围（2）疑问代词活用2：什么（3）“极了”表示程度很高", "汉字：学生能够：根据已学生词猜测出3个旧字新词“电影节、春节、文化节”的意思", "功能：学生能够：（1）用“除了……以外，都／还／也……”表示包括、排除等内容（2）用“什么”表示不确定的人或事物（3）用“极了”表示最高程度"], "steps": [{"title_zh": "复习旧课", "body_zh": "1 教师展示第14课的热身图片，请学生根据图片说出生词。\n2 教师根据第14课的内容进行提问。\n（1）你做好了一个菜，请朋友帮你拿进房间去，要怎么说？\n（2）老师要去你家玩儿，你怎么准备？\n（3）你的拿手菜是什么？怎么做？请你教教我。\n（4）我想去几个地方旅行，应该怎么去？\n（5）在我们的学校，可以学到什么？你最喜欢学什么？"}, {"title_zh": "学习新课 1 热身", "body_zh": "热身1：教师可依次朗读热身部分的词语，要求学生集体或单个说出图片对应的编号，教师评判正误；最后全体学生齐读热身环节所有词语，要求语音标准，声调准确。\n答案：①F　②D　③C　④E　⑤A　⑥B\n热身2：可留至语言点（1）“除了……以外，都／还／也……”导入时使用。"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n留学、水平、提高、练习、完成、句子、其他、发、要求、注意、上网、除了、新闻、花、极（了）、节日、举行、世界、街道、各、文化、小云\n· 教师先带领学生快速认读一遍生词；\n· 取消拼音，带领学生再次认读；\n· 请单个学生独自认读2-3个生词；\n· 最后全班一起快速认读所有的生词。\n（2）生词讲解方式\n· 直观法（如图片、照片、实物等）展示：留学、上网、新闻、节日、世界、街道\n· 对比法展示：其他—别的\n· 启发式引导：要求、注意\n上课的时候，老师有什么要求？——老师要求大家安静，要求大家认真听课。\n考试的时候应该注意什么？——注意别写错字。\n（3）重点生词扩展及常用搭配\n提高—提高水平—水平提高了—没提高\n　—提高得很快—大家的汉语水平提高得很快。\n完成—完成作业—完成练习—完成句子—今天的工作你完成了吗？\n其他—其他人—其他事—我只去过北京，其他地方都没去过。\n发—发短信—发电子邮件—今天的作业是给老师发一个中文电子邮件。\n　—发出去—发过来—电子邮件没发出去。\n花—花钱—花时间—我花了三个小时才写完作业。\n练习册相关练习：第99页／一／第一部分，第102页／二／第二部分"}, {"title_zh": "3 语言点（1）除了……以外，都／还／也……", "body_zh": "① 语言点解析\n“除了……以外，都……”表示在一个范围内，排除一部分，其他的都有相同的情况。“除了……以外，还／也……”表示排除一部分，补充其他的。\n② 语言点导入\n教师可利用本课热身2导入语言点。\n教师带领学生熟悉表格中所有词语，学生两人一组，合作完成热身2。\n教师请学生向自己提问。\n学生：老师，您喜欢喝什么饮料？\n教师：我只喜欢喝水，茶、咖啡、牛奶我都不喜欢喝。\n教师引导学生说出：除了水以外，老师都不喜欢喝。\n教师在黑板上画出教师喜欢喝的饮料“水”，帮助学生理解语言点。\n教师请学生再次向自己提问。\n学生：老师，您喜欢喝什么饮料？\n教师：我喜欢喝水，也喜欢喝茶、咖啡和牛奶。\n教师引导学生说出：除了水以外，老师还／也喜欢喝茶、咖啡和牛奶。\n教师在黑板上画出教师喜欢喝的饮料“水”“咖啡”“牛奶”“茶”，帮助学生理解语言点。\n③ 语言点操练\n教师可根据热身2的表格操练语言点。\n学生向教师提问，教师回答后，请学生说出目标句。\n目标句：除了西瓜以外，老师还喜欢吃苹果。\n　　　　除了鱼肉以外，其他肉老师都不喜欢吃。\n　　　　除了红色以外，老师还喜欢绿色和白色。\n　　　　除了爬山以外，其他运动老师都不喜欢。\n　　　　除了数学以外，其他课老师都喜欢。\n④ 语言点扩展练习\n教师利用热身2，让学生两人一组互相询问并回答。\n注意：其中“以外”可以完全省略或省略成“外”。"}, {"title_zh": "3 语言点（2）疑问代词活用2", "body_zh": "① 语言点解析\n汉语中，“什么”可以做指示代词，用来代替不确定的人或事物，表达的语气更客气。去掉“什么”以后，句子的意思不变。\n② 语言点导入\n教师根据实际情况，提问并引入语言点。\n教师：我想知道这个饭馆儿好吃的菜。怎么问？\n学生：这个饭馆儿有什么好吃的菜？\n教师引导学生说出：这个饭馆儿有什么好吃的菜吗？\n　　　　　　　　　这个饭馆儿有没有什么好吃的菜？\n教师：这个饭馆儿没有好吃的菜。怎么说？\n教师引导学生说出：这个饭馆儿没什么好吃的菜。\n③ 语言点操练\n教师给出情境，让学生说出句子。\n情境及目标句：\n我想知道这个月有哪些有意思的电影。——这个月有什么有意思的电影吗？\n我饿了，想吃东西。——有什么吃的吗？我饿了。\n这个商店没有好看的衣服。——这个商店没什么好看的衣服。\n我很忙，没有时间休息。——我很忙，没什么时间休息。\n④ 语言点扩展练习\n教师可根据实际情况提问，请学生回答。\n每天下课以前，老师会说什么？\n你去商店买东西的时候，服务员会说什么？"}, {"title_zh": "3 语言点（3）程度的表达：极了", "body_zh": "① 语言点解析\n汉语中，表达最高程度可以用“形容词／心理动词＋极了”。\n② 语言点导入\n教师就地取材，利用学生作业，提问并引入语言点。\n教师：他的字漂亮不漂亮？\n学生：非常漂亮。\n教师引导学生说出：他的字漂亮极了。\n③ 语言点操练\n教师给出一些学过的形容词，请学生互相询问并回答。\n可爱、舒服、容易、重要\n例：可爱：A：你觉得什么最可爱？\n　　　　　B：我觉得小狗可爱极了。\n④ 语言点扩展练习\n教师让本班学生夸夸自己的班级。\n我们班学生________。"}, {"title_zh": "4 课文 课文1", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的（大山）有什么问题吗？——他觉得他的汉语水平提高得一点儿也不快。\n女的（老师）觉得大山学得怎么样？——老师觉得他学得一直不错，每天认真学习，做练习，完成作业。\n大山昨天的作业做得怎么样？——做得不错，除了有一个句子意思有些不清楚外，其他都没什么问题。\n以后有不明白的地方，大山可以怎么办？——可以给老师打电话或者发电子邮件。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：我……了，但是……。\nB：你……，一直不错啊。\nA：这是……，你／您帮我……。\nB：……，除了……外，其他……。\nA：谢谢……！\nB：以后有什么……，可以……。"}, {"title_zh": "4 课文 课文2", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n大家都来了吗？——除了小云，其他人都来了。\n小云现在在哪儿？——小云在路上。\n老师要做什么？——老师要给大家讲讲这次比赛的要求和一些需要注意的地方。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：……，除了……，……。\nB：……，开始了，……还没来？\nA：刚才……，她／他……。\nB：不等她／他了，我先……。\nA：……，您放心，……。"}, {"title_zh": "4 课文 课文3", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n为什么现在的生活很方便？——因为除了看新闻，还可以在网上听歌、看电影、买东西。\n男的为什么没穿在网上买的那件新衣服？——因为有点儿小，他给他弟弟了。\n男的的弟弟为什么很满意？——因为不用花钱，还有新衣服穿，所以他满意极了。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）教师给提示词，带领学生复述课文。\n提示词：上网、除了……，还……、网上、满意、花钱、极了"}, {"title_zh": "4 课文 课文4", "body_zh": "（1）快速阅读，并回答：在啤酒节上可以做什么？\n（2）教师领读课文两遍，并回答下列问题：\n这个地方有什么重要的节日吗？——这个地方除了春节、中秋节以外，还有啤酒节。\n啤酒节什么时候举行？——啤酒节每年夏天举行。\n在啤酒节上可以做什么？——在啤酒节上，除了可以喝到世界上不同地方的啤酒以外，还可以看到世界上不同地方的歌舞。\n你想了解世界各个地方的啤酒文化，应该怎么办？——去啤酒节看看。\n（3）教师给提示词，带领学生复述课文。\n提示词：除了……以外、也、节日、喝啤酒、街道、歌舞、了解、啤酒文化\n（4）教师请学生仿照课文，说说自己住的地方有什么重要的节日，在这个节日里，人们都做什么。\n练习册相关练习：第105页／四"}, {"title_zh": "5 汉字", "body_zh": "旧字新词：\n① 教师领读以前学过的词语和新词，并让学生猜猜新词的意思。\n· 领读：电影、节日、电影节\n问学生：在“电影节”上可以做什么？——看各国的电影。\n· 领读：春天、节日、春节\n问学生：你们国家过“春节”吗？中国人过“春节”的时候做什么？——包饺子、团聚、一起吃饭等。\n· 领读：文化、节日、文化节\n问学生：在“文化节”上可以做什么？——了解世界各个地方的文化。\n扩展提问：还有什么“节”？——音乐节、旅游节、中秋节。（根据实际情况选用）\n② 教师领读新词扩展，通过情景，理解新词的意思和用法：\n电影节：中国电影节／大学生电影节／今年的电影节什么时候开始？\n春节：过春节／春节前的准备／过春节的时候，谁最高兴？\n文化节：世界文化节／文化节每两年举行一次／今年的文化节在我们学校举行。\n汉字辨认练习：\n辨认下列汉字并组词。\n炼：________、________　求：________、________\n练：________、________　球：________、________\n网：________、________　目：________、________\n风：________、________　日：________、________\n世：________、________\n也：________、________\n练习册相关练习：第105页／三／第三部分"}, {"title_zh": "6 补充课堂活动——根据词卡写句子", "body_zh": "4-5个学生一组，每组随机抽取3-4个词卡，用这些词完成一个句子，比比哪组能用最短的时间写出正确的句子。\n参考词语：留学、水平、提高、练习、完成、句子、其他、发、要求、注意、上网、除了、新闻、花、极（了）、节日、世界、街道、文化……"}, {"title_zh": "7 俗语", "body_zh": "教师引导学生理解俗语的含义。注意这里的“一”“二”指的是事情的本来面貌，比如：请你一是一、二是二地把这件事情告诉经理，不要说假话。"}, {"title_zh": "8 本课小结", "body_zh": "· 语言点：用“除了……以外，都／还／也……”表示范围\n　　　　　用“什么”代替不确定的人或物\n　　　　　用“极了”表示程度很高\n· 汉　字：旧字新词：电影节、春节、文化节"}, {"title_zh": "文化：中国人过生日吃什么", "body_zh": "1 文化点解析\n① 古代中国人认为脸长寿命就长，“脸”就是“面”，因此长长的面条就表示长长的脸，寓意长寿。除了长寿面，还有寿桃等，也寓意长寿。\n② 中国人过生日的时候还有吃鸡蛋的习俗，寓意平安和健康。\n2 文化点参考处理方式\n· 教师介绍中国人过生日吃长寿面、寿桃和鸡蛋的习俗。\n· 请学生说说在自己国家，过生日的时候吃什么，为什么有这样的习俗。"}], "notes_zh": ["注意：其中“以外”可以完全省略或省略成“外”。（语言点1）", "扩展提问：还有什么“节”？——音乐节、旅游节、中秋节。（根据实际情况选用）（汉字·旧字新词）", "注意这里的“一”“二”指的是事情的本来面貌，比如：请你一是一、二是二地把这件事情告诉经理，不要说假话。（俗语）"], "warmup_answers_zh": ["热身1 答案：①F　②D　③C　④E　⑤A　⑥B", "热身2：可留至语言点（1）“除了……以外，都／还／也……”导入时使用。"], "text_questions": [{"text": 1, "q_zh": "男的（大山）有什么问题吗？", "a_zh": "他觉得他的汉语水平提高得一点儿也不快。"}, {"text": 1, "q_zh": "女的（老师）觉得大山学得怎么样？", "a_zh": "老师觉得他学得一直不错，每天认真学习，做练习，完成作业。"}, {"text": 1, "q_zh": "大山昨天的作业做得怎么样？", "a_zh": "做得不错，除了有一个句子意思有些不清楚外，其他都没什么问题。"}, {"text": 1, "q_zh": "以后有不明白的地方，大山可以怎么办？", "a_zh": "可以给老师打电话或者发电子邮件。"}, {"text": 2, "q_zh": "大家都来了吗？", "a_zh": "除了小云，其他人都来了。"}, {"text": 2, "q_zh": "小云现在在哪儿？", "a_zh": "小云在路上。"}, {"text": 2, "q_zh": "老师要做什么？", "a_zh": "老师要给大家讲讲这次比赛的要求和一些需要注意的地方。"}, {"text": 3, "q_zh": "为什么现在的生活很方便？", "a_zh": "因为除了看新闻，还可以在网上听歌、看电影、买东西。"}, {"text": 3, "q_zh": "男的为什么没穿在网上买的那件新衣服？", "a_zh": "因为有点儿小，他给他弟弟了。"}, {"text": 3, "q_zh": "男的的弟弟为什么很满意？", "a_zh": "因为不用花钱，还有新衣服穿，所以他满意极了。"}, {"text": 4, "q_zh": "（快速阅读）在啤酒节上可以做什么？"}, {"text": 4, "q_zh": "这个地方有什么重要的节日吗？", "a_zh": "这个地方除了春节、中秋节以外，还有啤酒节。"}, {"text": 4, "q_zh": "啤酒节什么时候举行？", "a_zh": "啤酒节每年夏天举行。"}, {"text": 4, "q_zh": "在啤酒节上可以做什么？", "a_zh": "在啤酒节上，除了可以喝到世界上不同地方的啤酒以外，还可以看到世界上不同地方的歌舞。"}, {"text": 4, "q_zh": "你想了解世界各个地方的啤酒文化，应该怎么办？", "a_zh": "去啤酒节看看。"}], "summary_zh": "语言点：用“除了……以外，都／还／也……”表示范围；用“什么”代替不确定的人或物；用“极了”表示程度很高。汉字：旧字新词：电影节、春节、文化节。"}, "workbook": {"ref": {"book": "workbook", "pages": [103, 104, 105, 106, 107, 108, 109]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 1-5: Choose the right picture for each dialogue you hear.", "audio": "hsk3-workbook-15-part1.mp3", "items": [{"n": "例", "zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "transcript_zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "options": {"A": "[picture] a hand touching the screen of a mobile phone", "B": "[picture] a woman at a table looking at papers, and a man beside her holding a card and gesturing", "C": "[picture] two young men playing basketball outdoors", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man and a woman sitting at a restaurant table, with a waiter standing beside them", "F": "[picture] a woman in glasses holding a cup and reading a newspaper"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [103]}}, {"n": 1, "zh": "", "options": {"A": "[picture] a hand touching the screen of a mobile phone", "B": "[picture] a woman at a table looking at papers, and a man beside her holding a card and gesturing", "C": "[picture] two young men playing basketball outdoors", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man and a woman sitting at a restaurant table, with a waiter standing beside them", "F": "[picture] a woman in glasses holding a cup and reading a newspaper"}, "transcript_zh": "男1：你现在打篮球的水平越来越高了。 男2：我觉得没什么提高，还跟以前一样。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 2, "zh": "", "options": {"A": "[picture] a hand touching the screen of a mobile phone", "B": "[picture] a woman at a table looking at papers, and a man beside her holding a card and gesturing", "C": "[picture] two young men playing basketball outdoors", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man and a woman sitting at a restaurant table, with a waiter standing beside them", "F": "[picture] a woman in glasses holding a cup and reading a newspaper"}, "transcript_zh": "男：你要发电子邮件吗？我去把电脑打开。 女：不用，我的手机能上网，用手机也能发。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 3, "zh": "", "options": {"A": "[picture] a hand touching the screen of a mobile phone", "B": "[picture] a woman at a table looking at papers, and a man beside her holding a card and gesturing", "C": "[picture] two young men playing basketball outdoors", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man and a woman sitting at a restaurant table, with a waiter standing beside them", "F": "[picture] a woman in glasses holding a cup and reading a newspaper"}, "transcript_zh": "男1：你们这儿除了鱼以外，还有什么好吃的吗？ 男2：今天的羊肉也很新鲜，您要不要来一个？", "answer": "E", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 4, "zh": "", "options": {"A": "[picture] a hand touching the screen of a mobile phone", "B": "[picture] a woman at a table looking at papers, and a man beside her holding a card and gesturing", "C": "[picture] two young men playing basketball outdoors", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man and a woman sitting at a restaurant table, with a waiter standing beside them", "F": "[picture] a woman in glasses holding a cup and reading a newspaper"}, "transcript_zh": "男：这个月你怎么花了这么多钱？ 女：我记得我只买了几件衣服，其他也没买什么啊。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 5, "zh": "", "options": {"A": "[picture] a hand touching the screen of a mobile phone", "B": "[picture] a woman at a table looking at papers, and a man beside her holding a card and gesturing", "C": "[picture] two young men playing basketball outdoors", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a man and a woman sitting at a restaurant table, with a waiter standing beside them", "F": "[picture] a woman in glasses holding a cup and reading a newspaper"}, "transcript_zh": "男：看什么呢？今天报纸上有什么新闻吗？ 女：我没看新闻，我看看今天天气怎么样。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听句子，判断对错", "instruction_en": "Questions 6-10: Decide whether the statements are true or false based on the sentences you hear.", "audio": "hsk3-workbook-15-part2.mp3", "items": [{"n": "例1", "zh": "他希望自己很健康。", "transcript_zh": "为了让自己更健康，他每天都花一个小时去锻炼身体。", "answer": "√", "answer_ref": {"book": "workbook", "pages": [104]}}, {"n": "例2", "zh": "那块儿手表不是他的。", "transcript_zh": "今天我想早点儿回家。看了看手表，才5点。过了一会儿再看表，还是5点，我这才发现我的手表不走了。", "answer": "×", "answer_ref": {"book": "workbook", "pages": [104]}}, {"n": 6, "zh": "叔叔希望我花钱买本书。", "transcript_zh": "叔叔让我花时间认真地读一读这本书，他说书里的故事对他的影响很大。他希望我也能从书中学到一些东西。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 7, "zh": "弟弟每天晚上都上网看新闻。", "transcript_zh": "每天晚上的这个时间，电视上除了新闻以外，没什么其他节目，所以弟弟只好上网看自己喜欢的电视节目。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 8, "zh": "女儿边留学边在饭馆工作。", "transcript_zh": "女儿在国外留学三年了，除了每天上课学习以外，课后还要去饭馆帮忙洗盘子。虽然每个月我们都给她不少钱，但是她说花自己的钱更舒服。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 9, "zh": "老方每天都看报纸。", "transcript_zh": "老方每天都坐在办公室中间的那把椅子上，边看报纸边喝茶，报纸上有什么有意思的新闻，他都读给我们听。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 10, "zh": "他们以后能经常见面。", "transcript_zh": "这个短期班下周日就要结束了，以后我们不能像现在这样经常见面了，有什么事情可以给我打电话或者发电子邮件。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听短对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the short dialogues and choose the right answers.", "audio": "hsk3-workbook-15-part3.mp3", "items": [{"n": "例", "zh": "男的想让小王做什么？", "transcript_zh": "男：小王，帮我开一下门，好吗？谢谢！ 女：没问题。您去超市了？买了这么多东西。 问：男的想让小王做什么？", "options": {"A": "开门", "B": "拿东西", "C": "去超市买东西"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [104]}}, {"n": 11, "zh": "女的觉得这个地方怎么样？", "options": {"A": "环境不好", "B": "商店很远", "C": "夏天很热"}, "transcript_zh": "男：你在这个地方生活了二十年，对这儿很了解了吧？ 女：对，这个地方除了夏天太热以外，其他都很好。环境不错，买东西也方便。 问：女的觉得这个地方怎么样？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 12, "zh": "男的不让洗什么？", "options": {"A": "裤子", "B": "裙子", "C": "衬衫"}, "transcript_zh": "女：除了这条裤子以外，还有什么要洗的吗？ 男：那条裤子是干净的，不用洗，你把那两件衬衫洗了吧。 问：男的不让洗什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 13, "zh": "女的想要什么样的房子？", "options": {"A": "有电梯的", "B": "没电梯的", "C": "安静的"}, "transcript_zh": "男：除了安静以外，您对房子还有什么要求吗？有电梯的还是没电梯的？ 女：我只有这一个要求，你们有这样的房子吗？ 问：女的想要什么样的房子？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 14, "zh": "女的写字写得怎么样？", "options": {"A": "不认真", "B": "特别漂亮", "C": "特别慢"}, "transcript_zh": "男：你的字写得漂亮极了，你是怎么写的？能教教我吗？ 女：开始的时候除了认真学、慢慢写以外，还要努力练习，这样才能越写越快，越写越漂亮。 问：女的写字写得怎么样？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 15, "zh": "女的觉得谁是最重要的人？", "options": {"A": "男的", "B": "自己", "C": "穿得漂亮的人"}, "transcript_zh": "男：你今天穿得这么漂亮，要见什么重要的人吗？ 女：除了你以外，还有更重要的人吗？今天是中秋节，我们一起去看个电影吧。 问：女的觉得谁是最重要的人？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "一、听力 第四部分", "type_zh": "听力 第四部分", "instruction_zh": "第16–20题：听长对话，选择正确答案", "instruction_en": "Questions 16-20: Listen to the dialogues and choose the right answers.", "audio": "hsk3-workbook-15-part4.mp3", "items": [{"n": "例", "zh": "男的在做什么？", "transcript_zh": "女：晚饭做好了，准备吃饭了。 男：等一会儿，比赛还有三分钟就结束了。 女：快点儿吧，一起吃，菜冷了就不好吃了。 男：你先吃，我马上就看完了。 问：男的在做什么？", "options": {"A": "洗澡", "B": "吃饭", "C": "看电视"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [105]}}, {"n": 16, "zh": "关于男的，可以知道什么？", "options": {"A": "喜欢夏天", "B": "不喜欢热", "C": "四个季节都喜欢"}, "transcript_zh": "女：大明，一年四季，你最喜欢哪个季节？ 男：我啊，除了夏天以外，我都喜欢。 女：能告诉我为什么吗？ 男：我怕热啊，这儿的夏天热极了，你不觉得吗？ 问：关于男的，可以知道什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 17, "zh": "关于那个房子，可以知道什么？", "options": {"A": "环境不错", "B": "不太安静", "C": "不太干净"}, "transcript_zh": "女：我们新买的房子就在刚才过去的那条街上。 男：是吗？我看环境很好。 女：没错，那儿的街道除了很干净以外，也很安静，附近还有个花园。 男：有树有草，好极了！真想快点儿搬过去。 问：关于那个房子，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 18, "zh": "女的觉得这件衣服怎么样？", "options": {"A": "颜色不好", "B": "不便宜", "C": "太大了"}, "transcript_zh": "男：这条裙子不大不小，真不错。 女：颜色也好看，我穿着它去参加朋友的生日晚会，一定漂亮极了。 男：那你为什么不买？有什么不满意吗？ 女：除了太贵以外，没什么不满意的。 问：女的觉得这件衣服怎么样？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 19, "zh": "女的的手机有什么问题？", "options": {"A": "不能打电话", "B": "没有声音", "C": "不能上网"}, "transcript_zh": "女：您好，我的手机从前天开始就不能上网了，您帮我看看吧。 男：除了上不去网以外，还有什么其他问题吗？ 女：打电话的时候声音特别小，经常听不清楚。 男：您别着急，我马上帮您看看。 问：女的的手机有什么问题？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 20, "zh": "在这个宾馆里做什么不用花钱？", "options": {"A": "喝水", "B": "上网", "C": "打电话"}, "transcript_zh": "男：您好，我在这儿只住了一个星期，怎么这么贵？ 女：对不起，我们宾馆除了水以外，房间里其他吃的、喝的都是要花钱的。 男：上网和打电话也要自己花钱吗？ 女：对，上网每个小时5块，打电话一分钟也是5块。 问：在这个宾馆里做什么不用花钱？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第21–25题：选择合适的问答", "instruction_en": "Questions 21-25: Match the two parts of the same dialogue.", "items": [{"n": "例", "zh": "你知道怎么去那儿吗？", "options": {"A": "参加会议的人都到了吗？", "B": "没什么有意思的，我们上网看个电影吧。", "C": "请问，这两个手机有什么不一样吗？", "D": "除了半个西瓜以外，没有其他水果了。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我想提高汉语水平，应该做些什么呢？"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [106]}}, {"n": 21, "zh": "你要多听、多说，还要多跟中国朋友练习。", "options": {"A": "参加会议的人都到了吗？", "B": "没什么有意思的，我们上网看个电影吧。", "C": "请问，这两个手机有什么不一样吗？", "D": "除了半个西瓜以外，没有其他水果了。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我想提高汉语水平，应该做些什么呢？"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 22, "zh": "冰箱里还有什么水果吗？", "options": {"A": "参加会议的人都到了吗？", "B": "没什么有意思的，我们上网看个电影吧。", "C": "请问，这两个手机有什么不一样吗？", "D": "除了半个西瓜以外，没有其他水果了。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我想提高汉语水平，应该做些什么呢？"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 23, "zh": "这个黑色的手机字比较大，红色的小一些。", "options": {"A": "参加会议的人都到了吗？", "B": "没什么有意思的，我们上网看个电影吧。", "C": "请问，这两个手机有什么不一样吗？", "D": "除了半个西瓜以外，没有其他水果了。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我想提高汉语水平，应该做些什么呢？"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 24, "zh": "除了常笑以外，大家都到了。", "options": {"A": "参加会议的人都到了吗？", "B": "没什么有意思的，我们上网看个电影吧。", "C": "请问，这两个手机有什么不一样吗？", "D": "除了半个西瓜以外，没有其他水果了。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我想提高汉语水平，应该做些什么呢？"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 25, "zh": "电视上有什么好看的节目吗？", "options": {"A": "参加会议的人都到了吗？", "B": "没什么有意思的，我们上网看个电影吧。", "C": "请问，这两个手机有什么不一样吗？", "D": "除了半个西瓜以外，没有其他水果了。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "我想提高汉语水平，应该做些什么呢？"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第26–30题：选择合适的词语填空", "instruction_en": "Questions 26-30: Choose the proper words to fill in the brackets.", "word_bank": [["A 上网", "B 练习", "C 完成", "D 节日", "E 声音", "F 世界"]], "items": [{"n": "例", "zh": "她说话的（　）多好听啊！", "options": {"A": "上网", "B": "练习", "C": "完成", "D": "节日", "E": "声音", "F": "世界"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [106]}}, {"n": 26, "zh": "这个（　）上课的时候我们已经做过了，不用再做了。", "options": {"A": "上网", "B": "练习", "C": "完成", "D": "节日", "E": "声音", "F": "世界"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 27, "zh": "孩子们最喜欢这个（　），因为不用去上课，还能吃到好吃的。", "options": {"A": "上网", "B": "练习", "C": "完成", "D": "节日", "E": "声音", "F": "世界"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 28, "zh": "（　）可以发电子邮件，可以看节目，还可以买东西，真方便。", "options": {"A": "上网", "B": "练习", "C": "完成", "D": "节日", "E": "声音", "F": "世界"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 29, "zh": "A：六点半了，你还不回家？ B：今天的工作还没（　），我晚一点儿再回去。", "options": {"A": "上网", "B": "练习", "C": "完成", "D": "节日", "E": "声音", "F": "世界"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 30, "zh": "A：这是一张（　）地图，请大家找找中国在哪儿。 B：老师，我找到了。", "options": {"A": "上网", "B": "练习", "C": "完成", "D": "节日", "E": "声音", "F": "世界"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第31–35题：选择正确答案", "instruction_en": "Questions 31-35: Choose the right answers.", "items": [{"n": "例", "zh": "您是来参加今天会议的吗？您来早了一点儿，现在才八点半。您先进来坐吧。 ★会议最可能几点开始？", "options": {"A": "8点", "B": "8点半", "C": "9点"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [107]}}, {"n": 31, "zh": "以前的手机只能打电话，现在除了打电话以外，还能上网。世界上有什么新闻，马上就能知道。在没有电脑的地方，想给朋友发电子邮件，也能用手机，方便极了！ ★以前的手机可以做什么？", "options": {"A": "发电子邮件", "B": "上网", "C": "打电话"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 32, "zh": "我在中国留学了三年，除了提高了汉语水平以外，还了解了中国和世界文化。我们班除了老师，其他人都不是中国人，大家来自世界各地。上课和课间休息的时候，大家都用汉语聊天儿，介绍自己的文化，有意思极了。 ★在中国留学：", "options": {"A": "老师不是中国人", "B": "可以了解各地文化", "C": "不能提高汉语水平"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 33, "zh": "从下个月1号开始，这个地方要举行世界电影文化周，在文化周上，除了可以看到世界各地最新的电影，还有人为大家介绍各地的电影文化。一周七天，天天不同。对电影和电影文化感兴趣的朋友们，一定要去看看。 ★关于世界电影文化周，可以知道什么？", "options": {"A": "从1号到10号", "B": "有最新的电影", "C": "没有电影介绍"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 34, "zh": "春节是中国最重要的节日，这一节日在中国有很长的历史了。春节那天，大家都要在家里和家人一起做饭吃。近年来，除了在家吃饭以外，有些人也去饭馆吃饭，他们说这样更方便，还可以吃到在家不容易做的菜。 ★关于春节，可以知道什么？", "options": {"A": "一定要在家吃饭", "B": "是世界上最重要的节日", "C": "历史很长"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 35, "zh": "过去这儿有很多矮小的旧房子，但是这几年都不见了。现在，我们眼前除了高楼以外，还有干净的街道和漂亮的花园，这个地方的变化真是大极了。 ★这个地方现在：", "options": {"A": "有不少老房子", "B": "街道很干净", "C": "没有什么变化"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "三、书写 第一部分", "type_zh": "书写 第一部分", "instruction_zh": "第36–40题：连词成句", "instruction_en": "Questions 36-40: Rearrange the words/phrases to make sentences.", "items": [{"n": "例", "zh": "小船　上　一　河　条　有", "answer": "河上有一条小船。", "answer_ref": {"book": "workbook", "pages": [108]}}, {"n": 36, "zh": "笑笑　以外　除了　别人　都　来了", "answer": "除了笑笑以外，别人都来了。", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 37, "zh": "这个地方　极了　街道　干净　的", "answer": "这个地方的街道干净极了。", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 38, "zh": "历史　文化　除了　还　我　以外　喜欢", "answer": "除了历史以外，我还喜欢文化。", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 39, "zh": "什么　有　好看　电影院　电影　吗　的", "answer": "电影院有什么好看的电影吗？", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 40, "zh": "游泳　除了　我　爬山　愿意　也", "answer": "除了游泳我也愿意爬山。", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "三、书写 第二部分", "type_zh": "书写 第二部分", "instruction_zh": "第41–45题：看拼音，写汉字", "instruction_en": "Questions 41-45: Write the characters based on their pinyin.", "items": [{"n": "例", "zh": "没（　）系，别难过，高兴点儿。", "hint_zh": "guān", "answer": "关", "answer_ref": {"book": "workbook", "pages": [108]}}, {"n": 41, "zh": "马可，你的汉语水平（　）高了不少，老师真为你高兴！", "hint_zh": "tí", "answer": "提", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 42, "zh": "方朋，这个（　）子是什么意思？我没看明白。", "hint_zh": "jù", "answer": "句", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 43, "zh": "周经理，以后有什么问题，我可以给您（　）邮件吗？", "hint_zh": "fā", "answer": "发", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 44, "zh": "快把电视打开，新（　）开始了。", "hint_zh": "wén", "answer": "闻", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 45, "zh": "你看，（　）道两边都是树，一点儿也不觉得热。", "hint_zh": "jiē", "answer": "街", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "三、书写 第三部分", "type_zh": "书写 第三部分", "instruction_zh": "第46–50题：辨认汉字，选择正确的汉字填空", "instruction_en": "Questions 46-50: Distinguish the characters and fill in the blanks.", "items": [{"n": "例", "zh": "我不知道________个地方在________儿。", "hint_zh": "（那、哪）", "answer": "那、哪", "answer_ref": {"book": "workbook", "pages": [109]}}, {"n": 46, "zh": "你每天除了________习汉语以外，也要锻________身体。", "hint_zh": "（炼、练）", "answer": "练、炼", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 47, "zh": "大家都过来，我说一下这次篮________比赛的要________！", "hint_zh": "（求、球）", "answer": "球、求", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 48, "zh": "外边开始刮________了，别出去踢球了，在家上会儿________吧。", "hint_zh": "（网、风）", "answer": "风、网", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 49, "zh": "在这个重要的节________里，有很多歌舞节________。", "hint_zh": "（目、日）", "answer": "日、目", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 50, "zh": "弟弟除了喜欢中国文化以外，________对________界文化很感兴趣。", "hint_zh": "（也、世）", "answer": "也、世", "answer_ref": {"book": "teacher", "pages": [187]}}]}, {"n": "四、复习", "type_zh": "复习", "instruction_zh": "第1–2题：根据课文内容填空", "instruction_en": "Questions 1-2: Fill in the blanks based on the texts in the textbook.", "items": [{"n": 1, "zh": "大山来中国________两年了，他觉得自己的汉语________提高得一点儿也不快。昨天的作业，老师觉得他写得不错，________一个句子意思有些不清楚________，________都没什么问题。", "answer": "留学、水平、除了、外、其他", "answer_ref": {"book": "teacher", "pages": [187]}}, {"n": 2, "zh": "现在用电脑________真方便。除了看________，人们________可以听歌、看电影、买东西。小刚在网上买了一件衣服，有点儿小，给他弟弟了。不用________，还有新衣服穿，弟弟满意________。", "answer": "上网、新闻、还、花钱、极了", "answer_ref": {"book": "teacher", "pages": [187]}}]}], "answers_ref": {"book": "teacher", "pages": [185, 186, 187]}}, "hsk30": {"source": "courseware", "ref": {"book": "hsk30_courseware", "pages": [5, 18, 38]}, "new_words": [{"n": 1, "zh": "留学生", "pinyin": "liúxuéshēng", "pos": "n.", "en": "international student", "text": 1}, {"n": 2, "zh": "校园", "pinyin": "xiàoyuán", "pos": "n.", "en": "campus", "text": 1}, {"n": 3, "zh": "句", "pinyin": "jù", "pos": "m.", "en": "sentence", "text": 1}, {"n": 4, "zh": "选", "pinyin": "xuǎn", "pos": "v.", "en": "choose", "text": 1}, {"n": 5, "zh": "关注", "pinyin": "guānzhù", "pos": "v.", "en": "pay attention to", "text": 2}, {"n": 6, "zh": "过节", "pinyin": "guòjié", "pos": "v.", "en": "celebrate a festival", "text": 4}, {"n": 7, "zh": "新年", "pinyin": "xīnnián", "pos": "n.", "en": "New Year", "text": 4}, {"n": 8, "zh": "晚会", "pinyin": "wǎnhuì", "pos": "n.", "en": "evening party", "text": 4}], "grammar": [], "exercises": [], "unclear": []}, "audio": {"textbook": ["hsk3-textbook-1501.mp3", "hsk3-textbook-1502.mp3", "hsk3-textbook-1503.mp3", "hsk3-textbook-1504.mp3", "hsk3-textbook-1505.mp3"], "workbook": ["hsk3-workbook-15-part1.mp3", "hsk3-workbook-15-part2.mp3", "hsk3-workbook-15-part3.mp3", "hsk3-workbook-15-part4.mp3"]}, "unclear": ["Сурах бичиг PDF х.143 拼音课文 课文4-ийн сүүлийн өгүүлбэр «Lǎi zhèli de píjiǔ jié kànkan ba.» — ханз 来 (lái) байхад пиньиньд «Lǎi» (3-р өргөлт) хэвлэгдсэн; номд байгаагаар нь lines.pinyin-д «Lǎi» гэж үлдээсэн.", "Сурах бичиг PDF х.143 课文4: ханзан бичвэрт «……不同地方的歌舞。你想不想……» (цэг), 拼音课文-д «……de gēwǔ, nǐ xiǎng bu xiǎng……» (таслал) — lines-ийг ханзан бичвэрийн өгүүлбэрээр хувааж, пиньиньийг номд байгаагаар (4-р мөр таслалаар төгссөн, 5-р мөр жижиг үсгээр эхэлсэн) оноосон. Мөн 拼音课文-д «Chúle hē píjiǔ，» бүтэн өргөнтэй таслалтай хэвлэгдсэнийг хагас өргөнтэй «,» болгосон.", "课文4 номд гарчиггүй (зөвхөн «4» ба аудио 15-4) — title_zh хоосон, title_en байхгүй. Өгүүлэмжийг өгүүлбэр тус бүрээр lines-д хувааж, 拼音课文-ын харгалзах хэсгийг оноосон.", "Сурах бичгийн 拼音课文-ын гарчгийн пиньинь (Zài bàngōngshì / Zài jiàoshì / Zài Xiūxishì — 3-р гарчигт X том үсгээр хэвлэгдсэн) болон ярилцагчийн нэрийн пиньинь (Dàshān, lǎoshī, xuésheng, tóngshì, Xiǎogāng) схемд талбаргүй тул lines.pinyin-д зөвхөн яриаг оруулсан.", "Сурах бичиг PDF х.141 热身2: «英语» пиньинь «yīngyǔ» гэж жижиг үсгээр хэвлэгдсэн (汉语 нь «Hànyǔ») — номд байгаагаар. Хүснэгтийн □ нүдийг «□» тэмдгээр, мөрийг «ангилал | сонголт …» хэлбэрээр оруулсан.", "Сурах бичиг PDF х.145 注释2 练一练：(1) «A: ______。» цэгтэй, (2)(3) «A: ______» цэг таслалгүй хэвлэгдсэн — номд байгаагаар.", "Сурах бичгийн 练一练 (3 дүрэм × 3; 注释1-ийн 例如 хариулт хэвлэгдсэн тул зөвхөн түүнд answer бий), 练习2 选词填空， 练习3 描述图片， 练习4 回答问题， 热身2, 运用1–2 — хариулт сурах бичиг, багшийн номд хэвлэгдээгүй тул answer талбаргүй. Багшийн номын 课文 асуулт-хариулт (teacher.text_questions) нь 练习4-ийн асуултаас өөр.", "Багшийн ном PDF х.108 课文4 (1) «快速阅读，并回答：在啤酒节上可以做什么？» — тусдаа хариултгүй; (2)-ын 3-р асуулт («在啤酒节上可以做什么？») хариулттай давхцана. text_questions-д (1)-ийг a_zh-гүй оруулсан.", "Багшийн ном PDF х.105 语言点1 导入：«教师在黑板上画出……»-ийг зөвхөн текстээр (зураггүй) оруулсан.", "Багшийн номын 汉字辨认练习 (炼/练 · 求/球 · 网/风 · 目/日 · 世/也 — 组词；PDF х.108–109) хоосон зайтай, хариулт хэвлэгдээгүй. Дасгалын номын 46–50 ижил хосуудыг ашигладаг.", "Дасгалын ном PDF х.108 书写 40: хариулт (багшийн ном PDF х.187) «除了游泳我也愿意爬山。» — таслалгүй, «以外»-гүй (үгийн жагсаалтад 以外 байхгүй) — номд байгаагаар.", "Дасгалын номын сонсгол нэг CD тэмдэгтэй (15) — аудиог hsk3-workbook-15-part1…4.mp3 болгож хэсэг тус бүрт хуваасныг section.audio-д оноосон.", "Дасгалын ном 听力 第三/四部分 — номд зөвхөн сонголтууд хэвлэгдсэн; item.zh-д багшийн номын хавсралтын «问：» асуултыг оруулсан (transcript_zh-д бүтнээр). 第一部分 1–5-ын zh хоосон (номд зөвхөн дугаар), бичвэр transcript_zh-д.", "Дасгалын ном 听力 18: сонсголын бичвэрт «这条裙子», асуултад «这件衣服» гэж хэвлэгдсэн — номд байгаагаар.", "Дасгалын номд энэ хичээлд 51–54 (组词) хэсэг байхгүй — нийт 50 асуулт + 复习 2.", "Энэ хичээлд 汉字知识 хэсэг байхгүй (зөвхөн 旧字新词). * тэмдэгтэй үг: 举行 (17), 各 (20). 俗语 болон 文化-ын зургууд (同仁堂 самбартай хаалга; улаан хувцастай хүү гоймон идэж байна) схемд талбаргүй.", "HSK 3.0 нэмэлт үгс (BLCUP 课件 补充HSK3.0, слайд 5, 18, 38) `hsk30`-д."], "verified_pages": [103, 104, 105, 106, 107, 108, 109, 141, 142, 143, 144, 145, 146, 147, 148, 149, 150, 185, 186, 187], "schema_version": 1}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk3-l16', 'hsk3', 'HSK3', 16, '我现在累得下了班就想睡觉', 'Wǒ xiànzài lèi de xiàle bān jiù xiǎng shuì jiào', 'I am so tired that I want to do nothing but sleep after work', '{"level": "hsk3", "lesson": 16, "book": "HSK3", "title_zh": "我现在累得下了班就想睡觉", "title_pinyin": "Wǒ xiànzài lèi de xiàle bān jiù xiǎng shuì jiào", "title_en": "I am so tired that I want to do nothing but sleep after work", "textbook": {"ref": {"book": "textbook", "pages": [151, 152, 153, 154, 155, 156, 157, 158]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①皮鞋 píxié", "②城市 chéngshì", "③帽子 màozi", "④鼻子 bízi", "⑤刷牙 shuā yá", "⑥头发 tóufa"], "pictures_desc_en": ["A: a city skyline lit up at night with a road leading towards it", "B: a smiling woman touching her nose with one finger", "C: a pair of black leather shoes", "D: a woman with very long straight blond hair seen from the side", "E: a woman and a little girl brushing their teeth in front of a bathroom mirror", "F: a straw hat with a black band"]}, {"instruction_zh": "说说下列情况下，你想做什么或不想做什么", "instruction_en": "Talk about what you would or would not like to do under the following circumstances.", "items": ["累的时候 lèi de shíhou | 不想说话 bù xiǎng shuō huà", "高兴的时候 gāoxìng de shíhou |", "忙的时候 máng de shíhou |", "冷的时候 lěng de shíhou |", "牙疼的时候 yá téng de shíhou |", "热的时候 rè de shíhou |"]}], "texts": [{"n": 1, "title_zh": "在公司", "title_en": "In the company", "kind": "dialogue", "audio": "hsk3-textbook-1601.mp3", "lines": [{"speaker": "小丽", "zh": "我不喜欢一直住在同一个城市，想去其他城市看一看。", "pinyin": "Wǒ bù xǐhuan yìzhí zhù zài tóng yí ge chéngshì, xiǎng qù qítā chéngshì kàn yi kàn."}, {"speaker": "周明", "zh": "我年轻的时候也这么想，但是那时候没有钱，如果有钱，就去了。", "pinyin": "Wǒ niánqīng de shíhou yě zhème xiǎng, dànshì nà shíhou méiyǒu qián, rúguǒ yǒu qián, jiù qù le."}, {"speaker": "小丽", "zh": "那您现在为什么不去？", "pinyin": "Nà nín xiànzài wèi shénme bú qù?"}, {"speaker": "周明", "zh": "现在钱不是问题了，主要是没有时间。", "pinyin": "Xiànzài qián bú shì wèntí le, zhǔyào shì méiyǒu shíjiān."}, {"speaker": "小丽", "zh": "我认为现在您有时间也不会出去玩儿。", "pinyin": "Wǒ rènwéi xiànzài nín yǒu shíjiān yě bú huì chūqu wánr."}, {"speaker": "周明", "zh": "你说得对，我现在累得下了班就想睡觉。", "pinyin": "Nǐ shuō de duì, wǒ xiànzài lèi de xiàle bān jiù xiǎng shuì jiào."}], "new_words": [{"n": 1, "zh": "城市", "pinyin": "chéngshì", "pos": "n.", "en": "city", "text": 1}, {"n": 2, "zh": "如果", "pinyin": "rúguǒ", "pos": "conj.", "en": "if, in case", "text": 1}, {"n": 3, "zh": "认为", "pinyin": "rènwéi", "pos": "v.", "en": "to think, to believe", "text": 1}]}, {"n": 2, "title_zh": "在同事家", "title_en": "At a colleague’s home", "kind": "dialogue", "audio": "hsk3-textbook-1602.mp3", "lines": [{"speaker": "同事", "zh": "谢谢你们来看我女儿。你送的小皮鞋和小帽子真漂亮！", "pinyin": "Xièxiè nǐmen lái kàn wǒ nǚ’ér. Nǐ sòng de xiǎo píxié hé xiǎo màozi zhēn piàoliang!"}, {"speaker": "小丽", "zh": "别客气，你女儿长得白白的、胖胖的，真可爱！现在多高了？", "pinyin": "Bié kèqi, nǐ nǚ’ér zhǎng de báibái de, pàngpàng de, zhēn kě’ài! Xiànzài duō gāo le?"}, {"speaker": "同事", "zh": "快1米了，25公斤。", "pinyin": "Kuài yì mǐ le, èrshíwǔ gōngjīn."}, {"speaker": "小丽", "zh": "你看她鼻子小小的，头发黑黑的，长得像谁？", "pinyin": "Nǐ kàn tā bízi xiǎoxiǎo de, tóufa hēihēi de, zhǎng de xiàng shéi?"}, {"speaker": "同事", "zh": "像她爸爸，刚出生时她爸爸高兴得一个晚上都没睡着。", "pinyin": "Xiàng tā bàba, gāng chūshēng shí tā bàba gāoxìng de yí ge wǎnshang dōu méi shuì zháo."}], "new_words": [{"n": 4, "zh": "皮鞋", "pinyin": "píxié", "pos": "n.", "en": "leather shoes", "text": 2}, {"n": 5, "zh": "帽子", "pinyin": "màozi", "pos": "n.", "en": "hat, cap", "text": 2}, {"n": 6, "zh": "长", "pinyin": "zhǎng", "pos": "v.", "en": "to grow, to develop", "text": 2}, {"n": 7, "zh": "可爱", "pinyin": "kě’ài", "pos": "adj.", "en": "lovely, adorable", "text": 2}, {"n": 8, "zh": "米", "pinyin": "mǐ", "pos": "n.", "en": "metre", "text": 2}, {"n": 9, "zh": "公斤", "pinyin": "gōngjīn", "pos": "n.", "en": "kilogramme", "text": 2}, {"n": 10, "zh": "鼻子", "pinyin": "bízi", "pos": "n.", "en": "nose", "text": 2}, {"n": 11, "zh": "头发", "pinyin": "tóufa", "pos": "n.", "en": "hair", "text": 2}]}, {"n": 3, "title_zh": "在公司", "title_en": "In the company", "kind": "dialogue", "audio": "hsk3-textbook-1603.mp3", "lines": [{"speaker": "小刚", "zh": "我的牙还是很疼。", "pinyin": "Wǒ de yá háishi hěn téng."}, {"speaker": "同事", "zh": "如果不舒服，就去医院检查一下吧。", "pinyin": "Rúguǒ bù shūfu, jiù qù yīyuàn jiǎnchá yíxià ba."}, {"speaker": "小刚", "zh": "检查好几次了，但是没什么用。", "pinyin": "Jiǎnchá hǎo jǐ cì le, dànshì méi shénme yòng."}, {"speaker": "同事", "zh": "大夫怎么说的？", "pinyin": "Dàifu zěnme shuō de?"}, {"speaker": "小刚", "zh": "每次医生都告诉我，回家好好儿刷牙。", "pinyin": "Měi cì yīshēng dōu gàosu wǒ, huí jiā hǎohāor shuā yá."}], "new_words": [{"n": 12, "zh": "检查", "pinyin": "jiǎnchá", "pos": "v.", "en": "to check, to examine", "text": 3}, {"n": 13, "zh": "刷牙", "pinyin": "shuā yá", "pos": "v.", "en": "to brush the teeth", "text": 3}]}, {"n": 4, "kind": "narrative", "audio": "hsk3-textbook-1604.mp3", "lines": [{"zh": "很多人都觉得现在人和人的关系冷冷的，这可能是因为工作太忙，忙得没时间跟别人见面，累得不愿意和别人多说话。", "pinyin": "Hěn duō rén dōu juéde xiànzài rén hé rén de guānxì lěnglěng de, zhè kěnéng shì yīnwèi gōngzuò tài máng, máng de méi shíjiān gēn biérén jiàn miàn, lèi de bú yuànyì hé biérén duō shuō huà."}, {"zh": "其实，我们应该多对别人笑笑，说话时如果能多用一些“您好”“谢谢”这样的词语，和别人的关系就会变得更好。", "pinyin": "Qíshí, wǒmen yīnggāi duō duì biérén xiàoxiao, shuō huà shí rúguǒ néng duō yòng yìxiē “nín hǎo” “xièxie” zhèyàng de cíyǔ, hé biérén de guānxì jiù huì biàn de gèng hǎo."}], "new_words": [{"n": 14, "zh": "关系", "pinyin": "guānxì", "pos": "n.", "en": "relationship", "text": 4}, {"n": 15, "zh": "别人", "pinyin": "biérén", "pos": "n.", "en": "other people", "text": 4}, {"n": 16, "zh": "词语", "pinyin": "cíyǔ", "pos": "n.", "en": "word, expression", "text": 4, "star": true}]}], "grammar": [{"n": 1, "title_zh": "如果……（的话），（S）就……", "title_en": "The Structure “如果……（的话），（S）就……”", "explanation_zh": "“如果”后边的分句是一个假设，“就”后边的分句是在这种假设情况下产生的结果。注意，第二个分句的主语要放在“就”的前边。例如：", "explanation_en": "The clause following “如果” is a hypothesis, and the clause after “就” is the result based on the hypothesis. Note that the subject of the second clause should be put right before “就”. For example:", "structure_rows": ["如果……（的话），（S）就……"], "examples": [{"n": 1, "zh": "如果你太累了，就休息一会儿。"}, {"n": 2, "zh": "如果你喜欢，我就给你买。"}, {"n": 3, "zh": "如果有钱的话，我就去旅游。"}, {"n": 4, "zh": "如果不舒服，就去医院检查一下吧。"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "如果明天下雨的话，________。"}, {"n": 2, "zh": "如果考试考得很好的话，________。"}, {"n": 3, "zh": "________，我就跟朋友去踢足球。"}]}, {"n": 2, "title_zh": "复杂的状态补语", "title_en": "Complex Complements of State", "explanation_zh": "汉语中，可以用“得”构成状态补语，描写某种状态。“得”前一般是形容词或动词，“得”后一般是动词词组。例如：", "explanation_en": "In Chinese, “得” can be used to form a complement to describe a certain state. Usually “得” is preceded by an adjective or a verb and followed by a verb phrase. For example:", "examples": [{"n": 1, "zh": "孩子们玩儿得不想回家。"}, {"n": 2, "zh": "弟弟高兴得跳了起来。"}, {"n": 3, "zh": "儿子累得下了班就睡觉了。"}, {"n": 4, "zh": "人们忙得没时间跟别人见面。"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "我牙疼得________。"}, {"n": 2, "zh": "今天天气热得________。"}, {"n": 3, "zh": "看了这个电影，她笑得________。"}]}, {"n": 3, "title_zh": "单音节形容词重叠", "title_en": "Reduplication of Monosyllabic Adjectives", "explanation_zh": "汉语中，单音节形容词重叠表示程度深，形式为“AA的”，常用来描述人或事物的特征。例如：", "explanation_en": "In Chinese, a monosyllabic adjective is often reduplicated in the form of “AA的” to describe the characteristics of a person or thing, indicating a deep degree. For example:", "structure_rows": ["AA的"], "examples": [{"n": 1, "zh": "你送的花红红的，我很喜欢。"}, {"n": 2, "zh": "这些草绿绿的，真漂亮。"}, {"n": 3, "zh": "他鼻子小小的，长得像谁？"}, {"n": 4, "zh": "你女儿长得白白的、胖胖的，真可爱！"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "她的男朋友个子________。"}, {"n": 2, "zh": "他的女朋友头发________。"}, {"n": 3, "zh": "这个蛋糕________，真好吃。"}]}], "exercises": [{"n": 1, "type_zh": "朗读", "instruction_zh": "朗读下列短语和句子", "instruction_en": "Read the following phrases and sentences aloud.", "audio": "hsk3-textbook-1605.mp3", "items": [{"n": 1, "zh": "城市：一个城市／大城市／旅游城市／我想去其他城市看一看。"}, {"n": 2, "zh": "皮鞋：一双皮鞋／新皮鞋／买皮鞋／你送的小皮鞋和小帽子真漂亮！"}, {"n": 3, "zh": "长：长大了／长得胖胖的／长得很可爱／她长得像谁？"}, {"n": 4, "zh": "检查：检查作业／检查一下／好好儿检查／你去医院检查一下吧。"}, {"n": 5, "zh": "关系：师生关系／朋友关系／他和学生的关系很好／人和人的关系冷冷的。"}]}, {"n": 2, "type_zh": "选词填空", "instruction_zh": "选择恰当的词语填空", "instruction_en": "Choose the proper words to fill in the blanks.", "word_bank": [["关系", "可爱", "鼻子", "城市", "如果"], ["米", "检查", "公斤", "认为", "刷牙"]], "items": [{"n": 1, "zh": "________我的丈夫能少一些会议，他就会多跟我和孩子在一起了。"}, {"n": 2, "zh": "你觉得哪个________最好玩儿？"}, {"n": 3, "zh": "我和同屋的________不太好，怎么办？"}, {"n": 4, "zh": "我女朋友________高高的、头发长长的，非常好看。"}, {"n": 5, "zh": "那个小狗真________，我们把它带回家吧。"}, {"n": 6, "zh": "A：今天下午你去哪儿了？ B：我的车总是有问题，我去________了一下。"}, {"n": 7, "zh": "A：你想买点儿什么？ B：给我来一________苹果。"}, {"n": 8, "zh": "A：你有多高？ B：1________75。"}, {"n": 9, "zh": "A：你怎么刚吃饭？ B：今天起晚了，________以后就来上课了。"}, {"n": 10, "zh": "A：咱们去南方玩儿玩儿吧。 B：我________，还是北方更好玩儿一些。"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "A：这条裙子________，真好看。 B：是啊。但是太贵了，________，我就买。 A：生日的时候，我送给你吧。 B：真的吗？太好了。", "picture_desc_en": "A red sleeveless dress displayed on a mannequin."}, {"n": 2, "zh": "A：你怎么还不学习？ B：我现在累得________。 A：如果你考试考得好，我就________。 B：太好了，我现在就学习。", "picture_desc_en": "A boy asleep with his head on a desk, holding a red pen over an open notebook."}, {"n": 3, "zh": "A：________，就帮我做饭吧。 B：今天我忙得________，让我休息一下吧。 A：行，我自己去做饭。 B：好。", "picture_desc_en": "A man in a suit and glasses making a “time-out” T sign with his hands."}, {"n": 4, "zh": "A：你看，那个女孩个子________，头发________，眼睛________，真漂亮。 B：你如果喜欢她的话，________。 A：我现在已经有女朋友了。 B：我还没有女朋友呢，那我去吧。", "picture_desc_en": "A smiling young woman with long hair holding a pink folder, standing in a green park."}]}, {"n": 4, "type_zh": "回答问题", "instruction_zh": "根据课文回答问题", "instruction_en": "Answer the questions according to the texts.", "items": [{"n": 1, "zh": "周明年轻的时候为什么没去旅行？"}, {"n": 2, "zh": "现在周明为什么不能去旅行？"}, {"n": 3, "zh": "同事的女儿长得怎么样？"}, {"n": 4, "zh": "小刚为什么牙疼？"}, {"n": 5, "zh": "为什么现在人和人之间的关系冷冷的？"}, {"n": 6, "zh": "我们怎么做才能让关系变得更好？"}]}], "characters": {"knowledge_title_zh": "旧字新词", "knowledge_zh": "读读下面的词语，想想组成的新词是什么意思。", "knowledge_en": "Read the following words and guess the meanings of the newly-formed ones.", "word_game": [{"parts": ["词典", "汉语"], "result": "词语"}, {"parts": ["运动", "皮鞋"], "result": "运动鞋"}, {"parts": ["身体", "检查"], "result": "体检"}], "confusable_pairs": [["米", "来"], ["姐", "如"], ["斤", "近"], ["查", "香"], ["帽", "冒"]]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，互相调查对方的情况，完成调查表。", "instruction_en": "Work in pairs. Make a survey of your partner and fill in the questionnaire.", "example_zh": ["表格：| | 问 | 答 |", "| 1 | 如果有很多钱，你会做什么？ | 如果有钱，我就买一辆车。 |", "| 2 | 如果有时间，你做什么？ | |", "| 3 | 如果能去一个地方旅行，你去哪儿？ | |", "| 4 | 如果你是超人，你会做什么？ | |", "| 5 | 如果你是爸爸／妈妈，你不让孩子做什么？ | |", "| 6 | 如果你没钱了，你怎么办？ | |"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，一个人用“AA的”描述班里的一个人，其他人猜这个人是谁，猜对了的人接着描述。", "instruction_en": "Work in groups of 3-4. One describes a person in your class using “AA的”, and the other two or three guess who the person is. The one who has guessed right describes another person.", "example_zh": ["例如：他个子高高的，眼睛大大的……"]}], "saying": {"zh": "钱不是万能的", "pinyin": "Qián bú shì wànnéng de", "en": "Money is not omnipotent", "explanation_zh": "“钱不是万能的”，这句话的意思是钱虽然很重要，但是钱不能解决所有的问题。这句话告诉我们对待金钱要有正确的认识，虽然生活中处处需要钱，但是有钱也不一定能办成所有的事情。", "explanation_en": "“钱不是万能的” means though money is important, it is not the answer to all problems. It tells us to have a correct attitude towards money. We may need money everywhere in life, but being wealthy doesn’t mean everything is possible."}}, "teacher": {"ref": {"book": "teacher", "pages": [110, 111, 112, 113, 114, 115, 116]}, "objectives_zh": ["重点词语：学生能够熟练掌握：“长、检查、关系、别人”的词义和用法", "语言点：学生能够了解并掌握：（1）“如果……（的话），（主语）就……”表示假设和假设的结果（2）“得”构成的复杂状态补语（3）单音节形容词重叠表示人或事物的特征", "汉字：学生能够：根据已学生词猜测出3个旧字新词“词语、运动鞋、体检”的意思", "功能：学生能够：（1）用“如果……（的话），（主语）就……”表示假设的情况和结果（2）用“得”构成的状态补语描写某种状态（3）用单音节形容词的重叠式描述人或事物"], "steps": [{"title_zh": "复习旧课", "body_zh": "1 教师展示第15课的热身图片，请学生根据图片说出生词。\n2 教师根据第15课的内容进行提问。\n（1）昨天的课怎么样？你有问题吗？\n（2）说说你最想去的一个地方，为什么你最想去那儿？\n（3）为什么有些人非常喜欢小狗、小猫？你喜欢它们吗？\n（4）现在的年轻人用手机做什么事？你呢？\n（5）在你们国家，有哪些重要的节日？你最喜欢哪个节日？"}, {"title_zh": "学习新课 1 热身", "body_zh": "热身1：学生两人一组，合作完成热身1；教师出示热身1的图片，让学生根据图片说出词语，核对答案；最后全体学生齐读热身环节所有词语，要求语音标准，声调准确。\n答案：①C　②A　③F　④B　⑤E　⑥D\n热身2：可留至语言点（2）“复杂的状态补语”导入时使用。"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n城市、如果、认为、皮鞋、帽子、长、可爱、米、公斤、鼻子、头发、检查、刷牙、关系、别人、词语\n· 教师先带领学生快速认读一遍生词；\n· 取消拼音，带领学生再次认读；\n· 请单个学生独自认读2-3个生词；\n· 最后全班一起快速认读所有的生词。\n（2）生词讲解方式\n· 直观法（如图片、照片、实物等）展示：城市、皮鞋、帽子、可爱、米、公斤、鼻子、头发\n· 肢体展示：刷牙\n· 启发式引导：认为\n教师给出句子部分内容让学生进行补充，如：他每天下课以后都去运动，因为他认为运动对他的身体很好。\n（3）重点生词扩展及常用搭配\n长—长得很白—长得很高—她长得很像她妈妈。\n检查—检查作业—检查身体—我让医生给我检查一下牙齿。\n关系—有关系—没有关系—老师和学生的关系—他和每个人的关系都很好。\n别人—别人的事—请别人帮忙—这里没有别人。\n练习册相关练习：第106页／一／第一部分，第109页／二／第二部分"}, {"title_zh": "3 语言点（1）如果……（的话），（主语）就……", "body_zh": "① 语言点解析\n“如果”后边的分句是一个假设，“就”后边的分句是在这种假设情况下产生的结果。\n② 语言点导入\n教师给出情景，引导学生说出目标句。\n教师：星期天你们打算做什么？\n学生：我打算出去买衣服。\n教师：下雨你也去吗？\n学生：下雨我在家看电视。\n教师：星期天如果不下雨，她去买衣服，如果下雨，她在家看电视。\n③ 语言点操练\n教师给出词组，请学生说句子：\n很饿、吃一块蛋糕—如果你很饿，就吃一块蛋糕。\n写完作业、看会儿电视—如果你写完作业了，就看会儿电视。\n头疼、去医院—如果你头疼，就去医院看看。\n没听懂、再讲一遍—如果你没听懂，就让老师再讲一遍。\n你不去，我就不去—如果你不去，我就不去。\n④ 语言点扩展练习\n教师提问，请学生根据实际情况回答。\n如果你有很多钱，你做什么？\n如果给你一年的时间，你打算做什么？\n如果你现在能去旅游，你去哪儿？\n注意：第二个分句如果有主语，主语要放在“就”的前边。"}, {"title_zh": "3 语言点（2）复杂的状态补语", "body_zh": "① 语言点解析\n用“得”构成的状态补语，描写某种状态。“得”前一般是形容词或动词，“得”后一般是动词词组。\n［框］形容词＋得＋动词词组\n② 语言点导入\n教师可利用本课热身2的表格导入语言点。\n教师带领学生认读表格中的词语。\n教师示范：\n教师：累的时候，你会怎么样？\n学生：不想说话。\n教师：他累得不想说话。\n③ 语言点操练\n教师可根据热身2的表格操练语言点。\n学生向教师提问，教师回答后，请学生说出目标句。\n目标句：我高兴得给太太做了一桌子的菜。\n　　　　我忙得没有时间吃饭。\n　　　　我冷得穿上了妈妈的衣服。\n　　　　我牙疼得一直哭。\n　　　　我热得喝了三瓶冰箱里刚拿出来的水。\n④ 语言点扩展练习\n教师利用热身2，让学生互相询问并回答。\n注意：复杂状态补语中，“得”后边的成分是复杂的形式，而不是简单形式。“笑得很开心”是一个简单状态补语。"}, {"title_zh": "3 语言点（3）单音节形容词重叠", "body_zh": "① 语言点解析\n单音节形容词重叠，变为“AA的”形式，表示程度深，常用来描述人或事物的特征。\n［框］AA的\n② 语言点导入\n就地取材，教师利用教室中的情景，引导学生说出目标句：\n教师：你们觉得他高不高？\n学生：他很高。\n教师：他长得高高的。\n③ 语言点操练\n教师给出词组，请学生说句子：\n裙子、长—这条裙子长长的。\n鼻子、高—她的鼻子高高的。\n这个小孩子、胖—这个小孩子长得胖胖的。\n她的牙、白—她的牙白白的。\n头发、长—她的头发长长的。\n④ 语言点扩展练习\n教师让学生用单音节形容词重叠形式来描述一个人。\n注意：单音节形容词重叠后，要加上一个“的”字，才能进入句子。"}, {"title_zh": "4 课文 课文1", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n女的（小丽）喜欢做什么？——她喜欢去其他城市看一看。\n男的（周明）年轻的时候为什么没去其他城市？——他那时候没有钱。\n周明觉得他现在为什么不能去？——他没有时间。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：我不喜欢……，想去……。\nB：我年轻的时候……，但是……，如果……，就……。\nA：那你……？\nB：现在……，主要是……。\nA：我认为……。\nB：你说得对，……。"}, {"title_zh": "4 课文 课文2", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n同事的女儿长得怎么样？——她长得白白的、胖胖的，很可爱。\n她现在多高了？——快一米了。\n她长得像谁？——她长得像她爸爸。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：谢谢你们来……，你送的……！\nB：别客气，……长得……，真……！现在……？\nA：……。\nB：你看她／他……，……，长得像谁？\nA：像……，刚出生时……。"}, {"title_zh": "4 课文 课文3", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n男的的牙怎么了？——他的牙很疼。\n女的建议他做什么？——去医院检查一下。\n大夫觉得是什么问题？——他不好好刷牙。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）教师给提示词，带领学生复述课文。\n提示词：牙、疼、检查、没什么用、大夫、刷牙"}, {"title_zh": "4 课文 课文4", "body_zh": "（1）快速阅读，并回答：怎么才能和别人的关系变得更好？\n（2）教师领读课文两遍，并回答下列问题：\n很多人觉得现在人和人的关系怎么样？——关系冷冷的。\n为什么会这样？——因为工作太忙，忙得没时间跟别人见面，累得不愿意和别人多说话。\n（3）教师给提示词，带领学生复述课文。\n提示词：关系、冷、工作、见面、说话、笑、词语、更好\n（4）教师请学生仿照课文，介绍一个让自己和别人的关系变得更好的方法。\n练习册相关练习：第112页／四"}, {"title_zh": "5 汉字", "body_zh": "旧字新词：\n① 教师领读以前学过的词语和新词，并让学生猜猜新词的意思。\n· 领读：词典、汉语、词语\n问学生：“词语”是什么意思？——词典中的词。\n· 领读：运动、皮鞋、运动鞋\n问学生：“运动鞋”是什么意思？——运动的时候穿的鞋。\n· 领读：身体、检查、体检\n问学生：“体检”是什么意思？——给身体做一个检查。\n注意“体检”是一个名词。\n② 教师领读新词扩展，通过情景，理解新词的意思和用法：\n词语：学习词语／汉语词语／这些词语都很有用。\n运动鞋：一双运动鞋／穿运动鞋／今天下午我要去买一双运动鞋。\n体检：做体检／一次体检／我要去医院做一次体检。\n汉字辨认练习：\n辨认下列汉字并组词。\n米：________、________　来：________、________\n姐：________、________　如：________、________\n斤：________、________　近：________、________\n查：________、________　香：________、________\n帽：________、________　冒：________、________\n练习册相关练习：第112页／三／第三部分"}, {"title_zh": "6 补充课堂活动——吹牛游戏", "body_zh": "教师出示词语卡片，学生依次说出包含复杂程度补语的句子，比比谁是最……的人。例如：教师提问“谁是最忙的人”，学生可以说“我是最忙的人，因为我忙得没有时间吃饭”等句子。\n参考词语：累、忙、饿、高兴……"}, {"title_zh": "7 俗语", "body_zh": "教师引导学生理解俗语的含义，注意本课的“万能”是“能做所有的事”的意思，这句话是说钱不能做所有的事。例如，要想有一个好身体，一定要注意锻炼，当你的健康真的出现问题，有再多钱也换不回来，因为钱不是万能的。"}, {"title_zh": "8 本课小结", "body_zh": "· 语言点：“如果……（的话），（主语）就……”描述假设的情况及结果\n　　　　　用复杂状态补语描述某种状态\n　　　　　用单音节形容词重叠式描述某种状态\n· 汉　字：旧字新词：词语、运动鞋、体检"}], "notes_zh": ["注意：第二个分句如果有主语，主语要放在“就”的前边。（语言点1）", "注意：复杂状态补语中，“得”后边的成分是复杂的形式，而不是简单形式。“笑得很开心”是一个简单状态补语。（语言点2）", "注意：单音节形容词重叠后，要加上一个“的”字，才能进入句子。（语言点3）", "注意“体检”是一个名词。（汉字）", "注意本课的“万能”是“能做所有的事”的意思，这句话是说钱不能做所有的事。（俗语）"], "warmup_answers_zh": ["热身1 答案：①C　②A　③F　④B　⑤E　⑥D", "热身2：可留至语言点（2）“复杂的状态补语”导入时使用。"], "text_questions": [{"text": 1, "q_zh": "女的（小丽）喜欢做什么？", "a_zh": "她喜欢去其他城市看一看。"}, {"text": 1, "q_zh": "男的（周明）年轻的时候为什么没去其他城市？", "a_zh": "他那时候没有钱。"}, {"text": 1, "q_zh": "周明觉得他现在为什么不能去？", "a_zh": "他没有时间。"}, {"text": 2, "q_zh": "同事的女儿长得怎么样？", "a_zh": "她长得白白的、胖胖的，很可爱。"}, {"text": 2, "q_zh": "她现在多高了？", "a_zh": "快一米了。"}, {"text": 2, "q_zh": "她长得像谁？", "a_zh": "她长得像她爸爸。"}, {"text": 3, "q_zh": "男的的牙怎么了？", "a_zh": "他的牙很疼。"}, {"text": 3, "q_zh": "女的建议他做什么？", "a_zh": "去医院检查一下。"}, {"text": 3, "q_zh": "大夫觉得是什么问题？", "a_zh": "他不好好刷牙。"}, {"text": 4, "q_zh": "（快速阅读，并回答：）怎么才能和别人的关系变得更好？"}, {"text": 4, "q_zh": "很多人觉得现在人和人的关系怎么样？", "a_zh": "关系冷冷的。"}, {"text": 4, "q_zh": "为什么会这样？", "a_zh": "因为工作太忙，忙得没时间跟别人见面，累得不愿意和别人多说话。"}], "summary_zh": "语言点：“如果……（的话），（主语）就……”描述假设的情况及结果；用复杂状态补语描述某种状态；用单音节形容词重叠式描述某种状态。汉字：旧字新词：词语、运动鞋、体检。"}, "workbook": {"ref": {"book": "workbook", "pages": [110, 111, 112, 113, 114, 115, 116]}, "answers_ref": {"book": "teacher", "pages": [188, 189, 190]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 1-5: Choose the right picture for each dialogue you hear.", "audio": "hsk3-workbook-16-part1.mp3", "items": [{"n": "例", "zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "transcript_zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "options": {"A": "[picture] a small puppy standing next to a pair of small shoes", "B": "[picture] a woman at the dentist with her mouth open while a dentist examines her teeth with instruments", "C": "[picture] two smiling girls with long hair, heads close together", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young man holding his head in his hand, sitting at a desk across from a female doctor with a stethoscope", "F": "[picture] a man and a woman sitting beside a tent outdoors, the woman pointing into the distance"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [110]}}, {"n": 1, "zh": "", "options": {"A": "[picture] a small puppy standing next to a pair of small shoes", "B": "[picture] a woman at the dentist with her mouth open while a dentist examines her teeth with instruments", "C": "[picture] two smiling girls with long hair, heads close together", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young man holding his head in his hand, sitting at a desk across from a female doctor with a stethoscope", "F": "[picture] a man and a woman sitting beside a tent outdoors, the woman pointing into the distance"}, "transcript_zh": "女：你好，你有什么问题？哪儿不舒服？ 男：医生，我最近一直头疼，疼得晚上睡不着觉。有什么药吗？", "answer": "E", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 2, "zh": "", "options": {"A": "[picture] a small puppy standing next to a pair of small shoes", "B": "[picture] a woman at the dentist with her mouth open while a dentist examines her teeth with instruments", "C": "[picture] two smiling girls with long hair, heads close together", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young man holding his head in his hand, sitting at a desk across from a female doctor with a stethoscope", "F": "[picture] a man and a woman sitting beside a tent outdoors, the woman pointing into the distance"}, "transcript_zh": "女：常医生，我的牙不疼了，应该没什么问题了吧？ 男：只听你说不行，我需要检查一下才清楚。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 3, "zh": "", "options": {"A": "[picture] a small puppy standing next to a pair of small shoes", "B": "[picture] a woman at the dentist with her mouth open while a dentist examines her teeth with instruments", "C": "[picture] two smiling girls with long hair, heads close together", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young man holding his head in his hand, sitting at a desk across from a female doctor with a stethoscope", "F": "[picture] a man and a woman sitting beside a tent outdoors, the woman pointing into the distance"}, "transcript_zh": "女：你看！那边真漂亮！有山有水，有树有花，还有几个小房子，美得像画一样。 男：那还等什么？快过去看看吧。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 4, "zh": "", "options": {"A": "[picture] a small puppy standing next to a pair of small shoes", "B": "[picture] a woman at the dentist with her mouth open while a dentist examines her teeth with instruments", "C": "[picture] two smiling girls with long hair, heads close together", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young man holding his head in his hand, sitting at a desk across from a female doctor with a stethoscope", "F": "[picture] a man and a woman sitting beside a tent outdoors, the woman pointing into the distance"}, "transcript_zh": "男：你的两个女儿长得真像！这个头发长长的是姐姐吧？ 女：这是我二女儿，她喜欢长头发。大女儿不喜欢。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 5, "zh": "", "options": {"A": "[picture] a small puppy standing next to a pair of small shoes", "B": "[picture] a woman at the dentist with her mouth open while a dentist examines her teeth with instruments", "C": "[picture] two smiling girls with long hair, heads close together", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a young man holding his head in his hand, sitting at a desk across from a female doctor with a stethoscope", "F": "[picture] a man and a woman sitting beside a tent outdoors, the woman pointing into the distance"}, "transcript_zh": "男：你家小狗小小的，长得真可爱！ 女：还很聪明呢。它跟我女儿的关系特别好，每天都帮她把小皮鞋放好。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听句子，判断对错", "instruction_en": "Questions 6-10: Decide whether the statements are true or false based on the sentences you hear.", "audio": "hsk3-workbook-16-part2.mp3", "items": [{"n": "例1", "zh": "他希望自己很健康。", "transcript_zh": "为了让自己更健康，他每天都花一个小时去锻炼身体。", "answer": "√", "answer_ref": {"book": "workbook", "pages": [111]}}, {"n": "例2", "zh": "那块儿手表不是他的。", "transcript_zh": "今天我想早点儿回家。看了看手表，才5点。过了一会儿再看表，还是5点，我这才发现我的手表不走了。", "answer": "×", "answer_ref": {"book": "workbook", "pages": [111]}}, {"n": 6, "zh": "他不知道常月现在变胖了还是变瘦了。", "transcript_zh": "常月是我上大学时的好朋友。那时候她很瘦，瘦得只有40公斤。听说她现在已经是三个孩子的妈妈了，不知道长胖一点儿没有。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 7, "zh": "小丽没听明白自己的工作是什么。", "transcript_zh": "今天的会议就到这儿吧，大家对自己的工作都清楚了吗？如果有什么不明白的地方，就去秘书办公室问小丽。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 8, "zh": "女儿喜欢新衣服和新鞋。", "transcript_zh": "我女儿每天都说“从明天开始我每天跑五千米”，我和妻子很早就给她买好了运动服、运动鞋。直到今天，鞋和衣服还都是新的。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 9, "zh": "儿子没让我买东西给他。", "transcript_zh": "赛前，我跟儿子说：“如果你拿了第一，你要什么我就给你买什么。”没想到儿子真的拿了第一，更没想到他的要求是让我在家休息一天。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 10, "zh": "每个星期五老师都送给每个学生一件礼物。", "transcript_zh": "每个星期五，我们班中文老师都带着同学们复习。如果有人能把这个星期学的词语都写对，老师就送给他一件礼物。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听短对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the short dialogues and choose the right answers.", "audio": "hsk3-workbook-16-part3.mp3", "items": [{"n": "例", "zh": "男的想让小王做什么？", "transcript_zh": "男：小王，帮我开一下门，好吗？谢谢！ 女：没问题。您去超市了？买了这么多东西。 问：男的想让小王做什么？", "options": {"A": "开门", "B": "拿东西", "C": "去超市买东西"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [111]}}, {"n": 11, "zh": "关于女的，可以知道什么？", "options": {"A": "眼睛红", "B": "打算去医院", "C": "买了一个红眼镜"}, "transcript_zh": "男：最近你的眼睛一直红红的，我带你去医院检查一下吧。 女：我去过了，医生说没什么事，不用吃药，让我多休息。 问：关于女的，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 12, "zh": "女的是什么意思？", "options": {"A": "明天天气好", "B": "太阳能从西边出来", "C": "认为男的不可能去跑步"}, "transcript_zh": "男：我打算从明天开始，每天去运动场跑两千米。 女：真的吗？如果你能这么做，太阳就能从西边出来。 问：女的是什么意思？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 13, "zh": "女的是男的的什么人？", "options": {"A": "女儿", "B": "妈妈", "C": "奶奶"}, "transcript_zh": "女：乐乐，快让奶奶看看，你长高了，也长胖了。这双小皮鞋真好看，谁给你买的？ 男：是妈妈，她说如果我这次考试还拿第一，就再给我买一双。 问：女的是男的的什么人？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 14, "zh": "关于男的，可以知道什么？", "options": {"A": "中午吃过药了", "B": "现在要去医院", "C": "现在能吃甜的"}, "transcript_zh": "男：我觉得中午吃的药没什么用，牙还是很疼，不能吃甜的。 女：等一晚上，如果明天还不好，就带你去医院检查一下，看看医生怎么说。 问：关于男的，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 15, "zh": "男的打算给女儿起什么名字？", "options": {"A": "老高", "B": "高山", "C": "高静"}, "transcript_zh": "女：老高，你说我们给孩子起什么名字好？ 男：如果是男孩儿，就叫高山，如果是女孩儿，就叫高静，怎么样？ 问：男的打算给女儿起什么名字？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "一、听力 第四部分", "type_zh": "听力 第四部分", "instruction_zh": "第16–20题：听长对话，选择正确答案", "instruction_en": "Questions 16-20: Listen to the dialogues and choose the right answers.", "audio": "hsk3-workbook-16-part4.mp3", "items": [{"n": "例", "zh": "男的在做什么？", "transcript_zh": "女：晚饭做好了，准备吃饭了。 男：等一会儿，比赛还有三分钟就结束了。 女：快点儿吧，一起吃，菜冷了就不好吃了。 男：你先吃，我马上就看完了。 问：男的在做什么？", "options": {"A": "洗澡", "B": "吃饭", "C": "看电视"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [112]}}, {"n": 16, "zh": "男的为什么回来晚了？", "options": {"A": "一直工作", "B": "坐错车了", "C": "坐过站了"}, "transcript_zh": "女：你今天回来得有点儿晚啊。 男：今天不知道怎么了，特别累，回家的时候累得我在公共汽车上就睡着了。 女：我有时候也在车上睡一会儿。 男：但是我坐过站了，只好下了车再往回坐。 问：男的为什么回来晚了？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 17, "zh": "关于女的，可以知道什么？", "options": {"A": "不认识男的", "B": "变瘦了", "C": "没想到男的这么瘦"}, "transcript_zh": "男：周新，好久不见！你还是那么年轻、漂亮。 女：对不起，请问您是？ 男：我是常亮啊，你不认识我了？ 女：常亮？你现在怎么变得这么瘦？瘦得我都不认识你了。 问：关于女的，可以知道什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 18, "zh": "关于小白的孩子，可以知道什么？", "options": {"A": "不太胖", "B": "大眼睛", "C": "小鼻子"}, "transcript_zh": "男：听说上个月小白生了个儿子？ 女：是啊，那孩子特别可爱，出生时特别胖，四公斤呢，他们高兴得一晚上没睡。 男：孩子长得像谁？像小白还是像她丈夫？ 女：鼻子像爸爸，高高的，眼睛像妈妈，大大的，头发也像妈妈，黑黑的。 问：关于小白的孩子，可以知道什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 19, "zh": "女的喝什么比较好？", "options": {"A": "热牛奶", "B": "冰可乐", "C": "热水"}, "transcript_zh": "女：我睡不着，怎么办啊？ 男：喝杯热牛奶，能帮助你快点儿睡，也能睡得好。 女：热牛奶？我是热得睡不着，喝热的更睡不着了。 男：如果觉得太热，就喝杯冰可乐吧，甜甜的，很舒服。 问：女的喝什么比较好？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 20, "zh": "关于这个城市，可以知道什么？", "options": {"A": "有地铁", "B": "人很好", "C": "不太安静"}, "transcript_zh": "男：这个城市真不错，干净、安静、漂亮。 女：超市、洗衣店、饭馆、咖啡店，都有，很方便。 男：人和人的关系也不错，遇到问题时，别人都愿意帮助你。 女：如果这个地方有地铁，那就更好了。 问：关于这个城市，可以知道什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第21–25题：选择合适的问答", "instruction_en": "Questions 21-25: Match the two parts of the same dialogue.", "items": [{"n": "例", "zh": "你知道怎么去那儿吗？", "options": {"A": "你的鼻子红红的？怎么了？", "B": "我的牙有点儿疼，您帮我看看吧。", "C": "不到200米了，我们要不要先休息一下？", "D": "我们给小方的孩子买皮鞋还是买帽子？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "他是我们学校的校长，姓周。"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [113]}}, {"n": 21, "zh": "还有多远？我累得一步也不想走了。", "options": {"A": "你的鼻子红红的？怎么了？", "B": "我的牙有点儿疼，您帮我看看吧。", "C": "不到200米了，我们要不要先休息一下？", "D": "我们给小方的孩子买皮鞋还是买帽子？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "他是我们学校的校长，姓周。"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 22, "zh": "她儿子只有两个月大，不用穿皮鞋，买个小帽子吧。", "options": {"A": "你的鼻子红红的？怎么了？", "B": "我的牙有点儿疼，您帮我看看吧。", "C": "不到200米了，我们要不要先休息一下？", "D": "我们给小方的孩子买皮鞋还是买帽子？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "他是我们学校的校长，姓周。"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 23, "zh": "好，你坐这边吧，我给你检查一下。", "options": {"A": "你的鼻子红红的？怎么了？", "B": "我的牙有点儿疼，您帮我看看吧。", "C": "不到200米了，我们要不要先休息一下？", "D": "我们给小方的孩子买皮鞋还是买帽子？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "他是我们学校的校长，姓周。"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 24, "zh": "前边那个高高的、瘦瘦的老人是谁？", "options": {"A": "你的鼻子红红的？怎么了？", "B": "我的牙有点儿疼，您帮我看看吧。", "C": "不到200米了，我们要不要先休息一下？", "D": "我们给小方的孩子买皮鞋还是买帽子？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "他是我们学校的校长，姓周。"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 25, "zh": "没事，可能是外边太冷了，还刮大风。", "options": {"A": "你的鼻子红红的？怎么了？", "B": "我的牙有点儿疼，您帮我看看吧。", "C": "不到200米了，我们要不要先休息一下？", "D": "我们给小方的孩子买皮鞋还是买帽子？", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "他是我们学校的校长，姓周。"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第26–30题：选择合适的词语填空", "instruction_en": "Questions 26-30: Choose the proper words to fill in the brackets.", "word_bank": [["A 城市", "B 头发", "C 鼻子", "D 认为", "E 声音", "F 关系"]], "items": [{"n": "例", "zh": "她说话的（　）多好听啊！", "options": {"A": "城市", "B": "头发", "C": "鼻子", "D": "认为", "E": "声音", "F": "关系"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [113]}}, {"n": 26, "zh": "我感冒了，（　）不舒服。", "options": {"A": "城市", "B": "头发", "C": "鼻子", "D": "认为", "E": "声音", "F": "关系"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 27, "zh": "我（　）现在上网看新闻比以前方便多了。", "options": {"A": "城市", "B": "头发", "C": "鼻子", "D": "认为", "E": "声音", "F": "关系"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 28, "zh": "今天洗澡的时候我发现我的（　）长了不少。", "options": {"A": "城市", "B": "头发", "C": "鼻子", "D": "认为", "E": "声音", "F": "关系"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 29, "zh": "A：我看你和新来的小丽每天下班都一起走。 B：是，我们以前就是同学，（　）一直很好。", "options": {"A": "城市", "B": "头发", "C": "鼻子", "D": "认为", "E": "声音", "F": "关系"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 30, "zh": "A：最近工作太累了，我真想好好儿休息一下。 B：那你去别的（　）玩儿玩儿吧。", "options": {"A": "城市", "B": "头发", "C": "鼻子", "D": "认为", "E": "声音", "F": "关系"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第31–35题：选择正确答案", "instruction_en": "Questions 31-35: Choose the right answers.", "items": [{"n": "例", "zh": "您是来参加今天会议的吗？您来早了一点儿，现在才八点半。您先进来坐吧。 ★会议最可能几点开始？", "options": {"A": "8点", "B": "8点半", "C": "9点"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [114]}}, {"n": 31, "zh": "您有体检的习惯吗？很多人都认为体检没那么重要，觉得自己身体很健康。其实，我们应该每年做一次体检，这样可以让自己放心，也让家人放心。如果有什么病，也可以早点儿知道早点儿看。 ★关于体检，可以知道什么？", "options": {"A": "不太重要", "B": "应该每年一次", "C": "没病的人不用体检"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 32, "zh": "我是新兴饭店的经理，我和我的服务员很高兴为您服务。如果您对我们的服务很满意，就请您告诉您的朋友；如果您对我们的服务不满意，就请您告诉我们。新兴饭店祝您生活、工作事事开心。 ★如果认为这家饭店的饭菜不错，我们可以：", "options": {"A": "告诉大家", "B": "告诉饭店", "C": "来这儿工作"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 33, "zh": "我爸妈都是北方人，但是我从小跟爷爷奶奶在南方长大，一直没见过雪。去年搬回北京后，虽然这儿的冬天很冷，我还不太习惯，但是我终于第一次见到了雪，雪花白白的，特别漂亮，我高兴得在雪地里玩儿了一天，如果每天都能看到雪，那就太好了。 ★我：", "options": {"A": "没见过雪", "B": "每天都能看到雪", "C": "喜欢雪"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 34, "zh": "我们每天都刷牙，但你知道怎么刷牙吗？你的牙健康吗？牙医告诉我们，刷牙应该每天刷三次，每次最少要刷三分钟，这样才能把牙刷干净。还有，每年应该最少检查一次牙，如果牙不舒服，就要马上去医院。 ★根据这段话，可以知道什么？", "options": {"A": "刷牙的时间越长越好", "B": "每天刷两次牙就可以", "C": "每年都要去医院检查牙"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 35, "zh": "去年，我丈夫自己开了个公司，每天忙得都没有时间吃饭，好几次都累得一句话也不想说，到了家就睡觉，我真担心他累坏了。今天晚上丈夫回来后，我打算告诉他：下个月不工作，一起出去旅游，到一个安静的城市去好好儿休息一下。 ★我丈夫：", "options": {"A": "工作特别忙", "B": "不喜欢说话", "C": "下个月搬家"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "三、书写 第一部分", "type_zh": "书写 第一部分", "instruction_zh": "第36–40题：连词成句", "instruction_en": "Questions 36-40: Rearrange the words/phrases to make sentences.", "items": [{"n": "例", "zh": "小船　上　一　河　条　有", "answer": "河上有一条小船。", "answer_ref": {"book": "workbook", "pages": [115]}}, {"n": 36, "zh": "跳　起来　高兴　弟弟　得　了", "answer": "弟弟高兴得跳起来了。", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 37, "zh": "大　大　小狗　的　的　眼睛", "answer": "小狗的眼睛大大的。", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 38, "zh": "玩儿　天气　就　我们　明天　公园　去　好", "answer": "明天天气好我们就去公园玩儿。", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 39, "zh": "走路　不能　疼　腿　得　我的", "answer": "我的腿疼得不能走路。", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 40, "zh": "甜　的　甜　水果店　的　西瓜", "answer": "水果店的西瓜甜甜的。", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "三、书写 第二部分", "type_zh": "书写 第二部分", "instruction_zh": "第41–45题：看拼音，写汉字", "instruction_en": "Questions 41-45: Write the characters based on their pinyin.", "items": [{"n": "例", "zh": "没（　）系，别难过，高兴点儿。", "hint_zh": "guān", "answer": "关", "answer_ref": {"book": "workbook", "pages": [115]}}, {"n": 41, "zh": "这个（　）市的街道非常干净，路边有很多树。", "hint_zh": "chéng", "answer": "城", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 42, "zh": "妻子知道我明天参加面试，为我买了一双新（　）鞋。", "hint_zh": "pí", "answer": "皮", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 43, "zh": "弟弟的眼睛大大的，（　）子高高的，可爱极了。", "hint_zh": "bí", "answer": "鼻", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 44, "zh": "爷爷已经80岁了，每年都要去做一次健康（　）查。", "hint_zh": "jiǎn", "answer": "检", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 45, "zh": "你吃了那么多甜东西，快去把（　）刷干净。", "hint_zh": "yá", "answer": "牙", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "三、书写 第三部分", "type_zh": "书写 第三部分", "instruction_zh": "第46–50题：辨认汉字，选择正确的汉字填空", "instruction_en": "Questions 46-50: Distinguish the characters and fill in the blanks.", "items": [{"n": "例", "zh": "我不知道________个地方在________儿。", "hint_zh": "（那、哪）", "answer": "那、哪", "answer_ref": {"book": "workbook", "pages": [116]}}, {"n": 46, "zh": "小丽每天早上都要先去公园跑两千________，再________公司上班。", "hint_zh": "（米、来）", "answer": "米、来", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 47, "zh": "周秘书，________果白小________回来了，请你让她给我打个电话。", "hint_zh": "（姐、如）", "answer": "如、姐", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 48, "zh": "这儿附________有个超市，我们进去买几________水果吧。", "hint_zh": "（斤、近）", "answer": "近、斤", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 49, "zh": "医生检________完我的牙后，让我少吃些________蕉、蛋糕这样甜的东西。", "hint_zh": "（查、香）", "answer": "查、香", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 50, "zh": "天气越来越冷，我怕你感________，所以给你买了个________子。", "hint_zh": "（帽、冒）", "answer": "冒、帽", "answer_ref": {"book": "teacher", "pages": [190]}}]}, {"n": "四、复习", "type_zh": "复习", "instruction_zh": "第1–2题：根据课文内容填空", "instruction_en": "Questions 1-2: Fill in the blanks based on the texts in the textbook.", "items": [{"n": 1, "zh": "小丽认为一个人不能总住在同一个________，应该去其他地方看看。周经理年轻时也这么想，________那时候没有钱，他________去旅游了。现在钱不是问题了，但是他忙得________，________下了班就想睡觉。", "answer": "城市、如果、就、没时间、累得", "answer_ref": {"book": "teacher", "pages": [190]}}, {"n": 2, "zh": "小丽同事的女儿胖胖的，________，很可爱，现在已经25________，快1米了。她鼻子小小的，________黑黑的，长得像爸爸。刚出生时同事的丈夫________一个晚上都没睡着。小丽给她的女儿买了两件礼物：小________和小帽子，都很漂亮。", "answer": "白白的、公斤、头发、高兴得、皮鞋", "answer_ref": {"book": "teacher", "pages": [190]}}]}]}, "audio": {"textbook": ["hsk3-textbook-1601.mp3", "hsk3-textbook-1602.mp3", "hsk3-textbook-1603.mp3", "hsk3-textbook-1604.mp3", "hsk3-textbook-1605.mp3"], "workbook": ["hsk3-workbook-16-part1.mp3", "hsk3-workbook-16-part2.mp3", "hsk3-workbook-16-part3.mp3", "hsk3-workbook-16-part4.mp3"]}, "unclear": ["Дасгалын ном PDF х.116 四、复习 1: «周经理年轻时也这么想，________那时候没有钱，他________去旅游了» гэж «没有钱» хэвлэгдсэн; багшийн номын хариулт (PDF х.190) «城市、如果、就、没时间、累得» — «如果那时候没有钱，他就去旅游了» болж утга зөрнө (课文1: «但是那时候没有钱，如果有钱，就去了»). Номд байгаагаар нь үлдээсэн.", "Дасгалын ном 四、复习 1 «周经理» гэж нэрлэсэн — сурах бичгийн 课文1-д ярилцагч «周明» (албан тушаал дурдаагүй); номд байгаагаар.", "Сурах бичиг PDF х.153 拼音课文2: «Xièxiè nǐmen…» (хоёр үе хоёулаа 4-р хөг) — 课文4-т «xièxie» (хоёр дахь үе саармаг); номд байгаагаар.", "Сурах бичиг PDF х.155 注释3 жишээ (3) «他鼻子小小的，长得像谁？» — 课文2-т «你看她鼻子小小的…» (她); жишээ (3) улаанаар тэмдэглэгдээгүй (课文-аас авсан биш) тул номд байгаагаар үлдээсэн.", "Багшийн ном PDF х.116 补充课堂活动 «包含复杂程度补语的句子» гэж бичсэн — 语言点 гарчиг «复杂的状态补语»; номд байгаагаар.", "Багшийн ном 本课小结 «用单音节形容词重叠式描述某种状态» — 教学目标-д «表示人或事物的特征／描述人或事物»; номд байгаагаар.", "Багшийн ном PDF х.111 语言点（1）导入 — багш «你们» гэж асуусан ч дүгнэлтийн өгүүлбэр «她去买衣服…她在家看电视» — номд байгаагаар.", "Сурах бичгийн 练一练 (3 дүрэм × 3), 练习2 选词填空 / 练习3 描述图片 / 练习4 回答问题 — хариулт сурах бичиг, багшийн номд хэвлэгдээгүй тул answer талбаргүй. Багшийн номын 课文 асуулт-хариулт (teacher.text_questions) нь 练习4-ийн асуултаас өөр.", "Багшийн номын 汉字辨认练习 (米/来 · 姐/如 · 斤/近 · 查/香 · 帽/冒 — 组词) хоосон зайтай, хариулт хэвлэгдээгүй. 课文4-ийн «快速阅读，并回答：怎么才能和别人的关系变得更好？» асуултын хариулт хэвлэгдээгүй (a_zh байхгүй).", "Дасгалын номын сонсгол нэг CD тэмдэгтэй (16) — аудиог hsk3-workbook-16-part1…4.mp3 болгож хэсэг тус бүрт хуваасныг section.audio-д оноосон.", "Дасгалын ном 听力 第三/四部分 — номд зөвхөн сонголтууд хэвлэгдсэн; item.zh-д багшийн номын хавсралтын «问：» асуултыг оруулсан (transcript_zh-д бүтнээр).", "Сурах бичгийн 拼音课文-ын гарчгийн пиньинь (Zài gōngsī / Zài tóngshì jiā / Zài gōngsī) болон ярилцагчийн нэрийн пиньинь (Xiǎolì, Zhōu Míng, tóngshì, Xiǎogāng) схемд талбаргүй тул lines.pinyin-д зөвхөн яриаг оруулсан. 课文4 гарчиггүй.", "Багшийн номын 语言点(2)/(3)-ын хүрээтэй бүтэц («形容词＋得＋动词词组», «AA的») — teacher.steps-д «［框］» гэж тэмдэглэж оруулсан. Сурах бичгийн 注释2-т бүтцийн хүрээ байхгүй тул structure_rows-гүй.", "HSK 3.0 нэмэлт үгс (BLCUP 课件 补充HSK3.0, слайд 5, 18, 28, 38 — үг; слайд 29, 30, 40 — 语言点) hsk30-д."], "verified_pages": [110, 111, 112, 113, 114, 115, 116, 151, 152, 153, 154, 155, 156, 157, 158, 188, 189, 190], "schema_version": 1, "hsk30": {"source": "courseware", "ref": {"book": "hsk30_courseware", "pages": [5, 18, 28, 29, 30, 38, 40]}, "new_words": [{"n": 1, "zh": "的话", "pinyin": "dehuà", "pos": "aux.", "en": "if", "text": 1}, {"n": 2, "zh": "市", "pinyin": "shì", "pos": "n.", "en": "city", "text": 1}, {"n": 3, "zh": "斤", "pinyin": "jīn", "pos": "m.", "en": "jin (1/2 kilogram)", "text": 2}, {"n": 4, "zh": "查", "pinyin": "chá", "pos": "v.", "en": "look up", "text": 3}, {"n": 5, "zh": "牙", "pinyin": "yá", "pos": "n.", "en": "tooth", "text": 4}, {"n": 6, "zh": "牙刷", "pinyin": "yáshuā", "pos": "n.", "en": "toothbrush", "text": 4}, {"n": 7, "zh": "刷", "pinyin": "shuā", "pos": "v.", "en": "brush", "text": 4}, {"n": 8, "zh": "有用", "pinyin": "yǒuyòng", "pos": "adj.", "en": "useful", "text": 4}, {"n": 9, "zh": "别的", "pinyin": "biéde", "pos": "pron.", "en": "other", "text": 4}, {"n": 10, "zh": "有关", "pinyin": "yǒuguān", "pos": "v./prep.", "en": "related/regarding", "text": 4}], "grammar": [{"n": 1, "title_zh": "好+几/多+量词", "explanation_zh": "", "examples": [{"zh": "他一个人吃了好几块蛋糕。"}, {"zh": "今天她又买了好多件衣服。"}, {"zh": "检查好几次了，但是没什么用。"}]}, {"n": 2, "title_zh": "AA儿", "explanation_zh": "", "examples": [{"zh": "您慢慢儿走。"}, {"zh": "如果要来，明天就早早儿来！"}, {"zh": "每次医生都告诉我，回家好好儿刷牙。"}]}, {"n": 3, "title_zh": "变(v) VS 变化(n/v)", "explanation_zh": "", "examples": [{"zh": "最近几十年北京的变化很大。"}, {"zh": "快五年了，你几乎没变/变化。"}, {"zh": "这样才能和别人的关系变得更好。"}, {"zh": "她变漂亮了。"}]}], "exercises": [], "unclear": []}}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk3-l17', 'hsk3', 'HSK3', 17, '谁都有办法看好你的“病”', 'Shéi dōu yǒu bànfǎ kànhǎo nǐ de “bìng”', 'Everybody is able to cure your “disease”', '{"level": "hsk3", "lesson": 17, "book": "HSK3", "title_zh": "谁都有办法看好你的“病”", "title_pinyin": "Shéi dōu yǒu bànfǎ kànhǎo nǐ de “bìng”", "title_en": "Everybody is able to cure your “disease”", "textbook": {"ref": {"book": "textbook", "pages": [159, 160, 161, 162, 163, 164, 165, 166]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①邻居 línjū", "②爱好 àihào", "③选择 xuǎnzé", "④饱 bǎo", "⑤渴 kě", "⑥冬天 dōngtiān"], "pictures_desc_en": ["A: a snow-covered wooden cabin among snowy fir trees", "B: four smiling people standing together in front of a house with a red door", "C: a fair-haired woman sitting at a dining table, covering her mouth with her hand", "D: a man in a suit, seen from behind, standing in front of several white doors with arrows pointing down at them", "E: a blackboard with “WHAT''S YOUR HOBBY?” written on it in chalk", "F: a woman with a towel around her neck drinking water from a glass"]}, {"instruction_zh": "给下面的动词加上合适的宾语", "instruction_en": "Add an appropriate object after each of the following verbs.", "items": ["例如：学习 汉语", "介绍________", "打扫________", "检查________", "锻炼________", "帮助________", "复习________"]}], "texts": [{"n": 1, "title_zh": "在公司", "title_en": "In the company", "kind": "dialogue", "audio": "hsk3-textbook-1701.mp3", "lines": [{"speaker": "小丽", "zh": "周经理，下个星期我可以请几天假吗？", "pinyin": "Zhōu jīnglǐ, xià ge xīngqī wǒ kěyǐ qǐng jǐ tiān jià ma?"}, {"speaker": "周明", "zh": "你有什么事？", "pinyin": "Nǐ yǒu shénme shì?"}, {"speaker": "小丽", "zh": "我的一个老朋友结婚，我跟他两年没见了。", "pinyin": "Wǒ de yí ge lǎo péngyou jié hūn, wǒ gēn tā liǎng nián méi jiàn le."}, {"speaker": "周明", "zh": "你一共想请几天假？", "pinyin": "Nǐ yígòng xiǎng qǐng jǐ tiān jià?"}, {"speaker": "小丽", "zh": "三天。", "pinyin": "Sān tiān."}], "new_words": [{"n": 1, "zh": "请假", "pinyin": "qǐng jià", "pos": "v.", "en": "to ask for leave", "text": 1}, {"n": 2, "zh": "一共", "pinyin": "yígòng", "pos": "adv.", "en": "in total", "text": 1}]}, {"n": 2, "title_zh": "在公司", "title_en": "In the company", "kind": "dialogue", "audio": "hsk3-textbook-1702.mp3", "lines": [{"speaker": "同事", "zh": "小丽，那个高高的男人是你们公司的吗？你对他了解吗？", "pinyin": "Xiǎolì, nàge gāogāo de nánrén shì nǐmen gōngsī de ma? Nǐ duì tā liǎojiě ma?"}, {"speaker": "小丽", "zh": "我们过去是邻居，后来是大学同学，关系一直很不错。", "pinyin": "Wǒmen guòqù shì línjū, hòulái shì dàxué tóngxué, guānxì yìzhí hěn búcuò."}, {"speaker": "同事", "zh": "他一般喜欢做什么？", "pinyin": "Tā yìbān xǐhuan zuò shénme?"}, {"speaker": "小丽", "zh": "他有很多爱好，唱歌、画画儿、踢足球，什么都会。", "pinyin": "Tā yǒu hěn duō àihào, chàng gē, huà huàr, tī zúqiú, shénme dōu huì."}, {"speaker": "同事", "zh": "真的？那你介绍我们认识认识吧。", "pinyin": "Zhēn de? Nà nǐ jièshào wǒmen rènshi rènshi ba."}, {"speaker": "小丽", "zh": "不行，现在他是我丈夫。", "pinyin": "Bù xíng, xiànzài tā shì wǒ zhàngfu."}], "new_words": [{"n": 3, "zh": "邻居", "pinyin": "línjū", "pos": "n.", "en": "neighbour", "text": 2}, {"n": 4, "zh": "后来", "pinyin": "hòulái", "pos": "n.", "en": "later, afterwards", "text": 2}, {"n": 5, "zh": "爱好", "pinyin": "àihào", "pos": "n.", "en": "hobby, interest", "text": 2}]}, {"n": 3, "title_zh": "在家", "title_en": "At home", "kind": "dialogue", "audio": "hsk3-textbook-1703.mp3", "lines": [{"speaker": "周太太", "zh": "最近我觉得哪儿都不舒服，你带我去医院检查检查吧。", "pinyin": "Zuìjìn wǒ juéde nǎr dōu bù shūfu, nǐ dài wǒ qù yīyuàn jiǎnchá jiǎncha ba."}, {"speaker": "周明", "zh": "不用去医院，谁都有办法看好你的“病”。我问你，你多久没运动了？", "pinyin": "Búyòng qù yīyuàn, shéi dōu yǒu bànfǎ kànhǎo nǐ de “bìng”. Wǒ wèn nǐ, nǐ duō jiǔ méi yùndòng le?"}, {"speaker": "周太太", "zh": "我三年没运动了。", "pinyin": "Wǒ sān nián méi yùndòng le."}, {"speaker": "周明", "zh": "谁都知道运动对身体好。但是你吃饱了就睡。", "pinyin": "Shéi dōu zhīdào yùndòng duì shēntǐ hǎo. Dànshì nǐ chībǎole jiù shuì."}, {"speaker": "周太太", "zh": "为了健康，我真应该多锻炼锻炼了。从明天起，我决定每天去长跑。", "pinyin": "Wèile jiànkāng, wǒ zhēn yīnggāi duō duànliàn duànlian le. Cóng míngtiān qǐ, wǒ juédìng měi tiān qù chángpǎo."}], "new_words": [{"n": 6, "zh": "办法", "pinyin": "bànfǎ", "pos": "n.", "en": "way, approach", "text": 3}, {"n": 7, "zh": "饱", "pinyin": "bǎo", "pos": "adj.", "en": "full, having eaten one’s fill", "text": 3}, {"n": 8, "zh": "为了", "pinyin": "wèile", "pos": "prep.", "en": "for the sake of", "text": 3}, {"n": 9, "zh": "决定", "pinyin": "juédìng", "pos": "v.", "en": "to decide", "text": 3}]}, {"n": 4, "kind": "narrative", "audio": "hsk3-textbook-1704.mp3", "lines": [{"zh": "“运动很重要”这句话谁都懂。", "pinyin": "“Yùndòng hěn zhòngyào” zhè jù huà shéi dōu dǒng."}, {"zh": "但是你知道怎么运动吗？", "pinyin": "Dànshì nǐ zhīdào zěnme yùndòng ma?"}, {"zh": "第一，要选择“对”的时间。", "pinyin": "Dì yī, yào xuǎnzé “duì” de shíjiān."}, {"zh": "一般来说，早上9点是最好的时间，冬天要再晚一些。", "pinyin": "Yìbān lái shuō, zǎoshang jiǔ diǎn shì zuì hǎo de shíjiān, dōngtiān yào zài wǎn yìxiē."}, {"zh": "第二，要选择“对”的地点，公园、山上、游泳馆，这些地方都可以运动。", "pinyin": "Dì èr, yào xuǎnzé “duì” de dìdiǎn, gōngyuán, shānshang, yóuyǒngguǎn, zhèxiē dìfang dōu kěyǐ yùndòng."}, {"zh": "第三，必须要根据自己的健康情况运动。", "pinyin": "Dì sān, bìxū yào gēnjù zìjǐ de jiànkāng qíngkuàng yùndòng."}, {"zh": "如果你很久没爬山或者游泳了，运动一会儿就一定要休息休息。", "pinyin": "Rúguǒ nǐ hěn jiǔ méi pá shān huòzhě yóu yǒng le, yùndòng yíhuìr jiù yídìng yào xiūxi xiūxi."}, {"zh": "还要记得刚运动完口渴的时候，不要马上喝水。", "pinyin": "Hái yào jìde gāng yùndòng wán kǒu kě de shíhou, búyào mǎshàng hē shuǐ."}], "new_words": [{"n": 10, "zh": "选择", "pinyin": "xuǎnzé", "pos": "v.", "en": "to choose", "text": 4}, {"n": 11, "zh": "冬(天)", "pinyin": "dōng (tiān)", "pos": "n.", "en": "winter", "text": 4}, {"n": 12, "zh": "必须", "pinyin": "bìxū", "pos": "adv.", "en": "must", "text": 4}, {"n": 13, "zh": "根据", "pinyin": "gēnjù", "pos": "prep.", "en": "according to, based on", "text": 4}, {"n": 14, "zh": "情况", "pinyin": "qíngkuàng", "pos": "n.", "en": "condition, situation", "star": true, "text": 4}, {"n": 15, "zh": "口", "pinyin": "kǒu", "pos": "n.", "en": "mouth", "text": 4}, {"n": 16, "zh": "渴", "pinyin": "kě", "pos": "adj.", "en": "thirsty", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "双音节动词重叠", "title_en": "Reduplication of Disyllabic Verbs", "explanation_zh": "双音节动词重叠形式为“ABAB”，如“休息休息”，表达动作时间短、尝试等意义。例如：", "explanation_en": "The form of a reduplicated disyllabic verb is “ABAB”, such as “休息休息”, indicating a short action or an attempt. For example:", "structure_rows": ["ABAB"], "examples": [{"n": 1, "zh": "他是谁？你介绍我们认识认识吧。"}, {"n": 2, "zh": "他是新来的，有时间你帮助帮助他吧。"}, {"n": 3, "zh": "这是本新书，你学习学习吧。"}, {"n": 4, "zh": "我真应该多锻炼锻炼了。"}], "practice_instruction_zh": "练一练　完成句子 Complete the sentences.", "practice": [{"n": 1, "zh": "我不太舒服，我想去医院________。"}, {"n": 2, "zh": "太累了，我们________吧。"}, {"n": 3, "zh": "房间不太干净，我们________吧。"}]}, {"n": 2, "title_zh": "疑问代词活用3", "title_en": "Flexible Use of Interrogative Pronouns 3", "explanation_zh": "汉语中，可以用“谁”“什么”“怎么”“哪儿”等疑问代词代替某个范围内的每一个对象，它们都有相同的情况，没有例外。例如：", "explanation_en": "In Chinese, interrogative pronouns such as “谁”, “什么”, “怎么” and “哪儿” can be used to refer to every member in a certain scope, indicating all of them are the same in a certain way without exception. For example:", "examples": [{"n": 1, "zh": "谁都喜欢小丽。"}, {"n": 2, "zh": "小刚什么都喜欢吃。"}, {"n": 3, "zh": "我们怎么去公园都可以。"}, {"n": 4, "zh": "最近我觉得哪儿都不舒服。"}], "practice_instruction_zh": "练一练　完成对话 Complete the dialogues.", "practice": [{"n": 1, "zh": "A：你喜欢吃什么菜？ B：________。"}, {"n": 2, "zh": "A：我们什么时候去看电影？ B：________。"}, {"n": 3, "zh": "A：我们星期天去哪儿玩儿？ B：________。"}]}], "exercises": [{"n": 1, "type_zh": "朗读", "instruction_zh": "朗读下列短语和句子", "instruction_en": "Read the following phrases and sentences aloud.", "audio": "hsk3-textbook-1705.mp3", "items": [{"n": 1, "zh": "请假：请病假／请事假／请两天假／下个星期我可以请几天假吗？"}, {"n": 2, "zh": "爱好：很多爱好／我的爱好／我的爱好是游泳／他有很多爱好。"}, {"n": 3, "zh": "办法：好办法／没有办法／学汉语的办法／谁都有办法看好你的“病”。"}, {"n": 4, "zh": "选择：选择题／选择时间／很难选择／应该选择“对”的时间锻炼。"}, {"n": 5, "zh": "渴：很渴／不渴／口渴了／刚运动完口渴的时候，不要马上喝水。"}]}, {"n": 2, "type_zh": "选词填空", "instruction_zh": "选择恰当的词语填空", "instruction_en": "Choose the proper words to fill in the blanks.", "word_bank": [["为了", "请假", "后来", "爱好", "冬天"], ["一共", "饱", "邻居", "决定", "办法"]], "items": [{"n": 1, "zh": "老师，我不舒服，我想跟您________。"}, {"n": 2, "zh": "________了解中国文化，我常常去旅行。"}, {"n": 3, "zh": "我以前在美国学习，________来中国留学。"}, {"n": 4, "zh": "我最喜欢的季节是________。"}, {"n": 5, "zh": "我的________跟你的不一样，我更喜欢游泳。"}, {"n": 6, "zh": "A：你认识那个人吗？ B：认识，他是我的新________。"}, {"n": 7, "zh": "A：这次HSK你考得怎么样？ B：好极了，________考了280分。"}, {"n": 8, "zh": "A：我的口语不太好，你帮我想想________吧。 B：你最好多跟中国人聊聊天儿。"}, {"n": 9, "zh": "A：吃________了吗？ B：当然了，你看我们点了这么多菜。"}, {"n": 10, "zh": "A：明年你打算回国吗？ B：我还没________呢。"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "A：老师，您可以帮我________口语吗？ B：当然可以。从什么时候开始？ A：________都可以。 B：那从这个星期开始吧。", "picture_desc_en": "A smiling male teacher leaning over two young girls sitting at a desk in a classroom; a globe in the background."}, {"n": 2, "zh": "A：快考试了，你________吧？ B：老师，我应该复习什么啊？ A：________。 B：好吧，那我都复习吧。", "picture_desc_en": "A smiling man sitting beside a boy who is writing with a pencil at a desk; paint pots on the desk."}, {"n": 3, "zh": "A：今天天气不错，我们出去________吧。 B：好，我去换衣服。 A：我们去哪个公园呢？ B：________。", "picture_desc_en": "Elderly people in Chinese-style jackets doing tai chi outdoors in a park."}, {"n": 4, "zh": "A：周末你打算做什么？ B：我打算在家里________。 A：你每个周末都打扫房间吗？ B：不一定。________就打扫一下。", "picture_desc_en": "A smiling young woman in a floral apron and rubber gloves holding a spray bottle in a kitchen, next to a refrigerator."}]}, {"n": 4, "type_zh": "回答问题", "instruction_zh": "根据课文回答问题", "instruction_en": "Answer the questions according to the texts.", "items": [{"n": 1, "zh": "小丽为什么要请假？请几天假？"}, {"n": 2, "zh": "小丽的丈夫有什么爱好？"}, {"n": 3, "zh": "周太太为什么不舒服？"}, {"n": 4, "zh": "周太太有什么打算？"}, {"n": 5, "zh": "什么时间运动最好？"}, {"n": 6, "zh": "运动的时候要注意什么问题？"}]}], "characters": {"knowledge_title_zh": "形声字3", "knowledge_zh": "内外结构的形声字有两种。一种是“外形内声”，也就是形旁在外边，声旁在里边。例如：\n汉字 | 发音 | 声旁 | 形旁\n园 | yuán | 元（yuán） | 囗\n病 | bìng | 丙（bǐng） | 疒\n另一种是“内形外声”，也就是形旁在里边，声旁在外边。例如：\n汉字 | 发音 | 声旁 | 形旁\n问 | wèn | 门（mén） | 口\n闻 | wén | 门（mén） | 耳\n\n旧字新词：读读下面的词语，想想组成的新词是什么意思。", "knowledge_en": "Pictophonetic Characters 3. There are two types of pictophonetic characters which have an inside-outside structure. One has the phonetic component inside the semantic component. For example:\nCharacter | Pronounciation | Phonetic Component | Semantic Component\nThe other has the semantic component inside the phonetic component. For example:\n\nWord Game: Read the following words and guess the meanings of the newly-formed ones.", "characters": [{"zh": "园", "pinyin": "yuán", "note_zh": "外形内声：声旁 元（yuán），形旁 囗"}, {"zh": "病", "pinyin": "bìng", "note_zh": "外形内声：声旁 丙（bǐng），形旁 疒"}, {"zh": "问", "pinyin": "wèn", "note_zh": "内形外声：声旁 门（mén），形旁 口"}, {"zh": "闻", "pinyin": "wén", "note_zh": "内形外声：声旁 门（mén），形旁 耳"}], "word_game": [{"parts": ["结婚", "请假"], "result": "婚假"}, {"parts": ["怎么", "办法"], "result": "怎么办"}, {"parts": ["喜欢", "爱好"], "result": "喜爱"}], "confusable_pairs": [["居", "据"], ["饱", "跑"], ["必", "心"], ["喝", "渴"], ["选", "洗"]]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，一个人说说刚到一个新地方时的感受，另一个人说说熟悉了这个地方后的感受。用疑问代词的非疑问用法。", "instruction_en": "Work in pairs. One talks about the feeling when you get to a place for the first time, and the other talks about the feeling when you''ve got familiar with the place. Use interrogative pronouns in a non-interrogative way.", "example_zh": ["A：我刚到这里，谁都不认识。", "B：我的朋友都在这里，我谁都认识。"]}, {"title_zh": "小组活动", "instruction_zh": "3~4人一组，想想已经学过的双音节动词，把能重叠的写下来，并用它们说句子。", "instruction_en": "Work in groups of 3-4. Think about the disyllabic verbs you’ve already learned. Write down those which can be reduplicated, and say a sentence using each of the reduplicated verbs.", "example_zh": ["打扫——打扫打扫——客人要来了，我要打扫打扫房间。", "（书中另有4条空白横线供书写）"]}], "saying": {"zh": "早睡早起身体好", "pinyin": "Zǎo shuì zǎo qǐ shēntǐ hǎo", "en": "Keeping early hours is good for your health", "explanation_zh": "“早睡早起身体好”，这句话的意思是晚上早点儿睡觉，早上早点儿起床，这样对身体很有好处。这句话告诉我们养成良好的作息习惯有利于身体健康。", "explanation_en": "“早睡早起身体好” literally means one will become healthy if he/she sleeps early at night and gets up early in the morning. It tells us that keeping a proper work-rest schedule is good for our health."}}, "teacher": {"ref": {"book": "teacher", "pages": [117, 118, 119, 120, 121, 122, 123]}, "objectives_zh": ["重点词语：学生能够熟练掌握：“请假、一共、办法、决定、根据”的词义和用法", "语言点：学生能够了解并掌握：（1）双音节动词重叠表示动作时间短、尝试等（2）疑问代词活用3：代替某个范围内的每一个对象", "汉字：学生能够：（1）了解内外结构的形声字（2）根据已学生词猜测出3个旧字新词“婚假、怎么办、喜爱”的意思", "功能：学生能够：（1）用双音动词重叠形式描述动作（2）用疑问代词表示任指"], "steps": [{"title_zh": "复习旧课", "body_zh": "1 教师展示第16课的热身图片，请学生根据图片说出生词。\n2 教师根据第16课的内容进行提问。\n（1）你喜欢吃什么水果？为什么？\n（2）你觉得现在忙吗？有多忙？\n（3）如果你是汉语比赛的第一名，你高兴吗？你会做什么？\n（4）如果你有很多钱，你会做什么？\n（5）请你描述我们班的一个同学，看看大家知道不知道他／她是谁。"}, {"title_zh": "学习新课 1 热身", "body_zh": "热身1：教师可依次出示热身部分的词语卡片，要求学生集体或单个说出图片对应的编号，教师评判正误；最后全体学生齐读热身环节所有词语，要求语音标准，声调准确。\n答案：①B　②E　③D　④C　⑤F　⑥A\n热身2：可留至语言点（1）“双音节动词重叠”导入时使用。"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n请假、一共、邻居、后来、爱好、办法、饱、为了、决定、选择、冬（天）、必须、根据、情况、口、渴\n· 教师先带领学生快速认读一遍生词；\n· 取消拼音，带领学生再次认读；\n· 请单个学生独自认读2-3个生词；\n· 最后全班一起快速认读所有的生词。\n（2）生词讲解方式\n· 直观法（如图片、照片、实物等）展示：邻居、爱好、选择\n· 对比法展示：以前—后来、饿—饱—渴、春天—夏天—秋天—冬天\n· 启发式引导：一共、为了、必须\n一杯咖啡5块钱，一个面包2块钱，我花了多少钱？——一共7块钱。\n我想有一个好身体，应该做什么？——为了有一个好身体，你应该多运动。\n明天老师可以不来给大家上课吗？——不可以，您必须来上课。\n（3）重点生词扩展及常用搭配\n请假—请个假—请三天假—请病假—你可以帮我跟老师请个假吗？\n一共—一共五十个人—一共四天—一共八个小时—这些菜一共多少钱？\n办法—一个办法—好办法—想不出办法来—她总是有好办法。\n决定—决定去旅游—你们决定中午去哪儿吃饭？\n　—还没决定\n　—一个决定—做决定—告诉我你的决定。\n根据—根据时间—根据情况—请大家根据要求完成工作。\n练习册相关练习：第113页／一／第一部分，第116页／二／第二部分"}, {"title_zh": "3 语言点（1）双音节动词重叠", "body_zh": "① 语言点解析\n双音节动词AB的重叠形式为“ABAB”，如“休息休息”，表达动作时间短、尝试等意义。\n② 语言点导入\n教师可利用本课热身2导入语言点。\n教师带领学生熟读所有动词，学生两人一组，合作完成热身2。\n教师让学生回忆之前学过的单音节动词重叠形式，并引导学生说出双音动词重叠形式。\n教师：我想学学汉语。用“学习”怎么说？\n学生：我想学习学习汉语。\n③ 语言点操练\n教师可根据热身2的双音节动词操练语言点。\n教师：“请你介绍自己。”客气一点儿怎么说？\n学生：请你介绍介绍自己。\n目标句：客人来以前，我要打扫打扫房间。\n　　　　写完作业以后应该检查检查。\n　　　　多锻炼锻炼，对身体好。\n　　　　明天要考试了，我必须复习复习。\n④ 语言点扩展练习\n教师给出情境，请学生回答。\n特别累的时候，你想做什么？\n看到一个又高又漂亮的女孩儿，你会说什么？"}, {"title_zh": "3 语言点（2）疑问代词活用3", "body_zh": "① 语言点解析\n汉语中，可以用“谁”“什么”“怎么”“哪儿”等疑问代词代替某个范围内的每一个对象，它们都有相同的情况，没有例外。\n② 语言点导入\n教师根据实际情况，给出情境，提问并引入语言点。\n教师：大家都知道长城吗？\n学生：我们都知道。\n教师引导学生说出：谁都知道长城。\n③ 语言点操练\n教师可给出句子，让学生用语言点改写，进行操练。\n大家都觉得茶很好喝。——谁都觉得茶很好喝。\n你可以上午来找我，也可以下午来找我，还可以晚上来找我……——你什么时候都可以来找我。\n我们可以走路去，也可以坐车去，还可以坐地铁去……——我们怎么去都可以。\n④ 语言点扩展练习\n教师给出前半句，请学生用语言点完成句子。\n我们的校长很有名，________。\n我们学校举行文化节的时候，人多极了，________。\n这个地方吃的贵，喝的贵，玩儿的也贵，________。"}, {"title_zh": "4 课文 课文1", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n女的（小丽）在做什么？——她在跟周经理请假。\n小丽为什么要请假？——她的一个老朋友下个星期结婚，她们两年没见了。\n小丽想请几天假？——她想请三天假。\n（2）教师领读课文两遍，让学生分角色朗读课文。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：……，……我可以……吗？\nB：你……？\nA：我……，我……。\nB：你一共想……？\nA：……。"}, {"title_zh": "4 课文 课文2", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n那个高高的男人是谁？——小丽和他过去是邻居，后来是大学同学。\n他有什么爱好？——他有很多爱好，唱歌、画画儿、踢足球，什么都会。\n小丽为什么不愿意把那个男人介绍给同事？——因为那个男人现在是小丽的丈夫。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）模仿练习\n学生两人一组，根据提示词模仿课文内容进行对话练习。\nA：……，那个……？你对他……？\nB：我们过去……，后来……，关系……。\nA：他一般……？\nB：他有……，……，什么都会。\nA：真的？那你……。\nB：不行，……。"}, {"title_zh": "4 课文 课文3", "body_zh": "（1）让学生听两遍录音并回答下列问题：\n女的（周太太）为什么要去医院检查检查？——因为她最近哪儿都不舒服。\n男的（周明）觉得用不用去医院？——他觉得不用去医院，谁都有办法看好太太的“病”。\n周太太多长时间没运动了？——她三年没运动了。\n周太太有什么不好的习惯？——她吃饱了就睡。\n为了健康，周太太有什么决定？——她决定多锻炼锻炼，从明天起，每天去长跑。\n（2）教师领读课文两遍，让学生分角色朗读课文，注意说话人的语气。\n（3）教师给提示词，带领学生复述课文。\n提示词：哪儿、都、检查、办法、没运动、饱、锻炼、决定"}, {"title_zh": "4 课文 课文4", "body_zh": "（1）快速阅读，并回答：运动的时候要注意哪三点？\n（2）教师领读课文两遍，并回答下列问题：\n运动的时候要选择什么时间？——早上9点是最好的时间，冬天要再晚一些。\n应该选择什么样的地点运动？——公园、山上、游泳馆都可以运动。\n运动的时候还应该注意什么？——要根据自己的健康情况运动。\n刚运动完口渴的时候能不能喝水？——刚运动完的时候，不要马上喝水。\n（3）教师给提示词，带领学生复述课文。\n提示词：谁都懂、选择、一般来说、地点、必须、根据、休息、口渴\n（4）教师请学生根据课文，说说自己怎么运动，什么时候运动，除了课本上说的以外，运动的时候还要注意些什么。\n练习册相关练习：第120页／四"}, {"title_zh": "5 汉字", "body_zh": "形声字3：\n① 知识点解析：本课介绍内外结构的形声字，包括外形内声、内形外声。\n教师逐一展示课本第149页外形内声表格中的字，请学生分别读出形旁和声旁，说说形旁的意思。\n园：形旁是“口”，意思是围起来的一块地方；声旁是“元”（yuan）。\n病：形旁是“疒”，意思是疾病、生病；声旁是“丙”（bing）。\n请学生归纳这些汉字的结构——声旁与形旁的位置：\n“园”“病”的里边是声旁（发音），外边是形旁（意思）。\n教师展示更多外形内声的汉字，请学生说出形旁与声旁，如：房。\n教师逐一展示课本第149页内形外声表格中的字，请学生分别读出形旁和声旁，说说形旁的意思。\n问：形旁是“口”，意思是用嘴询问；声旁是“门”（men）。\n闻：形旁是“耳”，意思是用耳朵听到；声旁是“门”（men）。\n请学生归纳这些汉字的结构——声旁与形旁的位置：\n“问”“闻”的外边是声旁（发音），里边是形旁（意思）。\n教师展示更多内形外声的汉字，请学生说出形旁与声旁，如：闷。\n② 汉字练习\n教师板书或者用手指在空中书写本课形声字“园、病、问、闻”，带领学生一起识记形声字的笔画笔顺。\n请学生用本课所学形声字组词：\n参考答案：\n园：花园、公园\n病：生病、看病\n问：问题、请问\n闻：新闻\n旧字新词：\n① 教师领读以前学过的词语和新词，并让学生猜猜新词的意思。\n· 领读：结婚、请假、婚假\n问学生：什么是“婚假”？——结婚时候的假期。\n扩展提问：还有什么“假”？——病假、事假。（根据实际情况选用）\n· 领读：怎么、办法、怎么办\n问学生：什么时候说“怎么办”？——问别人办法的时候。\n· 领读：喜欢、爱好、喜爱\n问学生：什么是“喜爱”？——对人或事物喜欢或有好感。\n② 教师领读新词扩展，通过情景，理解新词的意思和用法：\n婚假：请婚假／婚假很短／三天婚假／你打算请几天婚假？\n怎么办：遇到问题的时候，怎么办？／考试的时候看不懂题怎么办？\n喜爱：这是我最喜爱的饮料／你们国家的年轻人最喜爱什么运动？\n汉字辨认练习：\n辨认下列汉字并组词。\n居：________、________　饱：________、________\n据：________、________　跑：________、________\n必：________、________　喝：________、________\n心：________、________　渴：________、________\n选：________、________\n洗：________、________\n练习册相关练习：第119页／三／第三部分"}, {"title_zh": "6 补充课堂活动——我来做，你来猜", "body_zh": "A、B两个同学一组到教室前边完成，教师给A同学和其他同学出示词语卡片，B同学不能看。A同学要用动作表演出卡片上词语的内容，B同学根据A同学的表演猜出这个词语是什么，并用这个词语说一个句子。\n参考词语：请假、邻居、选择、冬天、没办法、吃饱了、口渴……"}, {"title_zh": "7 俗语", "body_zh": "教师请学生自己说出这句俗语的含义，并说说自己是不是早睡早起的人。教师可以根据实际情况，询问学生所在国家有没有相似的俗语。"}, {"title_zh": "8 本课小结", "body_zh": "· 语言点：用双音节动词重叠表示时间短、尝试的意义\n　　　　　用疑问代词表示任指\n· 汉　字：形声字（内外结构）\n　　　　　旧字新词：婚假、怎么办、喜爱"}], "notes_zh": ["热身2：可留至语言点（1）“双音节动词重叠”导入时使用。", "教师让学生回忆之前学过的单音节动词重叠形式，并引导学生说出双音动词重叠形式。（语言点1）", "“园”“病”的里边是声旁（发音），外边是形旁（意思）；“问”“闻”的外边是声旁（发音），里边是形旁（意思）。（汉字）", "问学生：什么是“婚假”？——结婚时候的假期。扩展提问：还有什么“假”？——病假、事假。（根据实际情况选用）（汉字）"], "warmup_answers_zh": ["热身1 答案：①B　②E　③D　④C　⑤F　⑥A", "热身2：可留至语言点（1）“双音节动词重叠”导入时使用。"], "text_questions": [{"text": 1, "q_zh": "女的（小丽）在做什么？", "a_zh": "她在跟周经理请假。"}, {"text": 1, "q_zh": "小丽为什么要请假？", "a_zh": "她的一个老朋友下个星期结婚，她们两年没见了。"}, {"text": 1, "q_zh": "小丽想请几天假？", "a_zh": "她想请三天假。"}, {"text": 2, "q_zh": "那个高高的男人是谁？", "a_zh": "小丽和他过去是邻居，后来是大学同学。"}, {"text": 2, "q_zh": "他有什么爱好？", "a_zh": "他有很多爱好，唱歌、画画儿、踢足球，什么都会。"}, {"text": 2, "q_zh": "小丽为什么不愿意把那个男人介绍给同事？", "a_zh": "因为那个男人现在是小丽的丈夫。"}, {"text": 3, "q_zh": "女的（周太太）为什么要去医院检查检查？", "a_zh": "因为她最近哪儿都不舒服。"}, {"text": 3, "q_zh": "男的（周明）觉得用不用去医院？", "a_zh": "他觉得不用去医院，谁都有办法看好太太的“病”。"}, {"text": 3, "q_zh": "周太太多长时间没运动了？", "a_zh": "她三年没运动了。"}, {"text": 3, "q_zh": "周太太有什么不好的习惯？", "a_zh": "她吃饱了就睡。"}, {"text": 3, "q_zh": "为了健康，周太太有什么决定？", "a_zh": "她决定多锻炼锻炼，从明天起，每天去长跑。"}, {"text": 4, "q_zh": "运动的时候要注意哪三点？"}, {"text": 4, "q_zh": "运动的时候要选择什么时间？", "a_zh": "早上9点是最好的时间，冬天要再晚一些。"}, {"text": 4, "q_zh": "应该选择什么样的地点运动？", "a_zh": "公园、山上、游泳馆都可以运动。"}, {"text": 4, "q_zh": "运动的时候还应该注意什么？", "a_zh": "要根据自己的健康情况运动。"}, {"text": 4, "q_zh": "刚运动完口渴的时候能不能喝水？", "a_zh": "刚运动完的时候，不要马上喝水。"}], "summary_zh": "语言点：用双音节动词重叠表示时间短、尝试的意义；用疑问代词表示任指。汉字：形声字（内外结构）；旧字新词：婚假、怎么办、喜爱。"}, "workbook": {"ref": {"book": "workbook", "pages": [117, 118, 119, 120, 121, 122, 123, 124]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 1-5: Choose the right picture for each dialogue you hear.", "audio": "hsk3-workbook-17-part1.mp3", "items": [{"n": "例", "zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "transcript_zh": "男：喂，请问张经理在吗？ 女：他正在开会，您半个小时以后再打，好吗？", "options": {"A": "[picture] three men in suits talking at a meeting table with glasses of water on it", "B": "[picture] two elderly couples greeting and embracing each other in front of a house", "C": "[picture] a girl in a helmet standing by a bicycle drinking from a bottle, next to a crying toddler in a helmet sitting on a tricycle", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a piece of cake on a plate and a cup of coffee", "F": "[picture] three children in winter hats lying on their stomachs in the snow"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [117]}}, {"n": 1, "zh": "", "options": {"A": "[picture] three men in suits talking at a meeting table with glasses of water on it", "B": "[picture] two elderly couples greeting and embracing each other in front of a house", "C": "[picture] a girl in a helmet standing by a bicycle drinking from a bottle, next to a crying toddler in a helmet sitting on a tricycle", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a piece of cake on a plate and a cup of coffee", "F": "[picture] three children in winter hats lying on their stomachs in the snow"}, "transcript_zh": "女：你的早饭只有一杯咖啡和一小块蛋糕，吃不饱。要不要再来一个鸡蛋或者水果？ 男：没办法，为了瘦一点儿，我必须少吃。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 2, "zh": "", "options": {"A": "[picture] three men in suits talking at a meeting table with glasses of water on it", "B": "[picture] two elderly couples greeting and embracing each other in front of a house", "C": "[picture] a girl in a helmet standing by a bicycle drinking from a bottle, next to a crying toddler in a helmet sitting on a tricycle", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a piece of cake on a plate and a cup of coffee", "F": "[picture] three children in winter hats lying on their stomachs in the snow"}, "transcript_zh": "男：雪下得真大，谁都没想到今年冬天能下这么大的雪。 女：是啊，你看孩子们玩儿得多高兴。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 3, "zh": "", "options": {"A": "[picture] three men in suits talking at a meeting table with glasses of water on it", "B": "[picture] two elderly couples greeting and embracing each other in front of a house", "C": "[picture] a girl in a helmet standing by a bicycle drinking from a bottle, next to a crying toddler in a helmet sitting on a tricycle", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a piece of cake on a plate and a cup of coffee", "F": "[picture] three children in winter hats lying on their stomachs in the snow"}, "transcript_zh": "男1：经理，下个星期我想请三天假，可以吗？ 男2：这个月你已经请了两个星期假了，不能再请了。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 4, "zh": "", "options": {"A": "[picture] three men in suits talking at a meeting table with glasses of water on it", "B": "[picture] two elderly couples greeting and embracing each other in front of a house", "C": "[picture] a girl in a helmet standing by a bicycle drinking from a bottle, next to a crying toddler in a helmet sitting on a tricycle", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a piece of cake on a plate and a cup of coffee", "F": "[picture] three children in winter hats lying on their stomachs in the snow"}, "transcript_zh": "男：你们好，我是你们的新邻居，昨天刚搬过来。这是我妻子。 女：欢迎你们！这是我丈夫。我们在这儿住了五年了，对这儿很了解，以后有什么问题都可以来找我们。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 5, "zh": "", "options": {"A": "[picture] three men in suits talking at a meeting table with glasses of water on it", "B": "[picture] two elderly couples greeting and embracing each other in front of a house", "C": "[picture] a girl in a helmet standing by a bicycle drinking from a bottle, next to a crying toddler in a helmet sitting on a tricycle", "D": "[picture] a smiling woman in a uniform talking on a telephone", "E": "[picture] a piece of cake on a plate and a cup of coffee", "F": "[picture] three children in winter hats lying on their stomachs in the snow"}, "transcript_zh": "女：玩儿了这么长时间，我渴了，我先喝点儿水。你不渴吗？ 男：我不渴，你喝吧，我等会儿你。喝完了我们去前边玩儿。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听句子，判断对错", "instruction_en": "Questions 6-10: Decide whether the statements are true or false based on the sentences you hear.", "audio": "hsk3-workbook-17-part2.mp3", "items": [{"n": "例1", "zh": "他希望自己很健康。", "transcript_zh": "为了让自己更健康，他每天都花一个小时去锻炼身体。", "answer": "√", "answer_ref": {"book": "workbook", "pages": [118]}}, {"n": "例2", "zh": "那块儿手表不是他的。", "transcript_zh": "今天我想早点儿回家。看了看手表，才5点。过了一会儿再看表，还是5点，我这才发现我的手表不走了。", "answer": "×", "answer_ref": {"book": "workbook", "pages": [118]}}, {"n": 6, "zh": "明天早上有一个重要的会议。", "transcript_zh": "明天早上请大家8点以前到公司会议室，做好开会的准备。明天的会议非常重要，谁都不能迟到，也不能请假。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 7, "zh": "那家药店晚上不能买药。", "transcript_zh": "为了方便大家，楼下新开了一家药店，24小时不休息，什么时候去都能买到药，几点去都有人工作。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 8, "zh": "有问题时，我们应该自己想办法。", "transcript_zh": "我们在生活中遇到问题时，不能什么事情都请别人帮忙，因为有些事情必须要自己来做选择和决定。", "answer": "√", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 9, "zh": "汉字比赛时写什么都可以。", "transcript_zh": "学校这个学期要举行一次汉字比赛，比赛是根据要求写汉字，一共写100个，谁有兴趣都可以参加。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 10, "zh": "有三个同学要介绍自己。", "transcript_zh": "大家好，这个学期我们班新来了2个同学，一共21个学生。现在，请新同学给大家介绍介绍自己，大家欢迎。", "answer": "×", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听短对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the short dialogues and choose the right answers.", "audio": "hsk3-workbook-17-part3.mp3", "items": [{"n": "例", "zh": "男的想让小王做什么？", "transcript_zh": "男：小王，帮我开一下门，好吗？谢谢！ 女：没问题。您去超市了？买了这么多东西。 问：男的想让小王做什么？", "options": {"A": "开门", "B": "拿东西", "C": "去超市买东西"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [118]}}, {"n": 11, "zh": "女的买什么回来了？", "options": {"A": "两瓶牛奶", "B": "一条鱼", "C": "什么都没买"}, "transcript_zh": "男：你不是去超市吗？怎么什么都没买？ 女：我在超市里拿了两瓶牛奶，三个面包，还拿了条鱼。后来发现没带钱包，只好都放回去了。 问：女的买什么回来了？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 12, "zh": "关于男的，可以知道什么？", "options": {"A": "口渴", "B": "什么都不想喝", "C": "不想喝冰水"}, "transcript_zh": "女：走了这么长时间，渴了吧？快坐下来休息休息，你想喝点儿什么？ 男：喝什么都行，先来杯冰水，然后再看看这儿有什么好喝的饮料。 问：关于男的，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 13, "zh": "女的去哪儿旅游了？", "options": {"A": "国外", "B": "很多城市", "C": "什么地方都没去"}, "transcript_zh": "男：听说你和丈夫去旅游了？去了哪些地方？怎么样？ 女：我们打算坐飞机去国外，找个安静的城市，好好休息休息，后来儿子生病了，为了照顾他，哪儿都没去。 问：女的去哪儿旅游了？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 14, "zh": "关于冬冬，可以知道什么？", "options": {"A": "觉得考试不容易", "B": "写得很慢", "C": "题都检查过了"}, "transcript_zh": "女：冬冬，你怎么这么快就考完了？做完题应该检查检查，看看有没有写错的字。 男：我已经检查过了，今天的考试题特别简单，所以很快就做完了。 问：关于冬冬，可以知道什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 15, "zh": "他们可能是什么关系？", "options": {"A": "经理和秘书", "B": "医生和病人", "C": "丈夫和妻子"}, "transcript_zh": "男：我昨天跑完步以后就一直腿疼，请您帮我检查检查，看看用不用吃点儿药。 女：你太久没运动了，所以腿疼。以后多出去运动运动，不用吃药。 问：他们可能是什么关系？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "一、听力 第四部分", "type_zh": "听力 第四部分", "instruction_zh": "第16–20题：听长对话，选择正确答案", "instruction_en": "Questions 16-20: Listen to the dialogues and choose the right answers.", "audio": "hsk3-workbook-17-part4.mp3", "items": [{"n": "例", "zh": "男的在做什么？", "transcript_zh": "女：晚饭做好了，准备吃饭了。 男：等一会儿，比赛还有三分钟就结束了。 女：快点儿吧，一起吃，菜冷了就不好吃了。 男：你先吃，我马上就看完了。 问：男的在做什么？", "options": {"A": "洗澡", "B": "吃饭", "C": "看电视"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [119]}}, {"n": 16, "zh": "关于男的，可以知道什么？", "options": {"A": "经常不来上课", "B": "什么都听得懂", "C": "没请过假"}, "transcript_zh": "男：老师，我可以请几天假吗？ 女：小雨，你看看，这个学期你都请了几次假了？ 男：老师，对不起，上个月是我妈妈来北京，我带她在中国旅游，然后是我姐姐来，前几天是我病了，下个星期我女朋友要来看我。 女：小雨，如果你再不来上课，就什么都听不懂了。 问：关于男的，可以知道什么？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 17, "zh": "男的为什么听新闻？", "options": {"A": "天气很好", "B": "喜欢新闻", "C": "准备考试"}, "transcript_zh": "女：你在听新闻？太阳从西边出来了？ 男：我对新闻没兴趣，主要是想提高提高我的汉语水平。 女：你一个学期都没认真学习了，现在才开始努力？ 男：明天就要考试了，我要复习复习。 问：男的为什么听新闻？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 18, "zh": "关于男的，可以知道什么？", "options": {"A": "想去饭馆吃", "B": "不想吃牛肉", "C": "什么都喜欢吃"}, "transcript_zh": "女：我有点儿饿了，我们出去找个人少点儿的饭馆吃饭吧。 男：这个时间，哪个饭馆人都多，我们在家吃吧，自己做。 女：好，家里有鱼，有鸡蛋，还有牛肉。牛肉你想怎么吃？跟鸡蛋一起做还是跟别的菜一起做？ 男：怎么做都行，我什么都爱吃。需要我帮忙吗？ 问：关于男的，可以知道什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 19, "zh": "关于男的，可以知道什么？", "options": {"A": "喜欢那里的冬天", "B": "不喜欢那里的学习环境", "C": "不习惯那里的天气"}, "transcript_zh": "女：你在国外留学这几年怎么样？那里的生活习惯了吗？ 男：那个地方的人很热情，学习环境也不错，学校里有两个图书馆。但是天气我还不太习惯。 女：怎么？那儿的天气跟我们这儿不一样吗？ 男：冬天特别长，从11月到第二年3月都比较冷。下大雪的时候，哪儿都不能去，只能在房间里看书。 问：关于男的，可以知道什么？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 20, "zh": "关于女的，可以知道什么？", "options": {"A": "坐着上课", "B": "是老师", "C": "什么地方都想去"}, "transcript_zh": "男：你在椅子上坐了一个多小时了，一句话都不说，怎么了？ 女：我上了一天课，给学生讲中国历史，现在什么都不想说。 男：那你先休息休息，一会儿我带你出去吃饭。 女：我现在哪儿都不想去，就想在家睡觉。我们晚点儿再吃饭吧。 问：关于女的，可以知道什么？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第21–25题：选择合适的问答", "instruction_en": "Questions 21-25: Match the two parts of the same dialogue.", "items": [{"n": "例", "zh": "你知道怎么去那儿吗？", "options": {"A": "你几点来都可以，明天上午我不忙。", "B": "这次是我叔叔病了，我要去医院照顾他。", "C": "月月，你有什么爱好？喜欢音乐还是画画儿？", "D": "今晚吃得太饱了，吃了很多米饭，饭后还吃了三块西瓜。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "那儿一年四季都像春天一样，哪个季节去都很舒服。"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [120]}}, {"n": 21, "zh": "周经理，明天上午您什么时候方便？", "options": {"A": "你几点来都可以，明天上午我不忙。", "B": "这次是我叔叔病了，我要去医院照顾他。", "C": "月月，你有什么爱好？喜欢音乐还是画画儿？", "D": "今晚吃得太饱了，吃了很多米饭，饭后还吃了三块西瓜。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "那儿一年四季都像春天一样，哪个季节去都很舒服。"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 22, "zh": "我也没少吃，我们出去走走，运动运动吧。", "options": {"A": "你几点来都可以，明天上午我不忙。", "B": "这次是我叔叔病了，我要去医院照顾他。", "C": "月月，你有什么爱好？喜欢音乐还是画画儿？", "D": "今晚吃得太饱了，吃了很多米饭，饭后还吃了三块西瓜。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "那儿一年四季都像春天一样，哪个季节去都很舒服。"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 23, "zh": "什么时候去那个城市旅游比较好？", "options": {"A": "你几点来都可以，明天上午我不忙。", "B": "这次是我叔叔病了，我要去医院照顾他。", "C": "月月，你有什么爱好？喜欢音乐还是画画儿？", "D": "今晚吃得太饱了，吃了很多米饭，饭后还吃了三块西瓜。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "那儿一年四季都像春天一样，哪个季节去都很舒服。"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 24, "zh": "听说你又去跟经理请假了？", "options": {"A": "你几点来都可以，明天上午我不忙。", "B": "这次是我叔叔病了，我要去医院照顾他。", "C": "月月，你有什么爱好？喜欢音乐还是画画儿？", "D": "今晚吃得太饱了，吃了很多米饭，饭后还吃了三块西瓜。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "那儿一年四季都像春天一样，哪个季节去都很舒服。"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 25, "zh": "我的爱好很多，对什么都很感兴趣。", "options": {"A": "你几点来都可以，明天上午我不忙。", "B": "这次是我叔叔病了，我要去医院照顾他。", "C": "月月，你有什么爱好？喜欢音乐还是画画儿？", "D": "今晚吃得太饱了，吃了很多米饭，饭后还吃了三块西瓜。", "E": "当然。我们先坐公共汽车，然后换地铁。", "F": "那儿一年四季都像春天一样，哪个季节去都很舒服。"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第26–30题：选择合适的词语填空", "instruction_en": "Questions 26-30: Choose the proper words to fill in the brackets.", "word_bank": [["A 办法", "B 一共", "C 决定", "D 渴", "E 声音", "F 选择"]], "items": [{"n": "例", "zh": "她说话的（　）多好听啊！", "options": {"A": "办法", "B": "一共", "C": "决定", "D": "渴", "E": "声音", "F": "选择"}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [120]}}, {"n": 26, "zh": "我（　）找个老师，下课以后帮我练习练习汉语。", "options": {"A": "办法", "B": "一共", "C": "决定", "D": "渴", "E": "声音", "F": "选择"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 27, "zh": "不是什么时间锻炼身体都好，必须（　）“对”的时间。", "options": {"A": "办法", "B": "一共", "C": "决定", "D": "渴", "E": "声音", "F": "选择"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 28, "zh": "我买了两双皮鞋，三条裤子，（　）是一千块。", "options": {"A": "办法", "B": "一共", "C": "决定", "D": "渴", "E": "声音", "F": "选择"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 29, "zh": "A：你怎么总是这么瘦，你有什么好（　）吗？ B：我也不知道，其实我吃得不少。", "options": {"A": "办法", "B": "一共", "C": "决定", "D": "渴", "E": "声音", "F": "选择"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 30, "zh": "A：我太（　）了，快把饮料给我。 B：运动以后不能马上喝水，你休息一会儿再喝吧。", "options": {"A": "办法", "B": "一共", "C": "决定", "D": "渴", "E": "声音", "F": "选择"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第31–35题：选择正确答案", "instruction_en": "Questions 31-35: Choose the right answers.", "items": [{"n": "例", "zh": "您是来参加今天会议的吗？您来早了一点儿，现在才八点半。您先进来坐吧。 ★会议最可能几点开始？", "options": {"A": "8点", "B": "8点半", "C": "9点"}, "answer": "C", "answer_ref": {"book": "workbook", "pages": [121]}}, {"n": 31, "zh": "我刚来这儿工作的时候，谁都不认识，哪儿都不了解。每天一个人上班，一个人回家，周末哪儿也不去。现在不一样了，我和公司的同事经常一起开车出去玩儿，下了班还一起去体育馆运动运动，每天都特别开心。 ★我以前：", "options": {"A": "认识很多人", "B": "经常出去玩儿", "C": "对这个地方不太了解"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 32, "zh": "考大学时，很多学生都不知道自己要上哪个大学。他们经常看别人选什么，自己就选什么。其实，要根据自己的兴趣和爱好选择大学和学什么，谁都不能帮你做决定，因为没有人比你更了解自己。 ★选择大学：", "options": {"A": "要根据兴趣", "B": "要看别人怎么做", "C": "要请爸爸妈妈决定"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 33, "zh": "我三岁大的女儿走到哪儿都要带着一本叫《小狗笑笑》的故事书，看见谁都要讲讲书里的故事。虽然书上的字她还不能都看懂，但是经常看着画儿讲给我听。现在，我也很喜欢笑笑，它长得可爱极了，谁见了它都喜欢。 ★我女儿：", "options": {"A": "喜爱《小狗笑笑》", "B": "只给妈妈讲故事", "C": "不认识字"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 34, "zh": "谁都知道健康很重要，怎么吃最健康呢？中国有句话叫“早吃好，午吃饱，晚吃少”。早饭后人们开始一天的学习和工作，所以一定要吃得好。一般来说，牛奶和鸡蛋是不错的选择。下午还要工作、学习，所以午饭不能少吃，要吃得饱一点儿。晚饭不是吃多少都可以，也不是几点吃都可以。因为饭后不久就要睡觉了，所以要早点儿吃，也不能多吃。 ★根据这段话，可以知道：", "options": {"A": "早饭要早点儿吃", "B": "吃了晚饭就应该睡觉", "C": "中午一定要吃饱"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 35, "zh": "我爷爷是个热心人，谁的忙他都愿意帮。谁的车坏了，哪家的孩子病了，谁的狗找不到了，爷爷都过去帮忙。他常说：大家都是邻居，帮忙是应该的。如果遇到问题，没有人愿意帮忙，人和人的关系就越来越远了。 ★爷爷：", "options": {"A": "遇到了问题", "B": "经常帮别人", "C": "不知道要帮谁"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "三、书写 第一部分", "type_zh": "书写 第一部分", "instruction_zh": "第36–40题：连词成句", "instruction_en": "Questions 36-40: Rearrange the words/phrases to make sentences.", "items": [{"n": "例", "zh": "小船　上　一　河　条　有", "answer": "河上有一条小船。", "answer_ref": {"book": "workbook", "pages": [122]}}, {"n": 36, "zh": "去　哪儿　都　妻子　没　过", "answer": "妻子哪儿都没去过。", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 37, "zh": "名字　他的　都　谁　知道", "answer": "谁都知道他的名字。", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 38, "zh": "可以　都　怎么　我们　去　那儿", "answer": "我们怎么去那儿都可以。", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 39, "zh": "喝　什么　现在　妹妹　都　不　想", "answer": "现在妹妹什么都不想喝。", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 40, "zh": "时候　打电话　我　给　什么　你　可以　都", "answer": "你什么时候给我打电话都可以。", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "三、书写 第二部分", "type_zh": "书写 第二部分", "instruction_zh": "第41–45题：看拼音，写汉字", "instruction_en": "Questions 41-45: Write the characters based on their pinyin.", "items": [{"n": "例", "zh": "没（　）系，别难过，高兴点儿。", "hint_zh": "guān", "answer": "关", "answer_ref": {"book": "workbook", "pages": [122]}}, {"n": 41, "zh": "经理，我想请一个星期（　），可以吗？", "hint_zh": "jià", "answer": "假", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 42, "zh": "明天一（　）8个人去机场，我们需要两辆车。", "hint_zh": "gòng", "answer": "共", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 43, "zh": "我想快点儿提高汉语水平，你有什么好办（　）吗？", "hint_zh": "fǎ", "answer": "法", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 44, "zh": "在这家公司工作了几年后，她（　）定找一个新工作。", "hint_zh": "jué", "answer": "决", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 45, "zh": "这个地方的（　）天很舒服，一点儿也不冷。", "hint_zh": "dōng", "answer": "冬", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "三、书写 第三部分", "type_zh": "书写 第三部分", "instruction_zh": "第46–50题：辨认汉字，选择正确的汉字填空", "instruction_en": "Questions 46-50: Distinguish the characters and fill in the blanks.", "items": [{"n": "例", "zh": "我不知道________个地方在________儿。", "hint_zh": "（那、哪）", "answer": "那、哪", "answer_ref": {"book": "workbook", "pages": [123]}}, {"n": 46, "zh": "根________邻________说的话，大家很快就找到了那个孩子。", "hint_zh": "（居、据）", "answer": "据、居", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 47, "zh": "你刚吃________，最好不要马上________步，对身体不好。", "hint_zh": "（饱、跑）", "answer": "饱、跑", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 48, "zh": "天黑，路不好走，我有点儿担________女儿，所以________须出去看看。", "hint_zh": "（必、心）", "answer": "心、必", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 49, "zh": "你不是口________了吗？我带了冰茶，给你________点儿。", "hint_zh": "（喝、渴）", "answer": "渴、喝", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 50, "zh": "如果要________车，一定要________择一家服务好的店，不能只想着便宜。", "hint_zh": "（选、洗）", "answer": "洗、选", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "三、书写 第四部分", "type_zh": "书写 第四部分", "instruction_zh": "第51–54题：用下边的汉字组词", "instruction_en": "Questions 51-54: Make words using the following characters.", "items": [{"n": "例", "zh": "找________、________", "answer": "找人、找到", "answer_ref": {"book": "workbook", "pages": [123]}}, {"n": 51, "zh": "园________、________", "answer": "公园、花园", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 52, "zh": "病________、________", "answer": "生病、有病", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 53, "zh": "问________、________", "answer": "问题、问你", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 54, "zh": "闻________、________", "answer": "新闻、听闻", "answer_ref": {"book": "teacher", "pages": [193]}}]}, {"n": "四、复习", "type_zh": "复习", "instruction_zh": "第1–2题：根据课文内容填空", "instruction_en": "Questions 1-2: Fill in the blanks based on the texts in the textbook.", "items": [{"n": 1, "zh": "小丽的同事很想认识那个高高的男人，就问小丽对他是不是________。小丽告诉同事他们过去是________，后来是大学同学，那个男人有很多________，________都会。但是小丽不能把他介绍给同事，因为他现在是小丽的________。", "answer": "了解、邻居、爱好、什么、丈夫", "answer_ref": {"book": "teacher", "pages": [193]}}, {"n": 2, "zh": "周太太最近觉得哪儿都不舒服，想去医院________。周经理觉得________有办法看好她的“病”，因为太太三年没运动了，每天吃________了就睡。________健康，周太太决定从明天起每天去长跑，________。", "answer": "检查检查、谁都、饱、为了、多锻炼锻炼", "answer_ref": {"book": "teacher", "pages": [193]}}]}], "answers_ref": {"book": "teacher", "pages": [191, 192, 193]}}, "audio": {"textbook": ["hsk3-textbook-1701.mp3", "hsk3-textbook-1702.mp3", "hsk3-textbook-1703.mp3", "hsk3-textbook-1704.mp3", "hsk3-textbook-1705.mp3"], "workbook": ["hsk3-workbook-17-part1.mp3", "hsk3-workbook-17-part2.mp3", "hsk3-workbook-17-part3.mp3", "hsk3-workbook-17-part4.mp3"]}, "unclear": ["Сурах бичиг: 课文1 ба 课文2 хоёулаа «在公司 / In the company» гарчигтай; 课文4-т гарчиг байхгүй (зөвхөн «4») — title_zh талбаргүй.", "Сурах бичгийн 拼音课文-ын гарчгийн пиньинь (Zài gōngsī / Zài gōngsī / Zài jiā) болон ярилцагчийн нэрийн пиньинь (Xiǎolì, Zhōu Míng, tóngshì, Zhōu tàitai) схемд талбаргүй тул lines.pinyin-д зөвхөн яриаг оруулсан. 课文4-ийн бичвэрийг өгүүлбэрээр мөр болгон хуваасан.", "Сурах бичиг PDF х.161 生词 11 «冬(天) dōng (tiān)» — хаалттай хэвлэгдсэн, номд байгаагаар; 热身-д «冬天 dōngtiān». 生词 14 情况 * тэмдэгтэй. Энэ хичээлд 专有名词 хүснэгт болон 文化 хэсэг байхгүй.", "Сурах бичиг PDF х.162 注释1 жишээ (4) «我真应该多锻炼锻炼了。» ба 注释2 жишээ (4) «最近我觉得哪儿都不舒服。» өнгөөр (улаан) ялгагдсан — 课文3-аас авсан жишээ; талбар байхгүй тул тэмдэглээгүй. 注释1-ийн structure_rows «ABAB» нь тайлбар дахь томьёо (номд тусдаа хүснэгт биш); 注释2-т бүтцийн хүснэгт байхгүй.", "Сурах бичиг PDF х.165 汉字知识 хүснэгтийн англи гарчиг «Pronounciation» (Pronunciation биш) — номд байгаагаар.", "Сурах бичиг PDF х.165 汉字知识: 园-ийн 形旁 хүснэгтэд том дөрвөлжин хэлбэрээр (囗) хэвлэгдсэн, 问-ийн 形旁 жижиг «口» — хоёр глиф зурагт маш төстэй; 园-д 囗, 问-д 口 гэж оруулсан. Багшийн ном PDF х.121 «园：形旁是“口”» гэж 口 хэлбэрээр хэвлэсэн — номд байгаагаар teacher.steps-д.", "Багшийн ном PDF х.121 汉字 хэсэгт 声旁-ийн пиньинийг «元（yuan）», «丙（bing）», «门（men）» гэж хөгийн тэмдэггүй хэвлэсэн; сурах бичиг «元（yuán）», «丙（bǐng）», «门（mén）». Номд байгаагаар тус тусад нь.", "Багшийн ном PDF х.121–122: нэмэлт жишээ «外形内声…如：房» ба «内形外声…如：闷» (300 dpi-аар шалгасан) — номд байгаагаар teacher.steps-д.", "Багшийн ном PDF х.120 课文1 асуулт-хариулт «她的一个老朋友下个星期结婚，她们两年没见了。» — сурах бичгийн 课文1-д «我的一个老朋友结婚，我跟他两年没见了» (他, «下个星期» нь чөлөөний хугацаа). Номд байгаагаар.", "Багшийн ном PDF х.117 功能 «用双音动词重叠形式描述动作» ба PDF х.118 «引导学生说出双音动词重叠形式» — «双音节» биш «双音» гэж хэвлэгдсэн; номд байгаагаар.", "Багшийн номын 汉字练习 组词 参考答案 (PDF х.122: 园—花园、公园；病—生病、看病；问—问题、请问；闻—新闻) ба дасгалын номын 51–54-ийн хавсралтын 参考答案 (PDF х.193: 公园、花园；生病、有病；问题、问你；新闻、听闻) ялгаатай — хоёуланг номд байгаагаар; 51–54-ийн answer-т хавсралтынхыг.", "Дасгалын ном №10: дасгалын номд «★有三个同学要介绍自己。» (PDF х.118), хавсралтад «★有3个同学要介绍自己。» (PDF х.192) — item.zh-д дасгалын номынхыг.", "Сурах бичгийн 练一练 (2 дүрэм × 3), 练习2 选词填空 / 练习3 描述图片 / 练习4 回答问题, 热身2, 运用 — хариулт сурах бичиг, багшийн номд хэвлэгдээгүй тул answer талбаргүй. Багшийн номын 课文 асуулт-хариулт (teacher.text_questions) нь 练习4-ийн асуултаас өөр асуултууд; 课文4-ийн «运动的时候要注意哪三点？» асуултын хариулт хэвлэгдээгүй.", "Багшийн номын 汉字辨认练习 (居/据 · 饱/跑 · 必/心 · 喝/渴 · 选/洗 — 组词) хоосон зайтай, хариулт хэвлэгдээгүй. Багшийн номын 语言点 扩展练习-ийн гүйцээх өгүүлбэрүүд мөн хариултгүй.", "Багшийн номын «练习册相关练习：第113页／一／第一部分，第116页／二／第二部分», «第120页／四», «第119页／三／第三部分» — дасгалын номын хэвлэсэн хуудасны дугаар (PDF х.117, 120, 124, 123); «课本第149页» — сурах бичгийн хэвлэсэн хуудас (PDF х.165).", "Дасгалын номын сонсгол нэг CD тэмдэгтэй (17) — аудиог hsk3-workbook-17-part1…4.mp3 болгож хэсэг тус бүрт хуваасныг section.audio-д оноосон.", "Дасгалын ном 听力 第一部分 1–5-д номд текст байхгүй (зөвхөн дугаар + хайрцаг) тул zh хоосон; 第三/四部分-д номд зөвхөн сонголтууд хэвлэгдсэн — item.zh-д багшийн номын хавсралтын «问：» асуултыг оруулсан (transcript_zh-д бүтнээр).", "Сурах бичиг 运用 小组活动-ийн доор 4 хоосон бичих мөр байгаа — example_zh-д «（书中另有4条空白横线供书写）» гэж тэмдэглэсэн (номын текст биш).", "Дасгалын ном №51–54-ийн хариулт багшийн номын «参考答案» (өөр зөв хувилбар байж болно).", "HSK 3.0 нэмэлт үгс (BLCUP 课件 补充HSK3.0, слайд 5, 21, 31 — үг; слайд 7, 32 — 语言点) hsk30-д."], "verified_pages": [117, 118, 119, 120, 121, 122, 123, 124, 159, 160, 161, 162, 163, 164, 165, 166, 191, 192, 193], "schema_version": 1, "hsk30": {"source": "courseware", "ref": {"book": "hsk30_courseware", "pages": [5, 7, 21, 31, 32]}, "new_words": [{"n": 1, "zh": "放假", "pinyin": "fàngjià", "pos": "v.", "en": "have a holiday", "text": 1}, {"n": 2, "zh": "放学", "pinyin": "fàngxué", "pos": "v.", "en": "finish school", "text": 1}, {"n": 3, "zh": "喜爱", "pinyin": "xǐ''ài", "pos": "v.", "en": "like", "text": 2}, {"n": 4, "zh": "住院", "pinyin": "zhùyuàn", "pos": "v.", "en": "be in hospital", "text": 3}, {"n": 5, "zh": "出院", "pinyin": "chūyuàn", "pos": "v.", "en": "discharge", "text": 3}, {"n": 6, "zh": "病人", "pinyin": "bìngrén", "pos": "n.", "en": "patient", "text": 3}, {"n": 7, "zh": "跳", "pinyin": "tiào", "pos": "v.", "en": "jump", "text": 4}], "grammar": [{"n": 1, "title_zh": "请假", "explanation_zh": "", "examples": [{"zh": "下个星期我可以请几天假吗？"}, {"zh": "我一共想请两天假。"}, {"zh": "我有点儿不舒服，想请病假。"}, {"zh": "请帮我把请假条带给经理。"}]}, {"n": 2, "title_zh": "必须VS一定", "explanation_zh": "", "structure_rows": ["必须／一定", "不必／不须／无(wú)须", "不一定"], "examples": [{"zh": "必须／一定要根据自己的健康情况运动。"}, {"zh": "我必须完成作业。"}, {"zh": "我一定完成作业。"}]}], "exercises": [], "unclear": ["语言点 «短跑／长跑» слайд (23-р слайд) — зөвхөн хоёр үг, жишээ өгүүлбэргүй тул hsk30.grammar-т ороогүй."]}}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
